--
-- Name: add_plan_visit(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_plan_visit(p_plan_id uuid, p_scheduled_at timestamp with time zone, p_duration_minutes integer) RETURNS public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare last_visit public.appointments;
declare crew uuid[];
declare services uuid[];
declare created public.appointments;
begin
  perform public.assert_office();

  select * into last_visit from public.appointments
  where plan_id = p_plan_id and status <> 'Cancelled'
  order by scheduled_at desc limit 1;
  if last_visit.id is null then raise exception 'That plan has no visits left to follow.'; end if;
  if p_scheduled_at < last_visit.scheduled_at + make_interval(mins => last_visit.duration_minutes) then
    raise exception 'The new day must start after the current last day ends.';
  end if;
  if last_visit.status = 'Completed' then
    raise exception 'This job is already completed.';
  end if;

  select array_agg(technician_id order by is_lead desc, assigned_at) into crew
  from public.appointment_technicians where appointment_id = last_visit.id;
  select array_agg(service_id order by position) into services
  from public.appointment_services where appointment_id = last_visit.id and service_id is not null;

  select * into created from public.create_appointment(
    last_visit.client_id, p_scheduled_at, p_duration_minutes,
    last_visit.pest_concern, last_visit.service_type, last_visit.service_location,
    crew, last_visit.notes, last_visit.service_frequency, null, last_visit.service_id
  );

  update public.appointments
    set plan_id = p_plan_id,
        plan_position = (select coalesce(max(plan_position), 0) + 1 from public.appointments where plan_id = p_plan_id)
    where id = created.id;
  if services is not null then perform public.set_appointment_services(created.id, services); end if;

  select * into created from public.appointments where id = created.id;
  return created;
end;
$$;


--
-- Name: add_system_log(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_system_log(p_type text, p_message text, p_session_token uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  token uuid;
  account_id uuid;
  account_role text;
  account_name text;
  created uuid;
begin
  token := coalesce(p_session_token, nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid);

  select r.id, r.role_name into account_id, account_role
  from public.role_account_for_session(token) r
  limit 1;
  if account_id is null then raise exception 'Not signed in.'; end if;

  select coalesce(a.name, s.name, t.name) into account_name
  from (select account_id as id) me
  left join public.admins a on a.id = me.id
  left join public.staff s on s.id = me.id
  left join public.technicians t on t.id = me.id;

  if p_type is null or p_type not in ('auth', 'admin', 'client', 'document', 'inventory') then
    raise exception 'Unknown activity type.';
  end if;
  if nullif(trim(coalesce(p_message, '')), '') is null then
    raise exception 'An activity entry needs a message.';
  end if;

  insert into public.system_logs (actor_id, actor_name, actor_role, type, message)
  values (account_id, coalesce(account_name, 'Unknown account'), account_role, p_type, left(trim(p_message), 500))
  returning id into created;

  return created;
end;
$$;


