    CONSTRAINT contracts_deposit_type_check CHECK ((deposit_type = ANY (ARRAY['NONE'::text, 'AMOUNT'::text, 'PERCENT'::text]))),
    CONSTRAINT contracts_length CHECK (((visit_count IS NOT NULL) OR (ends_on IS NOT NULL))),
    CONSTRAINT contracts_payment_terms_check CHECK ((payment_terms = ANY (ARRAY['DUE_ON_RECEIPT'::text, 'NET_15'::text, 'NET_30'::text]))),
    CONSTRAINT contracts_price_per_visit_check CHECK (((price_per_visit >= (0)::numeric) AND (price_per_visit <= 999999.99))),
    CONSTRAINT contracts_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'ENDED'::text, 'CANCELLED'::text]))),
