--
-- Name: attach_contract_document(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attach_contract_document(p_contract_id uuid, p_document_id uuid) RETURNS public.contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.contracts;
begin
  perform public.assert_billing_office();
  select * into target from public.contracts c where c.id = p_contract_id for update;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  if target.status in ('ENDED', 'CANCELLED') then raise exception 'Contract % is %.', target.reference, lower(target.status); end if;
  if not exists (select 1 from public.client_documents d where d.id = p_document_id and d.client_id = target.client_id) then
    raise exception 'That document is not in this client''s files.';
  end if;
  update public.contracts c set signed_document_id = p_document_id, updated_at = now()
  where c.id = target.id returning * into target;
  return target;
end;
$$;


--
-- Name: billing_actor_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_actor_name() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(a.name, s.name, t.name)
  from (select public.current_account_id() as id) me
  left join public.admins a on a.id = me.id
  left join public.staff s on s.id = me.id
  left join public.technicians t on t.id = me.id;
$$;


--
-- Name: book_appointments(text, jsonb, uuid, text, uuid[], text, uuid[], text, text, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_appointments(p_kind text, p_visits jsonb, p_client_id uuid, p_pest_concern text, p_service_ids uuid[], p_service_location text, p_technician_ids uuid[], p_notes text, p_service_frequency text, p_price numeric, p_skip_sundays boolean DEFAULT true) RETURNS SETOF public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  new_plan_id    uuid;
  visit          record;
  created        public.appointments;
  position_no    integer := 0;
  visit_count    integer;
  first_service  uuid;
  service_names  text;
  visit_price    numeric;
  visit_frequency text;
  previous_end   timestamptz;
begin
  perform public.assert_office();

  if p_kind is not null and p_kind not in ('RECURRING', 'MULTI_DAY') then
    raise exception 'Unknown plan type.';
  end if;
  if p_visits is null or jsonb_typeof(p_visits) <> 'array' then
    raise exception 'The visits must be a list.';
  end if;
  visit_count := jsonb_array_length(p_visits);
  if visit_count = 0 then raise exception 'Add at least one visit.'; end if;
  if visit_count > 60 then raise exception 'A plan can hold at most 60 visits.'; end if;
  if p_kind is null and visit_count > 1 then
    raise exception 'Several visits need a recurring plan or a multi-day job.';
  end if;
  if p_kind is not null and visit_count < 2 then
    raise exception 'A plan needs at least two visits.';
  end if;
  if p_kind = 'RECURRING' and coalesce(p_service_frequency, 'One-time') = 'One-time' then
    raise exception 'Choose how often the service repeats.';
  end if;

  -- The services: the first is service_id, the names joined are service_type.
  if p_service_ids is not null and cardinality(p_service_ids) > 0 then
    if exists (
      select 1 from unnest(p_service_ids) as ids(id)
      where ids.id is null or not exists (select 1 from public.services s where s.id = ids.id)
    ) then
      raise exception 'One of those services no longer exists. Choose again.';
    end if;
    first_service := p_service_ids[1];
    select string_agg(s.name, ', ' order by ids.ord) into service_names
    from unnest(p_service_ids) with ordinality as ids(id, ord)
    join public.services s on s.id = ids.id;
  end if;

  if p_kind is not null then
    insert into public.appointment_plans (kind, client_id, frequency, skip_sundays, created_by)
    values (
      p_kind, p_client_id,
      case when p_kind = 'RECURRING' then p_service_frequency end,
      coalesce(p_skip_sundays, true),
      public.current_account_id()
    )
    returning id into new_plan_id;
  end if;

  for visit in
    select (entry->>'scheduled_at')::timestamptz as scheduled_at,
           (entry->>'duration_minutes')::integer as duration_minutes
    from jsonb_array_elements(p_visits) as entry
    order by (entry->>'scheduled_at')::timestamptz
  loop
    position_no := position_no + 1;

    -- A multi-day job's days follow one another; they never overlap.
    if p_kind = 'MULTI_DAY' and previous_end is not null and visit.scheduled_at < previous_end then
      raise exception 'Day % starts before Day % ends.', position_no, position_no - 1;
    end if;
    previous_end := visit.scheduled_at + make_interval(mins => visit.duration_minutes);

    -- Recurring: every visit is charged. Multi-day: the job is charged once,
    -- on Day 1, so totals and revenue count it once.
    visit_price := case when p_kind = 'MULTI_DAY' and position_no > 1 then null else p_price end;
    visit_frequency := case when p_kind = 'MULTI_DAY' then 'One-time' else p_service_frequency end;

    select * into created from public.create_appointment(
      p_client_id, visit.scheduled_at, visit.duration_minutes,
      p_pest_concern, service_names, p_service_location,
      p_technician_ids, p_notes, visit_frequency, visit_price, first_service
    );

    if new_plan_id is not null then
      update public.appointments set plan_id = new_plan_id, plan_position = position_no where id = created.id;
    end if;
    if p_service_ids is not null and cardinality(p_service_ids) > 0 then
      perform public.set_appointment_services(created.id, p_service_ids);
    end if;

    return query select * from public.appointments where id = created.id;
  end loop;
end;
$$;


--
-- Name: book_follow_up_from_report(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_follow_up_from_report(p_appointment_id uuid) RETURNS TABLE(status text, appointment_id uuid, reference text, message text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_original public.appointments;
  v_date date;
  v_service public.services;
  v_price numeric;
  v_crew uuid[];
  v_start timestamptz;
  v_created public.appointments;
  v_today date := (now() at time zone 'Asia/Manila')::date;
  v_contract uuid;
  v_until date;
  v_source_type text;
  v_source_id uuid;
begin
  if not public.has_role_table_session() then
    return query select 'NOT_ALLOWED'::text, null::uuid, null::text, 'Not signed in.'::text; return;
  end if;
  select * into v_original from public.appointments a where a.id = p_appointment_id;
  if v_original.id is null then
    return query select 'NOT_ALLOWED'::text, null::uuid, null::text, 'That visit was not found.'::text; return;
  end if;
  if coalesce(public.current_account_role(), '') not in ('ADMIN', 'STAFF')
     and not public.is_assigned_to_appointment(v_original.id) then
    return query select 'NOT_ALLOWED'::text, null::uuid, null::text, 'Only the office or the visit''s crew can book its follow-up.'::text; return;
  end if;

  select r.follow_up_date into v_date from public.appointment_reports r where r.appointment_id = v_original.id;
  if v_date is null then
    return query select 'NO_DATE'::text, null::uuid, null::text, 'No follow-up date on the report.'::text; return;
  end if;
  if v_date < v_today then
    return query select 'PAST'::text, null::uuid, null::text, 'The follow-up date has passed, so it was not booked.'::text; return;
  end if;
  -- 080: a follow-up checks on the visit, so never before it.
  if v_date < (v_original.scheduled_at at time zone 'Asia/Manila')::date then
    return query select 'PAST'::text, null::uuid, null::text, 'The follow-up date is before the visit itself, so it was not booked.'::text; return;
  end if;

  -- Under a running warranty the follow-up is a free re-treatment.
  if v_original.plan_id is not null then
    select c.id into v_contract from public.contracts c where c.plan_id = v_original.plan_id limit 1;
  end if;
  v_contract := coalesce(v_original.warranty_contract_id, v_contract);
  if v_contract is not null then
    select w.ends_on into v_until from public.warranty_window('CONTRACT', v_contract) w;
    if v_until is not null and v_date <= v_until then v_source_type := 'CONTRACT'; v_source_id := v_contract; end if;
  end if;
  if v_source_id is null and coalesce(v_original.quote_id, v_original.warranty_quote_id) is not null then
    select w.ends_on into v_until from public.warranty_window('QUOTE', coalesce(v_original.quote_id, v_original.warranty_quote_id)) w;
    if v_until is not null and v_date <= v_until then v_source_type := 'QUOTE'; v_source_id := coalesce(v_original.quote_id, v_original.warranty_quote_id); end if;
  end if;

  if v_source_id is null and v_original.quote_id is null then
    return query select 'NO_QUOTE'::text, null::uuid, null::text,
      'The visit was not booked under a quotation, so the office books its follow-up.'::text; return;
  end if;
  if exists (select 1 from public.appointments f where f.follow_up_of = v_original.id and f.status <> 'Cancelled') then
    return query select 'ALREADY'::text, f.id, f.reference, 'A follow-up of this visit is already booked.'::text
      from public.appointments f where f.follow_up_of = v_original.id and f.status <> 'Cancelled'
      order by f.scheduled_at limit 1;
    return;
  end if;

  select * into v_service from public.services s
  where s.system_key = 'FOLLOW_UP' and s.is_active;
  if v_service.id is null then
    return query select 'NO_SERVICE'::text, null::uuid, null::text, 'There is no Follow-up Visit service in the catalog.'::text; return;
  end if;

  if v_source_id is not null then
    v_price := 0;
  else
    select case when count(*) = 0 then v_service.default_price
                else sum(coalesce(s.follow_up_price, v_service.default_price)) end
      into v_price
    from public.appointment_services aps
    left join public.services s on s.id = aps.service_id
    where aps.appointment_id = v_original.id;
    if v_price is null and v_original.service_id is not null then
      select coalesce(s.follow_up_price, v_service.default_price) into v_price from public.services s where s.id = v_original.service_id;
    end if;
  end if;

  select coalesce(array_agg(t.technician_id order by t.is_lead desc, t.assigned_at), array[]::uuid[]) into v_crew
  from public.appointment_technicians t where t.appointment_id = v_original.id;
  if cardinality(v_crew) = 0 and v_original.technician_id is not null then v_crew := array[v_original.technician_id]; end if;

  v_start := (v_date::timestamp + time '09:00') at time zone 'Asia/Manila';
  if v_start < now() then
    v_start := date_trunc('hour', now()) + interval '1 hour';
    if (v_start at time zone 'Asia/Manila')::date <> v_date then
      return query select 'PAST'::text, null::uuid, null::text, 'Too late today to book the follow-up.'::text; return;
    end if;
  end if;

  begin
    v_created := public.create_appointment(
      v_original.client_id, v_start, coalesce(v_service.default_duration_minutes, 60),
      v_original.pest_concern, v_service.name, v_original.service_location, v_crew,
      'Follow-up of ' || coalesce(v_original.reference, 'a visit') || ', booked from its report.'
        || case when v_source_id is not null then ' Covered by warranty until ' || to_char(v_until, 'Mon DD, YYYY') || ': no charge.' else '' end,
      'One-time', v_price, v_service.id
    );
  exception when others then
    return query select 'REFUSED'::text, null::uuid, null::text, sqlerrm::text; return;
  end;

  -- 082: only the warranty functions may set a visit's warranty link.
  perform set_config('app.warranty_link', 'on', true);
  update public.appointments a
    set follow_up_of = v_original.id,
        quote_id = v_original.quote_id,
        warranty_kind = case when v_source_id is not null then 'RETREATMENT' end,
        warranty_quote_id = case when v_source_type = 'QUOTE' then v_source_id end,
        warranty_contract_id = case when v_source_type = 'CONTRACT' then v_source_id end
    where a.id = v_created.id;

  return query select 'BOOKED'::text, v_created.id, v_created.reference,
    ('Follow-up ' || coalesce(v_created.reference, '') || ' booked for ' || to_char(v_start at time zone 'Asia/Manila', 'Mon DD, HH12:MI AM') || ' (Pending)'
      || case when v_source_id is not null then ', free under warranty.' else '.' end)::text;
end;
$$;


--
-- Name: book_warranty_visits(text, text, uuid, jsonb, uuid[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_warranty_visits(p_kind text, p_source_type text, p_source_id uuid, p_visits jsonb, p_technician_ids uuid[], p_reason text DEFAULT NULL::text) RETURNS SETOF public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_kind text := upper(coalesce(p_kind, ''));
  v_type text := upper(coalesce(p_source_type, ''));
  v_starts date;
  v_ends date;
  v_client uuid;
  v_reference text;
  v_location text;
  v_service public.services;
  v_service_ids uuid[];
  v_service_name text;
  entry record;
  v_day date;
  created public.appointments;
begin
  perform public.assert_billing_office();
  if v_kind not in ('CHECKUP', 'RETREATMENT') then raise exception 'Book a checkup or a warranty re-treatment.'; end if;
  if v_type not in ('QUOTE', 'CONTRACT') then raise exception 'A warranty belongs to a quotation or a contract.'; end if;
  if v_kind = 'RETREATMENT' and nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'Write what came back, for the re-treatment.';
  end if;
  if p_visits is null or jsonb_typeof(p_visits) <> 'array' or jsonb_array_length(p_visits) = 0 then
    raise exception 'Choose at least one date.';
  end if;
  if jsonb_array_length(p_visits) > 60 then raise exception 'Book at most 60 visits at a time.'; end if;

  select w.starts_on, w.ends_on into v_starts, v_ends from public.warranty_window(v_type, p_source_id) w;
  if v_starts is null then
    raise exception 'That warranty has not started: a contract''s starts when it is signed, a quotation''s when its job is completed.';
  end if;

  if v_type = 'CONTRACT' then
    select c.client_id, c.reference into v_client, v_reference from public.contracts c where c.id = p_source_id;
    select coalesce(array_agg(s), '{}') into v_service_ids from public.contracts c, unnest(c.service_ids) s where c.id = p_source_id;
  else
    select q.client_id, q.reference into v_client, v_reference from public.quotes q where q.id = p_source_id;
    select coalesce(array_agg(distinct l.service_id), '{}') into v_service_ids
    from public.quote_lines l where l.quote_id = p_source_id and l.service_id is not null;
  end if;
  select cl.address into v_location from public.clients cl where cl.id = v_client;

  if v_kind = 'CHECKUP' then
    select * into v_service from public.services s where s.system_key = 'CHECKUP' and s.is_active;
    if v_service.id is null then raise exception 'There is no Checkup service in the catalog.'; end if;
    v_service_name := v_service.name;
  else
    select string_agg(s.name, ', ' order by s.name) into v_service_name from public.services s where s.id = any(v_service_ids);
    select * into v_service from public.services s where s.id = v_service_ids[1];
  end if;

  for entry in
    select (e->>'scheduled_at')::timestamptz as scheduled_at, coalesce((e->>'duration_minutes')::integer, 60) as minutes
    from jsonb_array_elements(p_visits) e
    order by 1
  loop
    v_day := (entry.scheduled_at at time zone 'Asia/Manila')::date;
    if v_day < v_starts or v_day > v_ends then
      raise exception 'The warranty runs % to %; % is outside it.', to_char(v_starts, 'Mon DD, YYYY'), to_char(v_ends, 'Mon DD, YYYY'), to_char(v_day, 'Mon DD, YYYY');
    end if;
    created := public.create_appointment(
      v_client, entry.scheduled_at, entry.minutes, null,
      coalesce(v_service_name, case when v_kind = 'CHECKUP' then 'Checkup' else 'Warranty re-treatment' end),
      v_location, p_technician_ids,
      case when v_kind = 'CHECKUP'
        then 'Checkup under ' || coalesce(v_reference, 'the warranty') || ' (warranty until ' || to_char(v_ends, 'Mon DD, YYYY') || '). No charge.'
        else 'Warranty re-treatment under ' || coalesce(v_reference, 'the warranty') || ': ' || trim(p_reason) || ' No charge.' end,
      'One-time', 0, v_service.id
    );
  -- 082: only the warranty functions may set a visit's warranty link.
  perform set_config('app.warranty_link', 'on', true);
    update public.appointments a
      set warranty_kind = v_kind,
          warranty_quote_id = case when v_type = 'QUOTE' then p_source_id end,
          warranty_contract_id = case when v_type = 'CONTRACT' then p_source_id end
      where a.id = created.id;
    -- A re-treatment carries the job's services (051).
    if v_kind = 'RETREATMENT' and cardinality(v_service_ids) > 1
       and exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'appointment_services') then
      delete from public.appointment_services aps where aps.appointment_id = created.id;
      insert into public.appointment_services (appointment_id, position, service_id, service_name)
      select created.id, ord - 1, s.id, s.name
      from unnest(v_service_ids) with ordinality as ids(id, ord) join public.services s on s.id = ids.id;
    end if;
    return query select * from public.appointments a where a.id = created.id;
  end loop;
end;
$$;


--
-- Name: can_read_appointment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_appointment(p_technician_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when public.current_account_role() = 'TECHNICIAN'
      then p_technician_id is not null
       and p_technician_id = public.current_account_id()
    else public.has_role_table_session()
  end;
$$;


--
-- Name: can_read_appointment_row(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_appointment_row(p_appointment_id uuid, p_technician_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when public.current_account_role() = 'TECHNICIAN'
      then (p_technician_id is not null and p_technician_id = public.current_account_id())
        or public.is_assigned_to_appointment(p_appointment_id)
    else public.has_role_table_session()
  end;
$$;


--
-- Name: cancel_contract(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_contract(p_contract_id uuid, p_reason text) RETURNS public.contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.contracts;
  cancelled_count integer := 0;
begin
  perform public.assert_billing_office();
  if nullif(trim(coalesce(p_reason, '')), '') is null then raise exception 'Write why the contract is being cancelled.'; end if;
  select * into target from public.contracts c where c.id = p_contract_id for update;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  if target.status not in ('DRAFT', 'ACTIVE') then raise exception 'Contract % is already %.', target.reference, lower(target.status); end if;

  if target.plan_id is not null then
    update public.appointments a
      set status = 'Cancelled', cancellation_reason = 'Contract cancelled: ' || trim(p_reason)
      where a.plan_id = target.plan_id and a.scheduled_at > now()
        and a.status not in ('Completed', 'Cancelled', 'In progress');
    get diagnostics cancelled_count = row_count;
    update public.appointment_plans p set renewal_declined_at = coalesce(p.renewal_declined_at, now()) where p.id = target.plan_id;
  end if;

  update public.contracts c set
    status = 'CANCELLED', cancelled_at = now(), updated_at = now(),
    cancellation_reason = trim(p_reason) || case when cancelled_count > 0 then ' (' || cancelled_count || ' visit' || case when cancelled_count = 1 then '' else 's' end || ' cancelled)' else '' end
  where c.id = target.id
  returning * into target;
  return target;
end;
$$;


--
-- Name: cancel_plan_remaining(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_plan_remaining(p_plan_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cancelled_count integer;
begin
  perform public.assert_office();
  update public.appointments
    set status = 'Cancelled', cancellation_reason = 'Plan cancelled'
    where plan_id = p_plan_id and scheduled_at > now()
      and status not in ('Completed', 'Cancelled', 'In progress');
  get diagnostics cancelled_count = row_count;
  return cancelled_count;
end;
$$;


--
-- Name: change_password(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_password(session_token uuid, current_password text, new_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare caller record;
begin
  select * into caller from (
    select a.id, a.email, a.password, a.password_hash, 'admins'::text as table_name from sessions s join admins a on a.id=s.user_id where s.token=session_token and s.user_role='ADMIN' and a.status='ACTIVE'
    union all select a.id, a.email, a.password, a.password_hash, 'staff'::text from sessions s join staff a on a.id=s.user_id where s.token=session_token and s.user_role='STAFF' and a.status='ACTIVE'
    union all select a.id, a.email, a.password, a.password_hash, 'technicians'::text from sessions s join technicians a on a.id=s.user_id where s.token=session_token and s.user_role='TECHNICIAN' and a.status='ACTIVE'
  ) account limit 1;
  if caller.id is null then raise exception 'Not signed in.'; end if;
  if caller.password <> current_password and caller.password_hash <> crypt(current_password, caller.password_hash) then raise exception 'Current password is incorrect.'; end if;
  execute format('update %I set password = $1, password_hash = null where id = $2', caller.table_name) using new_password, caller.id;
end;
$_$;


--
-- Name: check_login(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_login(login_identifier text, login_password text) RETURNS TABLE(token uuid, id uuid, name text, email text, username text, phone text, role text, status public.account_status)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare found record; new_token uuid;
begin
  if nullif(login_password, '') is null then return; end if;
  if nullif(login_identifier, '') is null then return; end if;

  select * into found from (
    select a.id, a.name, a.username, a.phone, a.email, a.password, a.password_hash, a.status, 'ADMIN'::text role_name
      from admins a where lower(a.email)=lower(login_identifier) or lower(a.username)=lower(login_identifier)
    union all
    select s.id, s.name, s.username, s.phone, s.email, s.password, s.password_hash, s.status, 'STAFF'::text
      from staff s where lower(s.email)=lower(login_identifier) or lower(s.username)=lower(login_identifier)
    union all
    select t.id, t.name, t.username, t.phone, t.email, t.password, t.password_hash, t.status, 'TECHNICIAN'::text
      from technicians t where lower(t.email)=lower(login_identifier) or lower(t.username)=lower(login_identifier)
  ) accounts
  where accounts.status in ('ACTIVE', 'PENDING')
    and (
      (nullif(accounts.password, '') is not null and accounts.password = login_password)
      or
      (nullif(accounts.password_hash, '') is not null
       and accounts.password_hash = crypt(login_password, accounts.password_hash))
    )
  limit 1;
  if found.id is null then return; end if;

  execute format(
    'update %I set status = ''ACTIVE'', last_login_at = now() where id = $1',
    case found.role_name when 'ADMIN' then 'admins' when 'STAFF' then 'staff' else 'technicians' end
  ) using found.id;
  -- One device per account, except the accounts listed as shared.
  if not exists (select 1 from public.shared_login_accounts sla where sla.id = found.id) then
    delete from sessions where user_id = found.id;
  end if;
  insert into sessions (user_id, user_role) values (found.id, found.role_name) returning sessions.token into new_token;
  return query select new_token, found.id, found.name, found.email, coalesce(found.username, found.email), found.phone, found.role_name, 'ACTIVE'::account_status;
end;
$_$;


--
-- Name: checkout_remaining(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkout_remaining(p_checkout_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when c.custody_closed_at is not null then 0
              else c.amount - coalesce((select sum(m.amount) from public.inventory_movements m where m.checkout_id = c.id), 0)
         end
  from public.inventory_movements c
  where c.id = p_checkout_id and c.stock_out_reason = 'TECHNICIAN_CHECKOUT';
$$;


--
-- Name: clients_email_unique(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clients_email_unique() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_email text := lower(btrim(coalesce(new.email, '')));
  v_other record;
begin
  -- Store what was typed without the stray spaces.
  new.email := nullif(btrim(coalesce(new.email, '')), '');

  if v_email = '' then
    return new;
  end if;
  if tg_op = 'UPDATE' and v_email = lower(btrim(coalesce(old.email, ''))) then
    return new;
  end if;

  select id, name, reference, status into v_other
  from clients
  where id <> new.id
    and lower(btrim(email)) = v_email
  limit 1;

  if found then
    raise exception 'That email is already used by % (%)%. Each client needs their own email.',
      v_other.name,
      coalesce(v_other.reference, 'another client'),
      case when v_other.status::text = 'ARCHIVED' then ', an archived client' else '' end
      using errcode = 'unique_violation';
  end if;
  return new;
end;
$$;


--
-- Name: contract_deposit_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contract_deposit_paid(p_contract_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(p.amount), 0)
  from public.payments p
  where p.contract_id = p_contract_id and p.kind = 'DEPOSIT' and public.payment_counts(p);
$$;


--
-- Name: create_appointment(uuid, timestamp with time zone, integer, text, text, text, uuid[], text, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_appointment(p_client_id uuid, p_scheduled_at timestamp with time zone, p_duration_minutes integer, p_pest_concern text, p_service_type text, p_service_location text, p_technician_ids uuid[], p_notes text, p_service_frequency text, p_price numeric, p_service_id uuid DEFAULT NULL::uuid) RETURNS public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare created public.appointments;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if p_duration_minutes is null or p_duration_minutes < 1 or p_duration_minutes > 1440 then
    raise exception 'Duration must be between 1 minute and 24 hours.';
  end if;
  if not exists (select 1 from public.clients where id = p_client_id and status = 'ACTIVE') then
    raise exception 'Active client not found.';
  end if;
  if p_price is not null and p_price < 0 then raise exception 'Price cannot be negative.'; end if;
  -- 047: caps and the past-date rule. Five minutes of grace covers the time
  -- between opening the form on "now" and pressing Save.
  if p_price is not null and p_price > 999999.99 then
    raise exception 'Price cannot be more than 999,999.99.';
  end if;
  if p_scheduled_at is null or p_scheduled_at < now() - interval '5 minutes' then
    raise exception 'Appointments cannot be booked in the past.';
  end if;
  if p_service_id is not null and not exists (select 1 from public.services where id = p_service_id) then
    raise exception 'That service no longer exists.';
  end if;

  perform public.assert_technicians_available(null, p_technician_ids, p_scheduled_at, p_duration_minutes);

  insert into public.appointments (
    client_id, scheduled_at, duration_minutes, pest_concern, service_type,
    service_location, technician_id, notes, created_by, service_frequency, price,
    service_id
  )
  select p_client_id, p_scheduled_at, p_duration_minutes,
         nullif(trim(p_pest_concern), ''), nullif(trim(p_service_type), ''),
         nullif(trim(p_service_location), ''),
         (select ids.technician_id
          from unnest(coalesce(p_technician_ids, array[]::uuid[])) with ordinality as ids(technician_id, position)
          where ids.technician_id is not null
          order by ids.position limit 1),
         nullif(trim(p_notes), ''), r.id,
         nullif(trim(p_service_frequency), ''), p_price,
         p_service_id
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  limit 1
  returning * into created;

  perform public.set_appointment_technicians(created.id, p_technician_ids);

  select * into created from public.appointments where id = created.id;
  return created;
end;
$$;


--
-- Name: invoice_reference_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.invoice_reference_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: invoices; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reference text DEFAULT ('TPC-INV-'::text || lpad((nextval('public.invoice_reference_seq'::regclass))::text, 5, '0'::text)) NOT NULL,
    client_id uuid NOT NULL,
    quote_id uuid,
    status text DEFAULT 'ISSUED'::text NOT NULL,
    issued_on date NOT NULL,
    payment_terms text DEFAULT 'DUE_ON_RECEIPT'::text NOT NULL,
    due_on date NOT NULL,
    discount_type text DEFAULT 'AMOUNT'::text NOT NULL,
    discount_value numeric DEFAULT 0 NOT NULL,
    vat_mode text DEFAULT 'ADDED'::text NOT NULL,
    vat_rate numeric DEFAULT 12 NOT NULL,
    subtotal numeric DEFAULT 0 NOT NULL,
    discount_amount numeric DEFAULT 0 NOT NULL,
    vat_amount numeric DEFAULT 0 NOT NULL,
    total numeric DEFAULT 0 NOT NULL,
    deposit_applied numeric DEFAULT 0 NOT NULL,
    amount_due numeric DEFAULT 0 NOT NULL,
    notes text,
    created_by uuid,
    created_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    voided_at timestamp with time zone,
    voided_by uuid,
    void_reason text,
    contract_id uuid,
    CONSTRAINT invoices_amount_due_check CHECK ((amount_due >= (0)::numeric)),
    CONSTRAINT invoices_deposit_applied_check CHECK ((deposit_applied >= (0)::numeric)),
    CONSTRAINT invoices_deposit_within_total CHECK ((deposit_applied <= total)),
    CONSTRAINT invoices_discount_type_check CHECK ((discount_type = ANY (ARRAY['AMOUNT'::text, 'PERCENT'::text]))),
    CONSTRAINT invoices_discount_value_check CHECK ((discount_value >= (0)::numeric)),
    CONSTRAINT invoices_due_after_issue CHECK ((due_on >= issued_on)),
    CONSTRAINT invoices_payment_terms_check CHECK ((payment_terms = ANY (ARRAY['DUE_ON_RECEIPT'::text, 'NET_15'::text, 'NET_30'::text]))),
    CONSTRAINT invoices_status_check CHECK ((status = ANY (ARRAY['ISSUED'::text, 'VOID'::text]))),
    CONSTRAINT invoices_total_check CHECK (((total >= (0)::numeric) AND (total <= ('9999999999'::bigint)::numeric))),
    CONSTRAINT invoices_vat_mode_check CHECK ((vat_mode = ANY (ARRAY['ADDED'::text, 'INCLUSIVE'::text, 'NONE'::text]))),
    CONSTRAINT invoices_vat_rate_check CHECK (((vat_rate >= (0)::numeric) AND (vat_rate <= (100)::numeric))),
    CONSTRAINT invoices_void_fields CHECK (((status = 'VOID'::text) = (voided_at IS NOT NULL)))
);


--
-- Name: TABLE invoices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.invoices IS 'A bill issued after the service (TPC-INV). Never edited or deleted: voided with a reason. amount_due = total - deposit_applied.';


--
-- Name: create_invoice(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice(p_invoice jsonb, p_lines jsonb) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  today date := (now() at time zone 'Asia/Manila')::date;
  target public.invoices;
  q_row public.quotes;
  entry_row record;
  extra_row public.appointment_extras;
  lines_total numeric := 0;
  discount numeric;
  net numeric;
  vat numeric;
  grand numeric;
  deposit numeric := 0;
  line_no integer := 0;
  visit_ids uuid[] := coalesce(
    (select array_agg(value::uuid) from jsonb_array_elements_text(coalesce(p_invoice->'appointment_ids', '[]'::jsonb))),
    '{}'::uuid[]
  );
  v_client uuid := (p_invoice->>'client_id')::uuid;
  v_quote uuid := nullif(p_invoice->>'quote_id', '')::uuid;
  v_issued date := coalesce(nullif(p_invoice->>'issued_on', '')::date, today);
  v_terms text := coalesce(p_invoice->>'payment_terms', 'DUE_ON_RECEIPT');
  v_discount_type text := coalesce(p_invoice->>'discount_type', 'AMOUNT');
  v_discount_value numeric := coalesce((p_invoice->>'discount_value')::numeric, 0);
  v_vat_mode text := coalesce(p_invoice->>'vat_mode', 'ADDED');
  v_vat_rate numeric := coalesce((p_invoice->>'vat_rate')::numeric, 12);
begin
  perform public.assert_billing_office();

  if v_client is null or not exists (select 1 from public.clients c where c.id = v_client) then
    raise exception 'Choose the client to invoice.';
  end if;
  if v_issued > today then raise exception 'An invoice cannot be dated in the future.'; end if;
  if v_terms not in ('DUE_ON_RECEIPT', 'NET_15', 'NET_30') then raise exception 'Choose the payment terms.'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'An invoice needs at least one line.';
  end if;
  if v_discount_type = 'PERCENT' and v_discount_value > 100 then raise exception 'A discount cannot be more than 100%%.'; end if;

  if v_quote is not null then
    select * into q_row from public.quotes q where q.id = v_quote for update;
    if q_row.id is null then raise exception 'That quote was not found.'; end if;
    if q_row.status <> 'APPROVED' then raise exception 'Only an approved quote can be invoiced.'; end if;
    if q_row.client_id <> v_client then raise exception 'That quote is for a different client.'; end if;
  end if;

  -- The visits: this client's, done, and not on another invoice.
  if exists (
    select 1 from unnest(visit_ids) as wanted(id)
    left join public.appointments a on a.id = wanted.id
    where a.id is null or a.client_id <> v_client
  ) then
    raise exception 'Every visit on the invoice must be this client''s.';
  end if;
  if exists (select 1 from public.appointments a where a.id = any(visit_ids) and a.status <> 'Completed') then
    raise exception 'Only completed visits can be invoiced.';
  end if;
  if exists (select 1 from public.appointments a where a.id = any(visit_ids) and a.invoice_id is not null) then
    raise exception 'One of those visits is already on an invoice.';
  end if;
  perform 1 from public.appointments a where a.id = any(visit_ids) for update;

  for entry_row in
    select entries.quantity, entries.unit_price, entries.extra_id, entries.appointment_id, entries.description
    from jsonb_to_recordset(p_lines) as entries(quantity numeric, unit_price numeric, extra_id uuid, appointment_id uuid, description text)
  loop
    if nullif(trim(coalesce(entry_row.description, '')), '') is null then raise exception 'Every line needs a description.'; end if;
    if entry_row.quantity is null or entry_row.quantity <= 0 then raise exception 'Every line needs a quantity above zero.'; end if;
    if entry_row.unit_price is null or entry_row.unit_price < 0 then raise exception 'Every line needs a price.'; end if;
    if entry_row.appointment_id is not null and not (entry_row.appointment_id = any(visit_ids)) then
      raise exception 'A line names a visit that is not on this invoice.';
    end if;
    if entry_row.extra_id is not null then
      select * into extra_row from public.appointment_extras e where e.id = entry_row.extra_id for update;
      if extra_row.id is null then raise exception 'An extra on the invoice was not found.'; end if;
      if extra_row.status <> 'APPROVED' then raise exception 'Only an approved extra can be invoiced (% is %).', extra_row.description, lower(extra_row.status); end if;
      if extra_row.invoice_id is not null then raise exception 'The extra "%" is already on an invoice.', extra_row.description; end if;
      if not exists (select 1 from public.appointments a where a.id = extra_row.appointment_id and a.client_id = v_client) then
        raise exception 'The extra "%" is on another client''s visit.', extra_row.description;
      end if;
    end if;
    lines_total := lines_total + round(entry_row.quantity * entry_row.unit_price, 2);
  end loop;

  discount := round(case when v_discount_type = 'PERCENT' then lines_total * v_discount_value / 100 else least(v_discount_value, lines_total) end, 2);
  net := lines_total - discount;
  vat := round(case v_vat_mode
    when 'ADDED' then net * v_vat_rate / 100
    when 'INCLUSIVE' then net - net / (1 + v_vat_rate / 100)
    else 0 end, 2);
  grand := case when v_vat_mode = 'ADDED' then net + vat else net end;

  if v_quote is not null then
    deposit := greatest(0, public.quote_deposit_paid(v_quote) - coalesce((
      select sum(i.deposit_applied) from public.invoices i where i.quote_id = v_quote and i.status = 'ISSUED'
    ), 0));
    deposit := least(deposit, grand);
  end if;

  insert into public.invoices (
    client_id, quote_id, issued_on, payment_terms, due_on, discount_type, discount_value, vat_mode, vat_rate,
    subtotal, discount_amount, vat_amount, total, deposit_applied, amount_due, notes, created_by, created_by_name
  )
  values (
    v_client, v_quote, v_issued, v_terms,
    v_issued + case v_terms when 'NET_15' then 15 when 'NET_30' then 30 else 0 end,
    v_discount_type, v_discount_value, v_vat_mode, v_vat_rate,
    lines_total, discount, vat, grand, deposit, grand - deposit,
    nullif(trim(coalesce(p_invoice->>'notes', '')), ''),
    public.current_account_id(), public.billing_actor_name()
  )
  returning * into target;

  for entry_row in
    select entries.kind, entries.service_id, entries.item_id, entries.appointment_id, entries.extra_id,
           entries.description, entries.quantity, entries.unit, entries.unit_price
    from jsonb_to_recordset(p_lines) as entries(kind text, service_id uuid, item_id uuid, appointment_id uuid, extra_id uuid,
                                                description text, quantity numeric, unit text, unit_price numeric)
  loop
    insert into public.invoice_lines (invoice_id, position, kind, service_id, item_id, appointment_id, extra_id, description, quantity, unit, unit_price, amount)
    values (
      target.id, line_no, upper(coalesce(entry_row.kind, 'EXTRA')), entry_row.service_id, entry_row.item_id,
      entry_row.appointment_id, entry_row.extra_id, trim(entry_row.description), entry_row.quantity,
      nullif(trim(coalesce(entry_row.unit, '')), ''), entry_row.unit_price, round(entry_row.quantity * entry_row.unit_price, 2)
    );
    if entry_row.extra_id is not null then
      update public.appointment_extras e set invoice_id = target.id where e.id = entry_row.extra_id;
    end if;
    line_no := line_no + 1;
  end loop;

  update public.appointments a set invoice_id = target.id where a.id = any(visit_ids);

  return target;
end;
$$;


--
-- Name: create_role_account(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_role_account(session_token uuid, new_name text, new_username text, new_email text, new_phone text, new_password text, new_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare caller_id uuid; caller_role text; created jsonb;
begin
  select id, role_name into caller_id, caller_role from role_account_for_session(session_token) limit 1;
  if caller_id is null or caller_role <> 'ADMIN' then raise exception 'You do not have permission to create accounts.'; end if;
  if upper(new_role) not in ('STAFF', 'TECHNICIAN') then raise exception 'Only Staff and Technician accounts can be created.'; end if;
  if exists (select 1 from admins where lower(email)=lower(new_email) or lower(username)=lower(new_username))
     or exists (select 1 from staff where lower(email)=lower(new_email) or lower(username)=lower(new_username))
     or exists (select 1 from technicians where lower(email)=lower(new_email) or lower(username)=lower(new_username)) then
    raise exception 'That email or username is already used by another account.';
  end if;
  if upper(new_role) = 'STAFF' then
    insert into staff (name, username, email, phone, password, password_hash, status) values
      (new_name, new_username, new_email, new_phone, '', crypt(new_password, gen_salt('bf')), 'ACTIVE') returning to_jsonb(staff.*) into created;
  else
    insert into technicians (name, username, email, phone, password, password_hash, status) values
      (new_name, new_username, new_email, new_phone, '', crypt(new_password, gen_salt('bf')), 'ACTIVE') returning to_jsonb(technicians.*) into created;
  end if;
  return created || jsonb_build_object('role', upper(new_role));
end;
$$;


--
-- Name: current_account_id(); Type: FUNCTION; Schema: public; Owner: -
