--
-- Name: quote_reference_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.quote_reference_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: quotes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.quotes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reference text DEFAULT ('TPC-Q-'::text || lpad((nextval('public.quote_reference_seq'::regclass))::text, 5, '0'::text)) NOT NULL,
    client_id uuid NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    valid_until date NOT NULL,
    payment_terms text DEFAULT 'DUE_ON_RECEIPT'::text NOT NULL,
    area_sqm numeric,
    discount_type text DEFAULT 'AMOUNT'::text NOT NULL,
    discount_value numeric DEFAULT 0 NOT NULL,
    vat_mode text DEFAULT 'ADDED'::text NOT NULL,
    vat_rate numeric DEFAULT 12 NOT NULL,
    deposit_type text DEFAULT 'NONE'::text NOT NULL,
    deposit_value numeric DEFAULT 0 NOT NULL,
    subtotal numeric DEFAULT 0 NOT NULL,
    discount_amount numeric DEFAULT 0 NOT NULL,
    vat_amount numeric DEFAULT 0 NOT NULL,
    total numeric DEFAULT 0 NOT NULL,
    deposit_amount numeric DEFAULT 0 NOT NULL,
    notes text,
    revision_of uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    decided_at timestamp with time zone,
    decided_by uuid,
    decision_note text,
    inspection_id uuid,
    warranty_months integer,
    checkup_frequency text,
    CONSTRAINT quotes_area_sqm_check CHECK (((area_sqm IS NULL) OR ((area_sqm > (0)::numeric) AND (area_sqm <= (1000000)::numeric)))),
    CONSTRAINT quotes_deposit_amount_check CHECK ((deposit_amount >= (0)::numeric)),
    CONSTRAINT quotes_deposit_type_check CHECK ((deposit_type = ANY (ARRAY['NONE'::text, 'AMOUNT'::text, 'PERCENT'::text]))),
    CONSTRAINT quotes_deposit_value_check CHECK ((deposit_value >= (0)::numeric)),
    CONSTRAINT quotes_discount_type_check CHECK ((discount_type = ANY (ARRAY['AMOUNT'::text, 'PERCENT'::text]))),
    CONSTRAINT quotes_discount_value_check CHECK ((discount_value >= (0)::numeric)),
    CONSTRAINT quotes_payment_terms_check CHECK ((payment_terms = ANY (ARRAY['DUE_ON_RECEIPT'::text, 'NET_15'::text, 'NET_30'::text]))),
    CONSTRAINT quotes_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'SENT'::text, 'APPROVED'::text, 'REJECTED'::text]))),
    CONSTRAINT quotes_total_check CHECK (((total >= (0)::numeric) AND (total <= ('9999999999'::bigint)::numeric))),
    CONSTRAINT quotes_vat_mode_check CHECK ((vat_mode = ANY (ARRAY['ADDED'::text, 'INCLUSIVE'::text, 'NONE'::text]))),
    CONSTRAINT quotes_vat_rate_check CHECK (((vat_rate >= (0)::numeric) AND (vat_rate <= (100)::numeric))),
    CONSTRAINT quotes_warranty_check CHECK ((((warranty_months IS NULL) OR ((warranty_months >= 1) AND (warranty_months <= 120))) AND ((checkup_frequency IS NULL) OR (checkup_frequency = ANY (ARRAY['MONTHLY'::text, 'QUARTERLY'::text])))))
);


--
-- Name: TABLE quotes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.quotes IS 'A price offered to a client before work begins. Totals are computed by save_quote(); DRAFT -> SENT -> APPROVED | REJECTED.';


--
-- Name: decide_quote(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_quote(p_quote_id uuid, p_approved boolean, p_note text DEFAULT NULL::text) RETURNS public.quotes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.quotes;
begin
  perform public.assert_billing_office();
  select * into target from public.quotes q where q.id = p_quote_id for update;
  if target.id is null then raise exception 'That quote was not found.'; end if;
  if target.status <> 'SENT' then raise exception 'Only a sent quote can be approved or rejected.'; end if;
  if p_approved and target.valid_until < (now() at time zone 'Asia/Manila')::date then
    raise exception 'Quote % expired on %. Revise it to send a new version.', target.reference, to_char(target.valid_until, 'Mon DD, YYYY');
  end if;
  if not p_approved and nullif(trim(coalesce(p_note, '')), '') is null then
    raise exception 'Write why the quote was rejected.';
  end if;
  update public.quotes q set
    status = case when p_approved then 'APPROVED' else 'REJECTED' end,
    decided_at = now(), decided_by = public.current_account_id(),
    decision_note = nullif(trim(coalesce(p_note, '')), ''),
    updated_at = now()
  where q.id = p_quote_id returning * into target;
  return target;
end;
$$;


--
-- Name: decide_visit_extra(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_visit_extra(p_extra_id uuid, p_approved boolean, p_note text DEFAULT NULL::text) RETURNS public.appointment_extras
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.appointment_extras;
begin
  perform public.assert_billing_office();
  select * into target from public.appointment_extras e where e.id = p_extra_id for update;
  if target.id is null then raise exception 'That extra was not found.'; end if;
  if target.status <> 'PROPOSED' then raise exception 'That extra was already %.', lower(target.status); end if;
  update public.appointment_extras e set
    status = case when p_approved then 'APPROVED' else 'DECLINED' end,
    decision_note = nullif(trim(coalesce(p_note, '')), ''),
    decided_at = now(), decided_by = public.current_account_id()
  where e.id = p_extra_id returning * into target;
  return target;
end;
$$;


--
-- Name: delete_contract(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_contract(p_contract_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.contracts;
begin
  perform public.assert_billing_office();
  select * into target from public.contracts c where c.id = p_contract_id for update;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  if target.status <> 'DRAFT' then raise exception 'Only a draft contract can be deleted; cancel it instead.'; end if;
  if target.plan_id is not null then raise exception 'Visits were booked for this contract; cancel it instead.'; end if;
  delete from public.contracts c where c.id = target.id;
  return true;
end;
$$;


--
-- Name: delete_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_quote(p_quote_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.quotes;
begin
  perform public.assert_billing_office();
  select * into target from public.quotes q where q.id = p_quote_id for update;
  if target.id is null then raise exception 'That quote was not found.'; end if;
  if target.status <> 'DRAFT' then raise exception 'Only a draft can be deleted.'; end if;
  if exists (select 1 from public.payments p where p.quote_id = target.id)
     or exists (select 1 from public.appointments a where a.quote_id = target.id)
     or exists (select 1 from public.quotes q where q.revision_of = target.id) then
    raise exception 'This quote has payments, visits or revisions and is kept.';
  end if;
  delete from public.quotes q where q.id = target.id;
end;
$$;


--
-- Name: delete_visit_extra(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_visit_extra(p_extra_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.appointment_extras;
begin
  perform public.assert_billing_office();
  select * into target from public.appointment_extras e where e.id = p_extra_id for update;
  if target.id is null then raise exception 'That extra was not found.'; end if;
  if target.invoice_id is not null then raise exception 'That extra is on an invoice. Void the invoice first.'; end if;
  delete from public.appointment_extras e where e.id = p_extra_id;
  return true;
end;
$$;


--
-- Name: end_absence(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_absence(p_absence_id uuid, p_back_on date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.technician_absences;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if public.current_account_role() not in ('ADMIN', 'STAFF') then
    raise exception 'Only the office can change an absence.';
  end if;
  select * into target from public.technician_absences ab where ab.id = p_absence_id for update;
  if target.id is null then raise exception 'That absence was not found.'; end if;
  if p_back_on is null then raise exception 'Choose the day they are back.'; end if;

  if p_back_on <= target.starts_on then
    delete from public.technician_absences ab where ab.id = target.id;
  elsif p_back_on <= target.ends_on then
    update public.technician_absences ab set ends_on = p_back_on - 1 where ab.id = target.id;
  end if;
end;
$$;


--
-- Name: enforce_appointment_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_appointment_status_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status then
    if old.status = 'Completed' then
      raise exception 'A completed appointment cannot change status.';
    end if;
    if old.status = 'Cancelled' and new.status <> 'Reschedule' then
      raise exception 'A cancelled appointment can only be reopened by setting its status to Reschedule.';
    end if;
  end if;

  if new.status <> 'Cancelled' then
    new.cancellation_reason := null;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_inventory_movement_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_inventory_movement_limits() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.movement_date is not null
     and new.movement_date > (now() at time zone 'Asia/Manila')::date then
    raise exception 'A stock movement cannot be dated in the future.';
  end if;
  if abs(coalesce(new.amount, 0)) > 100000 or abs(coalesce(new.quantity_delta, 0)) > 100000 then
    raise exception 'One stock movement cannot move more than 100,000 units.';
  end if;
  if new.unit_cost is not null and new.unit_cost > 999999.99 then
    raise exception 'Unit cost cannot be more than 999,999.99.';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_plan_day_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_plan_day_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare plan_kind text;
begin
  if new.plan_id is null or new.scheduled_at is not distinct from old.scheduled_at then
    return new;
  end if;
  select kind into plan_kind from public.appointment_plans where id = new.plan_id;
  if plan_kind is distinct from 'MULTI_DAY' then return new; end if;

  if exists (
    select 1 from public.appointments other
    where other.plan_id = new.plan_id and other.id <> new.id and other.status <> 'Cancelled'
      and (
        (other.plan_position < new.plan_position and other.scheduled_at >= new.scheduled_at)
        or (other.plan_position > new.plan_position and other.scheduled_at <= new.scheduled_at)
      )
  ) then
    raise exception 'A day of a multi-day job cannot move past the day before or after it.';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_treatment_method_value_stable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_treatment_method_value_stable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.value is distinct from old.value
     and public.treatment_method_in_use(old.value) then
    raise exception
      'This method is already recorded on filed reports, so its value cannot be changed. Edit the label instead, or retire it and add a replacement.';
  end if;

  if tg_op = 'DELETE' and public.treatment_method_in_use(old.value) then
    raise exception
      'This method is already recorded on filed reports, so it cannot be deleted. Set it inactive to retire it instead.';
  end if;

  return case tg_op when 'DELETE' then old else new end;
end;
$$;


--
-- Name: ensure_item_batches(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_item_batches(p_item_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  item_kind text;
  shelf numeric;
  batched numeric;
  gap numeric;
  opening uuid;
begin
  select i.type::text, i.quantity into item_kind, shelf from public.inventory i where i.id = p_item_id;
  if item_kind is distinct from 'CHEMICAL' then return; end if;

  select coalesce(sum(b.quantity), 0) into batched from public.inventory_batches b where b.item_id = p_item_id;
  gap := shelf - batched;
  if gap <= 0 then return; end if;

  select b.id into opening from public.inventory_batches b
  where b.item_id = p_item_id and b.is_opening and b.written_off_at is null
  order by b.created_at desc limit 1;

  if opening is null then
    insert into public.inventory_batches (item_id, expiration_date, received_date, quantity_received, quantity, unit_cost, is_opening)
    select i.id, i.expiration_date::date, coalesce(i.date_received::date, i.created_at::date, current_date), gap, gap, i.cost, true
    from public.inventory i where i.id = p_item_id;
  else
    update public.inventory_batches b
      set quantity = b.quantity + gap, quantity_received = b.quantity_received + gap
      where b.id = opening;
  end if;
end;
$$;


--
-- Name: fallback_batch(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fallback_batch(p_item_id uuid, p_on date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare found uuid;
begin
  select b.id into found from public.inventory_batches b
  where b.item_id = p_item_id and b.is_opening and b.written_off_at is null
  order by b.created_at desc limit 1;
  if found is null then
    insert into public.inventory_batches (item_id, received_date, quantity_received, quantity, is_opening)
    values (p_item_id, p_on, 0, 0, true)
    returning id into found;
  end if;
  return found;
end;
$$;


--
-- Name: finish_job_day(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_job_day(p_appointment_id uuid) RETURNS public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.appointments;
declare job_kind text;
begin
  perform public.assert_can_work_visit(p_appointment_id);

  select a.* into target from public.appointments a where a.id = p_appointment_id;
  if target.id is null then raise exception 'Appointment not found.'; end if;
  select kind into job_kind from public.appointment_plans where id = target.plan_id;
  if job_kind is distinct from 'MULTI_DAY' then raise exception 'Only a day of a multi-day job is closed this way.'; end if;
  if target.status in ('Cancelled', 'Completed') then raise exception 'This day is already closed.'; end if;
  if public.plan_last_day(target.plan_id) = p_appointment_id then
    raise exception 'This is the job''s last day: file the report to finish it.';
  end if;

  update public.appointments set day_done_at = now() where id = p_appointment_id returning * into target;
  return target;
end;
$$;


--
-- Name: finish_job_here(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_job_here(p_appointment_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.appointments;
declare job_kind text;
declare cancelled_count integer;
begin
  perform public.assert_can_work_visit(p_appointment_id);

  select a.* into target from public.appointments a where a.id = p_appointment_id;
  if target.id is null then raise exception 'Appointment not found.'; end if;
  select kind into job_kind from public.appointment_plans where id = target.plan_id;
  if job_kind is distinct from 'MULTI_DAY' then raise exception 'Only a multi-day job can be finished early.'; end if;
  if target.status = 'Cancelled' then raise exception 'This day is cancelled.'; end if;

  update public.appointments
    set status = 'Cancelled', cancellation_reason = 'Job finished early'
    where plan_id = target.plan_id and scheduled_at > target.scheduled_at
      and status not in ('Completed', 'Cancelled', 'In progress');
  get diagnostics cancelled_count = row_count;
  return cancelled_count;
end;
$$;


--
-- Name: guard_system_service(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_system_service() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_trusted boolean := coalesce(current_setting('app.system_service', true), '') = 'on';
begin
  if tg_op = 'DELETE' then
    if old.system_key is not null then
      raise exception '% is a built-in service and cannot be deleted.', old.name;
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' then
    if new.system_key is not null and not v_trusted then
      raise exception 'Built-in services are set up by the system.';
    end if;
    return new;
  end if;

  -- UPDATE
  if new.system_key is distinct from old.system_key and not v_trusted then
    raise exception 'Which service is built in cannot be changed.';
  end if;
  if old.system_key is not null and not v_trusted then
    if new.name is distinct from old.name then
      raise exception '% is a built-in service: its name cannot be changed.', old.name;
    end if;
    if new.description is distinct from old.description then
      raise exception '% is a built-in service: its description cannot be changed.', old.name;
    end if;
    if new.category is distinct from old.category then
      raise exception '% is a built-in service: its category cannot be changed.', old.name;
    end if;
    if new.skip_payment_check is distinct from old.skip_payment_check then
      raise exception '% is a built-in service: whether it needs payment cannot be changed.', old.name;
    end if;
    if not new.is_active then
      raise exception '% is a built-in service and cannot be retired.', old.name;
    end if;
    if old.system_key = 'CHECKUP' and coalesce(new.default_price, 0) <> 0 then
      raise exception 'A warranty checkup is free: the Checkup price stays 0.';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_warranty_checkup_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_warranty_checkup_period() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_type text;
  v_source uuid;
  v_frequency text;
  v_period record;
  v_old record;
  v_other text;
begin
  if new.warranty_kind is distinct from 'CHECKUP' or new.status = 'Cancelled' then
    return new;
  end if;
  -- Only a change is checked: marking a checkup, moving one, or bringing a
  -- cancelled one back.
  if tg_op = 'UPDATE'
     and old.warranty_kind is not distinct from new.warranty_kind
     and old.scheduled_at is not distinct from new.scheduled_at
     and old.status <> 'Cancelled' then
    return new;
  end if;

  v_type := case when new.warranty_contract_id is not null then 'CONTRACT' else 'QUOTE' end;
  v_source := coalesce(new.warranty_contract_id, new.warranty_quote_id);
  if v_type = 'CONTRACT' then
    select c.checkup_frequency into v_frequency from public.contracts c where c.id = v_source;
  else
    select q.checkup_frequency into v_frequency from public.quotes q where q.id = v_source;
  end if;
  if v_frequency is null then
    raise exception 'This warranty includes no checkups. Book a paid visit, or a warranty re-treatment if pests came back.';
  end if;

  select * into v_period
  from public.warranty_checkup_period(v_type, v_source, (new.scheduled_at at time zone 'Asia/Manila')::date);
  if v_period.period_index is null then
    raise exception 'A checkup must fall inside one of the warranty''s checkup periods; % is outside them.',
      to_char((new.scheduled_at at time zone 'Asia/Manila')::date, 'Mon DD, YYYY');
  end if;

  if tg_op = 'UPDATE' and old.warranty_kind = 'CHECKUP' and old.scheduled_at is distinct from new.scheduled_at then
    select * into v_old
    from public.warranty_checkup_period(v_type, v_source, (old.scheduled_at at time zone 'Asia/Manila')::date);
    if v_old.period_index is not null and v_old.period_index <> v_period.period_index then
      raise exception 'A checkup can move only inside its own period (% - %).',
        to_char(v_old.starts_on, 'Mon DD, YYYY'), to_char(v_old.ends_on, 'Mon DD, YYYY');
    end if;
  end if;

  select a.reference into v_other
  from public.appointments a
  cross join lateral public.warranty_checkup_period(v_type, v_source, (a.scheduled_at at time zone 'Asia/Manila')::date) p
  where a.id <> new.id
    and a.warranty_kind = 'CHECKUP'
    and a.status <> 'Cancelled'
    and coalesce(a.warranty_contract_id, a.warranty_quote_id) = v_source
    and p.period_index = v_period.period_index
  limit 1;
  if v_other is not null then
    raise exception 'This warranty already has its checkup for % - % (%). One checkup per period.',
      to_char(v_period.starts_on, 'Mon DD, YYYY'), to_char(v_period.ends_on, 'Mon DD, YYYY'), v_other;
  end if;
  return new;
end;
$$;


--
-- Name: guard_warranty_edit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_warranty_edit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_type text := case when tg_table_name = 'contracts' then 'CONTRACT' else 'QUOTE' end;
  v_start date;
  v_end date;
  v_list text;
begin
  if new.warranty_months is not distinct from old.warranty_months
     and new.checkup_frequency is not distinct from old.checkup_frequency then
    return new;
  end if;

  -- Removing the warranty: nothing may still be booked under it.
  if new.warranty_months is null then
    select string_agg(a.reference || ' (' || to_char((a.scheduled_at at time zone 'Asia/Manila')::date, 'Mon DD, YYYY') || ')', ', ' order by a.scheduled_at)
      into v_list
    from public.appointments a
    where (case when v_type = 'CONTRACT' then a.warranty_contract_id else a.warranty_quote_id end) = new.id
      and a.warranty_kind is not null and a.status not in ('Completed', 'Cancelled');
    if v_list is not null then
      raise exception 'The warranty cannot be removed while visits are booked under it: %. Cancel them first.', v_list;
    end if;
    return new;
  end if;

  -- A new length: no booked visit may fall after the new end.
  v_start := public.warranty_start(v_type, new.id);
  if v_start is not null then
    v_end := (v_start + make_interval(months => new.warranty_months))::date;
    select string_agg(a.reference || ' (' || to_char((a.scheduled_at at time zone 'Asia/Manila')::date, 'Mon DD, YYYY') || ')', ', ' order by a.scheduled_at)
      into v_list
    from public.appointments a
    where (case when v_type = 'CONTRACT' then a.warranty_contract_id else a.warranty_quote_id end) = new.id
      and a.warranty_kind is not null and a.status not in ('Completed', 'Cancelled')
      and (a.scheduled_at at time zone 'Asia/Manila')::date > v_end;
    if v_list is not null then
      raise exception 'The warranty would end on %, but these visits are booked after that: %. Cancel them first, or keep a longer warranty.',
        to_char(v_end, 'Mon DD, YYYY'), v_list;
    end if;
  end if;

  -- A new checkup frequency: the booked checkups were placed by the old one (086).
  if new.checkup_frequency is distinct from old.checkup_frequency then
    select string_agg(a.reference || ' (' || to_char((a.scheduled_at at time zone 'Asia/Manila')::date, 'Mon DD, YYYY') || ')', ', ' order by a.scheduled_at)
      into v_list
    from public.appointments a
    where (case when v_type = 'CONTRACT' then a.warranty_contract_id else a.warranty_quote_id end) = new.id
      and a.warranty_kind = 'CHECKUP' and a.status not in ('Completed', 'Cancelled');
    if v_list is not null then
      raise exception 'The checkups cannot change while these checkups are booked on the current schedule: %. Cancel them first.', v_list;
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: guard_warranty_visit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_warranty_visit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_trusted boolean := coalesce(current_setting('app.warranty_link', true), '') = 'on';
  v_starts date;
  v_ends date;
  v_day date;
begin
  -- 1. Setting the link: only the warranty functions.
  if new.warranty_kind is not null
     and (tg_op = 'INSERT' or old.warranty_kind is null)
     and not v_trusted then
    raise exception 'A visit is made a warranty visit only through Book checkups, Warranty re-treatment or a follow-up under warranty.';
  end if;

  if tg_op = 'UPDATE' and old.warranty_kind is not null then
    -- 2. The link stays as it was.
    if new.warranty_kind is distinct from old.warranty_kind
       or new.warranty_quote_id is distinct from old.warranty_quote_id
       or new.warranty_contract_id is distinct from old.warranty_contract_id
       or new.client_id is distinct from old.client_id
       or new.quote_id is distinct from old.quote_id then
      raise exception 'This is a warranty visit: its warranty, client and quotation cannot be changed.';
    end if;
    -- 4. Never billed.
    if new.invoice_id is not null and old.invoice_id is null then
      raise exception 'Warranty visit % is free and cannot be put on an invoice.', coalesce(new.reference, 'this visit');
    end if;
    -- 5. A new date stays inside the warranty.
    if new.scheduled_at is distinct from old.scheduled_at then
      select w.starts_on, w.ends_on into v_starts, v_ends
      from public.warranty_window(
        case when new.warranty_contract_id is not null then 'CONTRACT' else 'QUOTE' end,
        coalesce(new.warranty_contract_id, new.warranty_quote_id)
      ) w;
      v_day := (new.scheduled_at at time zone 'Asia/Manila')::date;
      if v_starts is not null and (v_day < v_starts or v_day > v_ends) then
        raise exception 'The warranty runs % to %; a warranty visit cannot move outside it.', to_char(v_starts, 'Mon DD, YYYY'), to_char(v_ends, 'Mon DD, YYYY');
      end if;
    end if;
  end if;

  -- 3. Free.
  if new.warranty_kind is not null and coalesce(new.price, 0) <> 0 then
    raise exception 'This is a warranty visit and is free: its price must be ₱0.';
  end if;

  return new;
end;
$$;


--
-- Name: has_role_table_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_role_table_session() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from role_account_for_session(
      nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid
    )
  );
$$;


--
-- Name: inventory_identity_key(text, public.inventory_type, text, public.chemical_type, text, text, text, text, text, public.material_category); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_identity_key(p_name text, p_type public.inventory_type, p_unit text, p_chemical_type public.chemical_type, p_safety_level text, p_hazard_rating text, p_manufacturer text, p_model text, p_serial_number text, p_material_category public.material_category) RETURNS text
    LANGUAGE sql STABLE
    AS $$
  select concat_ws('|',
    lower(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g')),
    coalesce(p_type::text, ''),
    lower(regexp_replace(btrim(coalesce(p_unit, '')), '\s+', ' ', 'g')),
    case when p_type = 'CHEMICAL' then coalesce(p_chemical_type::text, '') else '' end,
    case when p_type = 'CHEMICAL' then lower(regexp_replace(btrim(coalesce(p_safety_level, '')), '\s+', ' ', 'g')) else '' end,
    case when p_type = 'CHEMICAL' then lower(regexp_replace(btrim(coalesce(p_hazard_rating, '')), '\s+', ' ', 'g')) else '' end,
    case when p_type = 'EQUIPMENT' then lower(regexp_replace(btrim(coalesce(p_manufacturer, '')), '\s+', ' ', 'g')) else '' end,
    case when p_type = 'EQUIPMENT' then lower(regexp_replace(btrim(coalesce(p_model, '')), '\s+', ' ', 'g')) else '' end,
    case when p_type = 'EQUIPMENT' then lower(regexp_replace(btrim(coalesce(p_serial_number, '')), '\s+', ' ', 'g')) else '' end,
    case when p_type = 'MATERIAL' then coalesce(p_material_category::text, '') else '' end
  );
$$;


--
-- Name: invoice_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invoice_paid(p_invoice_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(p.amount), 0)
  from public.payments p
  where p.invoice_id = p_invoice_id and p.kind = 'PAYMENT' and public.payment_counts(p);
$$;


--
-- Name: is_assigned_to_appointment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_assigned_to_appointment(p_appointment_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.appointment_technicians at
    where at.appointment_id = p_appointment_id
      and at.technician_id = public.current_account_id()
  );
$$;


--
-- Name: is_office_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_office_account() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(public.current_account_role(), '') in ('ADMIN', 'STAFF');
$$;


--
-- Name: inventory; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    type public.inventory_type NOT NULL,
    quantity numeric DEFAULT 0 NOT NULL,
    unit text NOT NULL,
    cost numeric NOT NULL,
    supplier text,
    storage_location text,
    reorder_level numeric,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    chemical_type public.chemical_type,
    expiration_date timestamp with time zone,
    safety_level text,
    hazard_rating text,
    date_received timestamp with time zone,
    serial_number text,
    condition public.equipment_condition,
    last_maintenance_date timestamp with time zone,
    next_maintenance_date timestamp with time zone,
    manufacturer text,
    model text,
    material_category public.material_category,
    description text,
    status public.inventory_status DEFAULT 'ACTIVE'::public.inventory_status NOT NULL,
    purchase_unit text,
    usage_unit text,
    conversion_multiplier numeric,
    created_by uuid,
    intake_branch_or_station text,
    price_mode text DEFAULT 'MARKUP'::text NOT NULL,
    customer_price numeric,
    markup_percent numeric DEFAULT 0 NOT NULL,
    CONSTRAINT inventory_conversion_positive CHECK (((conversion_multiplier IS NULL) OR (conversion_multiplier > (0)::numeric))),
    CONSTRAINT inventory_customer_price_check CHECK (((customer_price IS NULL) OR ((customer_price >= (0)::numeric) AND (customer_price <= 999999.99)))),
    CONSTRAINT inventory_markup_percent_check CHECK (((markup_percent >= (0)::numeric) AND (markup_percent <= (1000)::numeric))),
    CONSTRAINT inventory_nonnegative_values CHECK (((quantity >= (0)::numeric) AND (cost >= (0)::numeric) AND ((reorder_level IS NULL) OR (reorder_level >= (0)::numeric)))),
    CONSTRAINT inventory_price_mode_check CHECK ((price_mode = ANY (ARRAY['FIXED'::text, 'MARKUP'::text])))
);


--
-- Name: COLUMN inventory.price_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory.price_mode IS 'How the customer price is set: FIXED (customer_price) or MARKUP (cost × (1 + markup_percent/100)).';


--
-- Name: item_customer_price(public.inventory); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_customer_price(p_item public.inventory) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  select round(case
    when p_item.price_mode = 'FIXED' then coalesce(p_item.customer_price, 0)
    else coalesce(p_item.cost, 0) * (1 + coalesce(p_item.markup_percent, 0) / 100)
  end, 2);
$$;


--
-- Name: link_contract_plan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_contract_plan(p_contract_id uuid, p_appointment_id uuid) RETURNS public.contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.contracts;
  visit public.appointments;
  paid numeric;
begin
  perform public.assert_billing_office();
  select * into target from public.contracts c where c.id = p_contract_id for update;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  if target.status in ('ENDED', 'CANCELLED') then raise exception 'Contract % is %.', target.reference, lower(target.status); end if;
  paid := public.contract_deposit_paid(target.id);
  if target.deposit_amount > 0 and paid < target.deposit_amount then
    raise exception 'The down payment of ₱% has not been received yet (₱% so far).', target.deposit_amount, paid;
  end if;
  select * into visit from public.appointments a where a.id = p_appointment_id;
  if visit.id is null then raise exception 'That visit was not found.'; end if;
  if visit.client_id <> target.client_id then raise exception 'That visit is for a different client.'; end if;
  if visit.plan_id is null then raise exception 'Book the contract''s visits as a recurring plan.'; end if;
  update public.contracts c set plan_id = visit.plan_id, updated_at = now() where c.id = target.id returning * into target;
  return target;
end;
$$;


--
-- Name: link_follow_up(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_follow_up(p_appointment_id uuid, p_original_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_visit public.appointments;
  v_original public.appointments;
begin
  if coalesce(public.current_account_role(), '') not in ('ADMIN', 'STAFF') then
    raise exception 'Only the office can link a follow-up visit.';
  end if;
  select * into v_visit from public.appointments where id = p_appointment_id;
  if v_visit.id is null then raise exception 'That visit was not found.'; end if;
  if p_original_id is null then
    update public.appointments set follow_up_of = null where id = p_appointment_id;
    return;
  end if;
  select * into v_original from public.appointments where id = p_original_id;
  if v_original.id is null then raise exception 'The original visit was not found.'; end if;
  if v_original.id = v_visit.id then raise exception 'A visit cannot be a follow-up of itself.'; end if;
  if v_original.client_id is distinct from v_visit.client_id then
    raise exception 'A follow-up must be for the same client as the visit it follows.';
  end if;
  -- 080: after the visit it checks on, never before.
  if v_visit.scheduled_at < v_original.scheduled_at + make_interval(mins => coalesce(v_original.duration_minutes, 60)) then
    raise exception 'A follow-up must be after % (%).', coalesce(v_original.reference, 'the visit it follows'), to_char(v_original.scheduled_at at time zone 'Asia/Manila', 'Mon DD, HH12:MI AM');
  end if;
  update public.appointments set follow_up_of = v_original.id where id = p_appointment_id;
end;
$$;


--
-- Name: link_invoice_contract(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_invoice_contract(p_invoice_id uuid, p_contract_id uuid) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.invoices;
  v_deposit numeric;
begin
  perform public.assert_billing_office();
  select * into target from public.invoices i where i.id = p_invoice_id for update;
  if target.id is null then raise exception 'That invoice was not found.'; end if;
  if not exists (select 1 from public.contracts c where c.id = p_contract_id and c.client_id = target.client_id) then
    raise exception 'That contract is for a different client.';
  end if;
  update public.invoices i set contract_id = p_contract_id where i.id = target.id returning * into target;

  if target.quote_id is null and target.status = 'ISSUED' and coalesce(target.deposit_applied, 0) = 0
     and not exists (select 1 from public.payments p where p.invoice_id = target.id and p.reversed_at is null) then
    v_deposit := greatest(0, public.contract_deposit_paid(p_contract_id) - coalesce((
      select sum(i.deposit_applied) from public.invoices i
      where i.contract_id = p_contract_id and i.quote_id is null and i.status = 'ISSUED' and i.id <> target.id
    ), 0));
    v_deposit := least(v_deposit, target.total);
    if v_deposit > 0 then
      update public.invoices i set deposit_applied = v_deposit, amount_due = i.total - v_deposit
      where i.id = target.id returning * into target;
    end if;
  end if;
  return target;
end;
$$;


--
-- Name: link_quote_appointments(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_quote_appointments(p_quote_id uuid, p_appointment_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  q_row public.quotes;
  paid numeric;
  linked integer;
begin
  perform public.assert_billing_office();
  select * into q_row from public.quotes q where q.id = p_quote_id;
  if q_row.id is null then raise exception 'That quote was not found.'; end if;
  if q_row.status <> 'APPROVED' then raise exception 'Only an approved quote can be booked.'; end if;
  paid := public.quote_booking_paid(q_row.id);
  if q_row.deposit_amount > 0 and paid < q_row.deposit_amount then
    raise exception 'The down payment of ₱% has not been received yet (₱% so far).', q_row.deposit_amount, paid;
  end if;
  if exists (
    select 1 from public.appointments a
    where a.id = any(p_appointment_ids) and a.client_id is distinct from q_row.client_id
  ) then
    raise exception 'Those visits are for a different client.';
  end if;
  update public.appointments a set quote_id = q_row.id where a.id = any(p_appointment_ids);
  get diagnostics linked = row_count;
  return linked;
end;
$$;


--
-- Name: log_visit_usage(uuid, uuid, numeric, date, text, text, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_visit_usage(p_appointment_id uuid, p_item_id uuid, p_amount numeric, p_on date, p_reference text, p_actor text, p_actor_id uuid, p_batch_id uuid, p_label text, p_checkout_id uuid) RETURNS TABLE(movement_id uuid, new_quantity numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare created uuid; shelf numeric;
begin
  insert into public.inventory_movements (
    item_id, amount, quantity_delta, movement_date, reference, actor, actor_id, movement_type,
    appointment_id, batch_number, stock_out_reason, checkout_id, batch_id
  )
  values (
    p_item_id, p_amount, case when p_checkout_id is null then -p_amount else 0 end, p_on,
    p_reference || case when p_checkout_id is null then '' else ' (from checkout)' end,
    p_actor, p_actor_id, 'OUT', p_appointment_id, p_label, 'APPOINTMENT', p_checkout_id, p_batch_id
  )
  returning id into created;

  if p_checkout_id is null then
    update public.inventory i set quantity = i.quantity - p_amount where i.id = p_item_id returning i.quantity into shelf;
  else
    select i.quantity into shelf from public.inventory i where i.id = p_item_id;
  end if;

  movement_id := created;
  new_quantity := shelf;
  return next;
end;
$$;


--
-- Name: logout(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.logout(session_token uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  delete from sessions where sessions.token = session_token;
$$;


--
-- Name: mark_technician_out(uuid, date, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_technician_out(p_technician_id uuid, p_starts_on date, p_ends_on date, p_reason text DEFAULT NULL::text, p_changes jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  today date := (now() at time zone 'Asia/Manila')::date;
  merged_start date := p_starts_on;
  merged_end date := p_ends_on;
  created uuid;
  left_with integer;
  technician_name text;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if public.current_account_role() not in ('ADMIN', 'STAFF') then
    raise exception 'Only the office can mark a technician out.';
  end if;
  if p_starts_on is null or p_ends_on is null then raise exception 'Choose the days they are out.'; end if;
  if p_ends_on < p_starts_on then raise exception 'The last day out is before the first.'; end if;
  if p_ends_on < today then raise exception 'Those days have already passed.'; end if;

  select t.name into technician_name from public.technicians t where t.id = p_technician_id;
  if technician_name is null then raise exception 'That technician was not found.'; end if;

  -- Their visits in those days first, so the absence does not refuse the
  -- very changes that clear them.
  if p_changes is not null and jsonb_typeof(p_changes) = 'array' and jsonb_array_length(p_changes) > 0 then
    perform public.reassign_visits(p_technician_id, p_changes, p_reason);
  end if;

  select count(*) into left_with
  from public.appointments a
  where a.status in ('Pending', 'Confirmed', 'Reschedule')
    and (a.scheduled_at at time zone 'Asia/Manila')::date between p_starts_on and p_ends_on
    and (a.technician_id = p_technician_id or exists (
      select 1 from public.appointment_technicians at
      where at.appointment_id = a.id and at.technician_id = p_technician_id));
  if left_with > 0 then
    raise exception '% still has % visit% in those days. Choose who covers each one.',
      technician_name, left_with, case when left_with = 1 then '' else 's' end;
  end if;

  -- One absence per stretch: fold in any that overlap or touch this one.
  select least(p_starts_on, coalesce(min(ab.starts_on), p_starts_on)),
         greatest(p_ends_on, coalesce(max(ab.ends_on), p_ends_on))
    into merged_start, merged_end
  from public.technician_absences ab
  where ab.technician_id = p_technician_id
    and ab.starts_on <= p_ends_on + 1
    and ab.ends_on >= p_starts_on - 1;

  delete from public.technician_absences ab
  where ab.technician_id = p_technician_id
    and ab.starts_on <= p_ends_on + 1
    and ab.ends_on >= p_starts_on - 1;

  insert into public.technician_absences (technician_id, starts_on, ends_on, reason, created_by)
  values (p_technician_id, merged_start, merged_end, nullif(trim(coalesce(p_reason, '')), ''), public.current_account_id())
  returning id into created;

  return created;
end;
$$;


--
-- Name: mark_warranty_retreatment(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_warranty_retreatment(p_appointment_id uuid, p_source_type text, p_source_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_until date;
begin
  perform public.assert_billing_office();
  select w.ends_on into v_until from public.warranty_window(upper(p_source_type), p_source_id) w;
  if v_until is null then raise exception 'That warranty is not running.'; end if;
  -- 082: only the warranty functions may set a visit's warranty link.
  perform set_config('app.warranty_link', 'on', true);
  update public.appointments a
    set warranty_kind = 'RETREATMENT',
        warranty_quote_id = case when upper(p_source_type) = 'QUOTE' then p_source_id end,
        warranty_contract_id = case when upper(p_source_type) = 'CONTRACT' then p_source_id end,
        price = 0
    where a.id = p_appointment_id;
end;
$$;


--
-- Name: move_account_role(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_account_role(session_token uuid, target_id uuid, new_role text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  caller_id uuid;
  caller_role text;
  caller_name text;
  current_role_name text;
  source_table text;
  target_table text;
  account record;
  pending_jobs integer;
  moved jsonb;
begin
  select r.id, r.role_name into caller_id, caller_role
  from public.role_account_for_session(session_token) r
  limit 1;
  if caller_id is null then raise exception 'Not signed in.'; end if;
  if caller_role <> 'ADMIN' then
    raise exception 'Only an administrator can change an account''s role.';
  end if;

  if upper(coalesce(new_role, '')) not in ('ADMIN', 'STAFF', 'TECHNICIAN') then
    raise exception 'Role must be ADMIN, STAFF or TECHNICIAN.';
  end if;
  new_role := upper(new_role);

  select accounts.role_name into current_role_name
  from (
    select id, 'ADMIN'::text role_name from public.admins
    union all select id, 'STAFF'::text from public.staff
    union all select id, 'TECHNICIAN'::text from public.technicians
  ) accounts
  where accounts.id = target_id;
  if current_role_name is null then raise exception 'Account not found.'; end if;

  -- Nothing to do. Not an error: update_role_account() passes the unchanged
  -- role on every ordinary profile edit.
  if current_role_name = new_role then
    return jsonb_build_object('id', target_id, 'role', current_role_name, 'moved', false);
  end if;

  if caller_id = target_id then
    raise exception 'You cannot change your own role.';
  end if;
  if current_role_name = 'ADMIN' then
    raise exception 'An Admin account cannot be demoted. Create a new account for the other role instead.';
  end if;
  if new_role = 'ADMIN' then
    raise exception 'Accounts cannot be promoted to Admin.';
  end if;

  -- A technician still holding live work would leave those appointments
  -- pointing at an id that is no longer a technician.
  if current_role_name = 'TECHNICIAN' then
    select count(*) into pending_jobs
    from public.appointments a
    where a.status not in ('Completed', 'Cancelled')
      and (a.technician_id = target_id
           or exists (select 1 from public.appointment_technicians at
                      where at.appointment_id = a.id and at.technician_id = target_id));
    if pending_jobs > 0 then
      raise exception
        'This technician is still assigned to % upcoming appointment(s). Reassign them before changing the role.',
        pending_jobs;
    end if;
  end if;

  source_table := lower(case current_role_name when 'ADMIN' then 'admins' when 'STAFF' then 'staff' else 'technicians' end);
  target_table := lower(case new_role         when 'ADMIN' then 'admins' when 'STAFF' then 'staff' else 'technicians' end);

  -- Read the whole row, then write it to the other table under the same id.
  execute format(
    'select id, name, username, email, phone, password, password_hash, status, created_at, last_login_at, avatar_url from %I where id = $1',
    source_table
  ) into account using target_id;

  if exists (select 1 from public.admins where lower(email) = lower(account.email) and id <> target_id)
     or exists (select 1 from public.staff where lower(email) = lower(account.email) and id <> target_id)
     or exists (select 1 from public.technicians where lower(email) = lower(account.email) and id <> target_id) then
    raise exception 'That email is already used by another account.';
  end if;

  execute format(
    'insert into %I (id, name, username, email, phone, password, password_hash, status, created_at, updated_at, last_login_at, avatar_url)
     values ($1, $2, $3, $4, $5, $6, $7, $8, $9, now(), $10, $11)
     returning to_jsonb(%I.*)',
    target_table, target_table
  )
  into moved
  using account.id, account.name, account.username, account.email, account.phone,
        account.password, account.password_hash, account.status, account.created_at,
        account.last_login_at, account.avatar_url;

  execute format('delete from %I where id = $1', source_table) using target_id;

  -- The session carries the old role, and role_account_for_session() joins on
  -- it, so leaving it in place would give this person a token that resolves
  -- to nothing. Signing them out is the honest outcome of a role change.
  delete from public.sessions where sessions.user_id = target_id;

  select a.name into caller_name from public.admins a where a.id = caller_id;
  insert into public.system_logs (actor_id, actor_name, message, type)
  values (caller_id, coalesce(caller_name, 'Administrator'),
          format('Changed %s''s role from %s to %s.', account.name, current_role_name, new_role),
          'admin');

  return moved || jsonb_build_object('role', new_role, 'moved', true);
end;
$_$;


--
-- Name: payment_reference_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.payment_reference_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: payments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reference text DEFAULT ('TPC-R-'::text || lpad((nextval('public.payment_reference_seq'::regclass))::text, 5, '0'::text)) NOT NULL,
    client_id uuid NOT NULL,
    quote_id uuid,
    kind text NOT NULL,
    amount numeric NOT NULL,
    paid_on date NOT NULL,
    method text NOT NULL,
    reference_no text,
    check_number text,
    check_bank text,
    check_date date,
    check_status text,
    check_status_on date,
    check_status_note text,
    notes text,
    received_by uuid,
    received_by_name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    reversal_reason text,
    invoice_id uuid,
    contract_id uuid,
    CONSTRAINT payments_amount_check CHECK (((amount > (0)::numeric) AND (amount <= ('9999999999'::bigint)::numeric))),
    CONSTRAINT payments_check_fields CHECK ((((method = 'CHECK'::text) AND (check_status IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(check_number, ''::text)), ''::text) IS NOT NULL)) OR ((method <> 'CHECK'::text) AND (check_status IS NULL)))),
    CONSTRAINT payments_check_status_check CHECK ((check_status = ANY (ARRAY['PENDING'::text, 'CLEARED'::text, 'BOUNCED'::text]))),
    CONSTRAINT payments_kind_check CHECK ((kind = ANY (ARRAY['DEPOSIT'::text, 'PAYMENT'::text]))),
    CONSTRAINT payments_method_check CHECK ((method = ANY (ARRAY['CASH'::text, 'BANK_TRANSFER'::text, 'GCASH'::text, 'CHECK'::text]))),
    CONSTRAINT payments_target CHECK ((((kind = 'DEPOSIT'::text) AND (invoice_id IS NULL) AND (((quote_id IS NOT NULL) AND (contract_id IS NULL)) OR ((quote_id IS NULL) AND (contract_id IS NOT NULL)))) OR ((kind = 'PAYMENT'::text) AND (invoice_id IS NOT NULL) AND (contract_id IS NULL))))
);


--
-- Name: TABLE payments; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.payments IS 'Money received, one row per receipt (TPC-R). Never deleted: a mistake is reversed with a reason. A check counts only when CLEARED.';


--
-- Name: payment_counts(public.payments); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_counts(p_payment public.payments) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p_payment.reversed_at is null
     and (p_payment.method <> 'CHECK' or p_payment.check_status = 'CLEARED');
$$;


--
-- Name: payments_no_deposit_after_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payments_no_deposit_after_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.kind = 'DEPOSIT' and exists (
    select 1 from public.invoices i where i.quote_id = new.quote_id and i.status <> 'VOID'
  ) then
    raise exception 'This quotation already has an invoice. Record the payment on the invoice instead.';
  end if;
  return new;
end;
$$;


--
-- Name: plan_last_day(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.plan_last_day(p_plan_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select id from public.appointments
  where plan_id = p_plan_id and status <> 'Cancelled'
  order by scheduled_at desc, plan_position desc
  limit 1;
$$;


--
-- Name: prevent_duplicate_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_duplicate_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  identity_key text;
  existing_id uuid;
begin
  identity_key := public.inventory_identity_key(
    new.name, new.type, new.unit, new.chemical_type, new.safety_level,
    new.hazard_rating, new.manufacturer, new.model, new.serial_number,
    new.material_category
  );

  -- Do not block metadata-only edits to records that were already duplicated.
  if tg_op = 'UPDATE' and identity_key = public.inventory_identity_key(
    old.name, old.type, old.unit, old.chemical_type, old.safety_level,
    old.hazard_rating, old.manufacturer, old.model, old.serial_number,
    old.material_category
  ) then
    return new;
  end if;

  -- Serialize matching identities so concurrent submissions cannot both pass.
  perform pg_advisory_xact_lock(hashtextextended(identity_key, 0));

  select id into existing_id
  from public.inventory
  where id is distinct from new.id
    and public.inventory_identity_key(
      name, type, unit, chemical_type, safety_level, hazard_rating,
      manufacturer, model, serial_number, material_category
    ) = identity_key
  limit 1;

  if existing_id is not null then
    raise exception 'This item already exists. Use Stock In to add quantity instead.'
      using errcode = '23505', detail = format('Existing inventory item: %s', existing_id);
  end if;

  return new;
end;
$$;


--
-- Name: purge_expired_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_expired_sessions() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  delete from sessions where expires_at <= now();
$$;


--
-- Name: quote_booking_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_booking_paid(p_quote_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.quote_deposit_paid(p_quote_id) + coalesce((
    select sum(p.amount)
    from public.payments p
    join public.invoices i on i.id = p.invoice_id
    where i.quote_id = p_quote_id
      and i.status <> 'VOID'
      and p.kind = 'PAYMENT'
      and public.payment_counts(p)
  ), 0);
$$;


--
-- Name: quote_deposit_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.quote_deposit_paid(p_quote_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(p.amount), 0)
  from public.payments p
  where p.quote_id = p_quote_id and p.kind = 'DEPOSIT' and public.payment_counts(p);
$$;


--
-- Name: reassign_visits(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign_visits(p_absent_technician_id uuid, p_changes jsonb, p_reason text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  change record;
  visit public.appointments;
  old_crew uuid[];
  new_crew uuid[];
  absent_name text;
  client_name text;
  note_line text;
  changed integer := 0;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if public.current_account_role() not in ('ADMIN', 'STAFF') then
    raise exception 'Only the office can reassign visits.';
  end if;
  if p_absent_technician_id is null then raise exception 'Choose the technician who is unavailable.'; end if;
  if jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) = 0 then
    raise exception 'There are no visits to reassign.';
  end if;

  select t.name into absent_name from public.technicians t where t.id = p_absent_technician_id;
  if absent_name is null then raise exception 'That technician was not found.'; end if;

  for change in
    select entries.appointment_id, upper(entries.action) as action, entries.technician_ids
    from jsonb_to_recordset(p_changes) as entries(appointment_id uuid, action text, technician_ids uuid[])
  loop
    if change.action not in ('ASSIGN', 'REMOVE', 'RESCHEDULE') then
      raise exception 'Choose what happens to every visit.';
    end if;

    select * into visit from public.appointments a where a.id = change.appointment_id for update;
    if visit.id is null then raise exception 'One of those visits no longer exists. Reload and try again.'; end if;
    if visit.status not in ('Pending', 'Confirmed', 'Reschedule') then
      raise exception 'Visit % is already %; it cannot be reassigned here.', coalesce(visit.reference, visit.id::text), lower(visit.status);
    end if;

    select coalesce(array_agg(at.technician_id order by at.is_lead desc, at.assigned_at), '{}') into old_crew
    from public.appointment_technicians at where at.appointment_id = visit.id;
    if cardinality(old_crew) = 0 and visit.technician_id is not null then old_crew := array[visit.technician_id]; end if;
    if not (p_absent_technician_id = any(old_crew)) then
      raise exception '% is no longer on visit %. Reload and try again.', absent_name, coalesce(visit.reference, visit.id::text);
    end if;

    -- The crew as given, lead first; a name given twice counts once.
    new_crew := array(
      select ids.id
      from unnest(coalesce(change.technician_ids, '{}')) with ordinality as ids(id, ord)
      where ids.id is not null
      group by ids.id
      order by min(ids.ord)
    );

    if p_absent_technician_id = any(new_crew) then
      raise exception '% cannot cover their own visit.', absent_name;
    end if;
    if change.action = 'ASSIGN' and cardinality(new_crew) = 0 then
      raise exception 'Choose who covers visit %.', coalesce(visit.reference, visit.id::text);
    end if;
    if change.action <> 'ASSIGN' and exists (select 1 from unnest(new_crew) as n(id) where not (n.id = any(old_crew))) then
      raise exception 'Only an assigned visit can take someone new.';
    end if;

    perform public.assert_technicians_available(visit.id, new_crew, visit.scheduled_at, visit.duration_minutes);
    perform public.set_appointment_technicians(visit.id, case when cardinality(new_crew) = 0 then null else new_crew end);

    note_line := to_char(now() at time zone 'Asia/Manila', 'Mon DD') || ': ' || absent_name || ' unavailable'
      || coalesce(' (' || nullif(trim(coalesce(p_reason, '')), '') || ')', '') || ' — '
      || case change.action
           when 'ASSIGN' then 'covered by ' || coalesce((
             select string_agg(t.name, ', ') from public.technicians t
             where t.id = any(new_crew) and not (t.id = any(old_crew))), 'the crew')
           when 'REMOVE' then case when cardinality(new_crew) = 0 then 'left unassigned' else 'the rest of the crew carries on' end
           else 'marked for reschedule'
         end || '.';

    update public.appointments a
      set notes = concat_ws(E'\n', nullif(trim(coalesce(a.notes, '')), ''), note_line),
          status = case when change.action = 'RESCHEDULE' then 'Reschedule' else a.status end
      where a.id = visit.id;

    select c.name into client_name from public.clients c where c.id = visit.client_id;
    insert into public.notifications (recipient_id, appointment_id, message)
    select n.id, visit.id,
           'You are covering ' || absent_name || '''s visit for ' || coalesce(client_name, 'a client') || ' on '
           || to_char(visit.scheduled_at at time zone 'Asia/Manila', 'Mon DD, HH12:MI AM') || '.'
    from unnest(new_crew) as n(id)
    where not (n.id = any(old_crew));

    changed := changed + 1;
  end loop;

  return changed;
end;
$$;


--
-- Name: record_appointment_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_appointment_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return new;
  end if;
  insert into public.appointment_status_history (appointment_id, from_status, to_status, changed_by, changed_by_name)
  values (
    new.id,
    case when tg_op = 'UPDATE' then old.status end,
    new.status,
    public.current_account_id(),
    public.billing_actor_name()
  );
  return new;
end;
$$;


--
-- Name: record_contract_deposit(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_contract_deposit(p_contract_id uuid, p_payment jsonb) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  today date := (now() at time zone 'Asia/Manila')::date;
  target public.contracts;
  created public.payments;
  v_amount numeric := (p_payment->>'amount')::numeric;
  v_paid_on date := coalesce((p_payment->>'paid_on')::date, today);
  v_method text := upper(coalesce(p_payment->>'method', ''));
  already numeric;
begin
  perform public.assert_billing_office();
  select * into target from public.contracts c where c.id = p_contract_id for update;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  if target.status <> 'ACTIVE' then raise exception 'A down payment is taken once the contract is signed and active.'; end if;
  if target.deposit_amount <= 0 then raise exception 'Contract % has no down payment set.', target.reference; end if;
  if v_amount is null or v_amount <= 0 then raise exception 'Enter an amount above zero.'; end if;
  if v_paid_on > today then raise exception 'A payment cannot be dated in the future.'; end if;
  if v_method not in ('CASH', 'BANK_TRANSFER', 'GCASH', 'CHECK') then raise exception 'Choose how it was paid.'; end if;
  if v_method = 'CHECK' and nullif(trim(coalesce(p_payment->>'check_number', '')), '') is null then
    raise exception 'Enter the check number.';
  end if;
  select coalesce(sum(p.amount), 0) into already
  from public.payments p where p.contract_id = target.id and p.kind = 'DEPOSIT' and p.reversed_at is null
    and not (p.method = 'CHECK' and p.check_status = 'BOUNCED');
  if already + v_amount > target.deposit_amount then
    raise exception 'That is more than the ₱% down payment. Already received: ₱%.', target.deposit_amount, already;
  end if;

  insert into public.payments (
    client_id, contract_id, kind, amount, paid_on, method, reference_no,
    check_number, check_bank, check_date, check_status, notes, received_by, received_by_name
  )
  values (
    target.client_id, target.id, 'DEPOSIT', round(v_amount, 2), v_paid_on, v_method,
    nullif(trim(coalesce(p_payment->>'reference_no', '')), ''),
    case when v_method = 'CHECK' then trim(p_payment->>'check_number') end,
    case when v_method = 'CHECK' then nullif(trim(coalesce(p_payment->>'check_bank', '')), '') end,
    case when v_method = 'CHECK' then (p_payment->>'check_date')::date end,
    case when v_method = 'CHECK' then 'PENDING' end,
    nullif(trim(coalesce(p_payment->>'notes', '')), ''),
    public.current_account_id(), public.billing_actor_name()
  )
  returning * into created;
  return created;
end;
$$;


--
-- Name: record_inspection(uuid, numeric, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_inspection(p_appointment_id uuid, p_area_sqm numeric, p_service_ids uuid[]) RETURNS public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare visit public.appointments;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  select * into visit from public.appointments a where a.id = p_appointment_id for update;
  if visit.id is null then raise exception 'Appointment not found.'; end if;
  if public.current_account_role() not in ('ADMIN', 'STAFF') and not public.is_assigned_to_appointment(visit.id) then
    raise exception 'Only the office or the visit''s crew can record its inspection.';
  end if;
  if p_area_sqm is not null and (p_area_sqm <= 0 or p_area_sqm > 1000000) then
    raise exception 'Enter an area between 1 and 1,000,000 sqm.';
  end if;
  if exists (select 1 from unnest(coalesce(p_service_ids, '{}')) as wanted(id)
             where not exists (select 1 from public.services s where s.id = wanted.id)) then
    raise exception 'A recommended service was not found.';
  end if;
  update public.appointments a set
    inspection_area_sqm = p_area_sqm,
    recommended_service_ids = coalesce(p_service_ids, '{}')
  where a.id = visit.id
  returning * into visit;
  return visit;
end;
$$;


--
-- Name: record_payment(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment(p_payment jsonb) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  today date := (now() at time zone 'Asia/Manila')::date;
  q_row public.quotes;
  inv public.invoices;
  created public.payments;
  v_kind text := upper(coalesce(p_payment->>'kind', ''));
  v_amount numeric := (p_payment->>'amount')::numeric;
  v_paid_on date := coalesce((p_payment->>'paid_on')::date, today);
  v_method text := upper(coalesce(p_payment->>'method', ''));
  v_client uuid;
  already numeric;
begin
  perform public.assert_billing_office();

  if v_kind not in ('DEPOSIT', 'PAYMENT') then raise exception 'A payment is a down payment or a payment on an invoice.'; end if;
  if v_amount is null or v_amount <= 0 then raise exception 'Enter an amount above zero.'; end if;
  if v_paid_on > today then raise exception 'A payment cannot be dated in the future.'; end if;
  if v_method not in ('CASH', 'BANK_TRANSFER', 'GCASH', 'CHECK') then raise exception 'Choose how it was paid.'; end if;
  if v_method = 'CHECK' and nullif(trim(coalesce(p_payment->>'check_number', '')), '') is null then
    raise exception 'Enter the check number.';
  end if;

  if v_kind = 'DEPOSIT' then
    select * into q_row from public.quotes q where q.id = nullif(p_payment->>'quote_id', '')::uuid for update;
    if q_row.id is null then raise exception 'That quote was not found.'; end if;
    if q_row.status <> 'APPROVED' then raise exception 'A down payment is taken on an approved quote.'; end if;
    select coalesce(sum(p.amount), 0) into already
    from public.payments p where p.quote_id = q_row.id and p.kind = 'DEPOSIT' and p.reversed_at is null
      and not (p.method = 'CHECK' and p.check_status = 'BOUNCED');
    if already + v_amount > q_row.total then
      raise exception 'That would take more than the quote total (₱%). Already received: ₱%.', q_row.total, already;
    end if;
    v_client := q_row.client_id;
  else
    select * into inv from public.invoices i where i.id = nullif(p_payment->>'invoice_id', '')::uuid for update;
    if inv.id is null then raise exception 'That invoice was not found.'; end if;
    if inv.status = 'VOID' then raise exception 'Invoice % was voided.', inv.reference; end if;
    select coalesce(sum(p.amount), 0) into already
    from public.payments p where p.invoice_id = inv.id and p.kind = 'PAYMENT' and p.reversed_at is null
      and not (p.method = 'CHECK' and p.check_status = 'BOUNCED');
    if already + v_amount > inv.amount_due then
      raise exception 'That is more than the ₱% still due on %.', greatest(inv.amount_due - already, 0), inv.reference;
    end if;
    v_client := inv.client_id;
  end if;

  insert into public.payments (
    client_id, quote_id, invoice_id, kind, amount, paid_on, method, reference_no,
    check_number, check_bank, check_date, check_status, notes, received_by, received_by_name
  )
  values (
    v_client, q_row.id, inv.id, v_kind, round(v_amount, 2), v_paid_on, v_method,
    nullif(trim(coalesce(p_payment->>'reference_no', '')), ''),
    case when v_method = 'CHECK' then trim(p_payment->>'check_number') end,
    case when v_method = 'CHECK' then nullif(trim(coalesce(p_payment->>'check_bank', '')), '') end,
    case when v_method = 'CHECK' then (p_payment->>'check_date')::date end,
    case when v_method = 'CHECK' then 'PENDING' end,
    nullif(trim(coalesce(p_payment->>'notes', '')), ''),
    public.current_account_id(), public.billing_actor_name()
  )
  returning * into created;

  return created;
end;
$$;


--
-- Name: record_site_monitoring(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_site_monitoring(p_appointment_id uuid, p_activity_level text, p_open_issues text DEFAULT NULL::text) RETURNS public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  visit public.appointments;
  v_level text := nullif(upper(trim(coalesce(p_activity_level, ''))), '');
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  select * into visit from public.appointments a where a.id = p_appointment_id for update;
  if visit.id is null then raise exception 'Appointment not found.'; end if;
  if public.current_account_role() not in ('ADMIN', 'STAFF') and not public.is_assigned_to_appointment(visit.id) then
    raise exception 'Only the office or the visit''s crew can record its monitoring.';
  end if;
  if visit.status = 'Cancelled' then raise exception 'A cancelled visit has nothing to record.'; end if;
  if v_level is not null and v_level not in ('NONE', 'LOW', 'MEDIUM', 'HIGH') then
    raise exception 'Activity level is None, Low, Medium or High.';
  end if;
  if char_length(coalesce(p_open_issues, '')) > 2000 then raise exception 'Keep the open issues under 2,000 characters.'; end if;

  update public.appointments a set
    activity_level = v_level,
    open_issues = nullif(trim(coalesce(p_open_issues, '')), '')
  where a.id = visit.id
  returning * into visit;
  return visit;
end;
$$;


--
-- Name: refuse_deleting_used_service(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refuse_deleting_used_service() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if public.service_in_use(old.id) then
    raise exception 'The service "%" has been used on visits, so it can''t be deleted. Retire it instead.', old.name;
  end if;
  return old;
end;
$$;


--
-- Name: refuse_system_log_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refuse_system_log_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'The activity log cannot be changed or deleted.';
end;
$$;


--
-- Name: report_checkout_loss(uuid, numeric, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_checkout_loss(p_checkout_id uuid, p_amount numeric, p_kind text, p_note text, p_movement_date date DEFAULT NULL::date) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, remaining numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  checkout public.inventory_movements;
  left_out numeric;
  technician_name text;
  actor_name text;
  actor_account_id uuid;
  movement_id_value uuid;
  happened_on date;
  label text;
begin
  if coalesce(public.current_account_role(), '') not in ('ADMIN', 'STAFF') then
    raise exception 'Only the office can report stock as lost or damaged.';
  end if;
  if p_kind is null or p_kind not in ('LOST', 'STOLEN', 'DAMAGED') then
    raise exception 'Choose whether the stock was lost, stolen or damaged.';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Enter a quantity greater than zero.'; end if;
  if nullif(trim(coalesce(p_note, '')), '') is null then
    raise exception 'Write what happened.';
  end if;

  select * into checkout from public.inventory_movements m
  where m.id = p_checkout_id and m.stock_out_reason = 'TECHNICIAN_CHECKOUT';
  if checkout.id is null then raise exception 'That checkout was not found.'; end if;
  if checkout.custody_closed_at is not null then
    raise exception 'That checkout was settled before custody was tracked.';
  end if;

  -- Serialise with return_checkout() and visit draws on the same item.
  perform 1 from public.inventory i where i.id = checkout.item_id for update;

  left_out := public.checkout_remaining(checkout.id);
  if p_amount > left_out then
    raise exception 'Only % is still out on this checkout.', left_out;
  end if;

  happened_on := coalesce(p_movement_date, current_date);
  if happened_on < checkout.movement_date then
    raise exception 'A loss cannot be dated before the checkout.';
  end if;

  select t.name into technician_name from public.technicians t where t.id = checkout.technician_id;

  select r.id, coalesce(a.name, s.name, t.name) into actor_account_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id
  left join public.staff s on s.id = r.id
  left join public.technicians t on t.id = r.id
  limit 1;

  label := case p_kind when 'LOST' then 'Lost' when 'STOLEN' then 'Stolen' else 'Damaged' end
    || ' while with ' || coalesce(technician_name, 'a technician');

  insert into public.inventory_movements (
    item_id, amount, quantity_delta, movement_date, reference, actor, actor_id,
    movement_type, stock_out_reason, technician_id, note, checkout_id, batch_id, batch_number
  )
  values (
    checkout.item_id, p_amount, 0, happened_on, label, actor_name, actor_account_id,
    'OUT', case when p_kind = 'DAMAGED' then 'DAMAGED' else 'MISSING' end, checkout.technician_id,
    trim(p_note), checkout.id, checkout.batch_id, checkout.batch_number
  )
  returning id into movement_id_value;

  return query select movement_id_value, checkout.item_id, p_amount, happened_on, left_out - p_amount;
end;
$$;


--
-- Name: request_password_reset(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_password_reset(target_email text) RETURNS TABLE(user_id uuid, user_name text, user_email text, temp_password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  target_id uuid;
  target_name text;
  found_email text;
  target_role text;
  generated_password text;
begin
  select id, name, email, role_name into target_id, target_name, found_email, target_role
  from (
    select id, name, email, status, 'ADMIN'::text role_name from admins
    union all select id, name, email, status, 'STAFF'::text from staff
    union all select id, name, email, status, 'TECHNICIAN'::text from technicians
  ) accounts
  where lower(accounts.email) = lower(target_email)
    -- A deactivated account is not a candidate for a reset: issuing one would
    -- mail a working password to someone who is not allowed back in.
    and accounts.status <> 'INACTIVE'
  limit 1;

  -- Same silence as an unknown email, deliberately: the caller cannot use
  -- this endpoint to learn whether an address is registered or deactivated.
  if target_id is null then
    return;
  end if;

  generated_password := substr(md5(random()::text || clock_timestamp()::text), 1, 10) || floor(random() * 90 + 10)::text;

  execute format(
    'update %I set password_hash = crypt($1, gen_salt(''bf'')), password = '''', '
    || 'status = case when status = ''INACTIVE'' then ''INACTIVE''::account_status '
    || 'else ''PENDING''::account_status end where id = $2',
    case target_role when 'ADMIN' then 'admins' when 'STAFF' then 'staff' else 'technicians' end
  )
    using generated_password, target_id;

  delete from sessions where sessions.user_id = target_id;

  insert into system_logs (actor_id, actor_name, message, type)
    values (target_id, target_name, 'Requested a password reset.', 'auth');

  return query select target_id, target_name, found_email, generated_password;
end;
$_$;


--
-- Name: reset_password(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_password(session_token uuid, target_id uuid, new_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  caller_id uuid;
  caller_role text;
  caller_name text;
  target_role text;
  target_name text;
  target_table text;
begin
  select r.id, r.role_name into caller_id, caller_role
  from public.role_account_for_session(session_token) r
  limit 1;
  if caller_id is null then raise exception 'Not signed in.'; end if;
  if caller_role <> 'ADMIN' then
    raise exception 'You do not have permission to reset passwords.';
  end if;

  select a.name into caller_name from public.admins a where a.id = caller_id;

  select accounts.role_name, accounts.name into target_role, target_name
  from (
    select id, name, 'ADMIN'::text role_name from public.admins
    union all select id, name, 'STAFF'::text from public.staff
    union all select id, name, 'TECHNICIAN'::text from public.technicians
  ) accounts
  where accounts.id = target_id;
  if target_role is null then raise exception 'Account not found.'; end if;

  -- Migration 014's rule, carried over: one admin may not act on another.
  if target_role = 'ADMIN' and caller_id <> target_id then
    raise exception 'You cannot reset the password of another Admin.';
  end if;

  if new_password is null
     or length(new_password) < 6
     or new_password !~ '[A-Za-z]'
     or new_password !~ '[0-9]' then
    raise exception 'Password must be at least 6 characters and include a letter and a number.';
  end if;

  target_table := case target_role
    when 'ADMIN' then 'admins' when 'STAFF' then 'staff' else 'technicians' end;

  -- THE CHANGE: PENDING unless the account is deactivated, in which case it
  -- stays deactivated. Everything else is migration 044's statement.
  execute format(
    'update %I set password_hash = crypt($1, gen_salt(''bf'')), password = '''', '
    || 'status = case when status = ''INACTIVE'' then ''INACTIVE''::account_status '
    || 'else ''PENDING''::account_status end where id = $2',
    target_table
  ) using new_password, target_id;

  delete from public.sessions where sessions.user_id = target_id;

  insert into public.system_logs (actor_id, actor_name, message, type)
  values (caller_id, coalesce(caller_name, 'Administrator'),
          format('Reset the password for %s.', target_name), 'auth');
end;
$_$;


--
-- Name: return_checkout(uuid, numeric, text, uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_checkout(p_checkout_id uuid, p_amount numeric, p_reason text, p_appointment_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_movement_date date DEFAULT NULL::date) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, new_quantity numeric, remaining numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  checkout public.inventory_movements;
  item_kind text;
  target_batch uuid;
  target_label text;
  left_out numeric;
  visit uuid;
  visit_status text;
  visit_reference text;
  technician_name text;
  actor_name text;
  actor_account_id uuid;
  movement_id_value uuid;
  new_quantity_value numeric;
  returned_on date;
  label text;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if p_reason is null or p_reason not in ('VISIT_CANCELLED', 'LEFTOVER', 'NOT_NEEDED', 'OTHER') then
    raise exception 'Choose why the stock is coming back.';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Enter a quantity greater than zero.'; end if;
  if p_reason = 'OTHER' and nullif(trim(coalesce(p_note, '')), '') is null then
    raise exception 'Write a note saying why the stock is coming back.';
  end if;

  select * into checkout from public.inventory_movements m
  where m.id = p_checkout_id and m.stock_out_reason = 'TECHNICIAN_CHECKOUT';
  if checkout.id is null then raise exception 'That checkout was not found.'; end if;
  if checkout.custody_closed_at is not null then
    raise exception 'That checkout was settled before returns existed. Record a Stock In or correction instead.';
  end if;

  select i.type::text into item_kind from public.inventory i where i.id = checkout.item_id for update;

  left_out := public.checkout_remaining(checkout.id);
  if p_amount > left_out then
    raise exception 'Only % is still out on this checkout.', left_out;
  end if;

  returned_on := coalesce(p_movement_date, current_date);
  if returned_on < checkout.movement_date then
    raise exception 'A return cannot be dated before the checkout.';
  end if;

  visit := coalesce(p_appointment_id, checkout.for_appointment_id);
  if p_reason = 'VISIT_CANCELLED' then
    if visit is null then raise exception 'Choose the visit that was cancelled.'; end if;
    select a.status, coalesce(a.reference, 'a visit') into visit_status, visit_reference
    from public.appointments a where a.id = visit;
    if visit_status is null then raise exception 'That visit was not found.'; end if;
    if visit_status <> 'Cancelled' then
      raise exception 'That visit is not cancelled. Cancel it first, or choose another reason.';
    end if;
  end if;

  -- The batch the stock left in; a checkout from before batches goes to the
  -- item's opening batch, whose lot is unknown too.
  if item_kind = 'CHEMICAL' then
    target_batch := coalesce(checkout.batch_id, public.fallback_batch(checkout.item_id, returned_on));
    update public.inventory_batches b set quantity = b.quantity + p_amount where b.id = target_batch
      returning coalesce(b.lot_number, b.reference) into target_label;
  end if;

  select t.name into technician_name from public.technicians t where t.id = checkout.technician_id;

  select r.id, coalesce(a.name, s.name, t.name) into actor_account_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id
  left join public.staff s on s.id = r.id
  left join public.technicians t on t.id = r.id
  limit 1;

  label := 'Returned by ' || coalesce(technician_name, 'a technician') || ' · ' || case p_reason
    when 'VISIT_CANCELLED' then 'visit ' || visit_reference || ' cancelled'
    when 'LEFTOVER' then 'leftover after the visit'
    when 'NOT_NEEDED' then 'not needed'
    else 'other'
  end;

  insert into public.inventory_movements (
    item_id, amount, quantity_delta, movement_date, reference, actor, actor_id,
    movement_type, technician_id, note, checkout_id, for_appointment_id, return_reason, batch_id, batch_number
  )
  values (
    checkout.item_id, p_amount, p_amount, returned_on, label, actor_name, actor_account_id,
    'RETURN', checkout.technician_id, nullif(trim(coalesce(p_note, '')), ''), checkout.id, visit, p_reason,
    target_batch, target_label
  )
  returning id into movement_id_value;

  update public.inventory i set quantity = i.quantity + p_amount
  where i.id = checkout.item_id
  returning i.quantity into new_quantity_value;

  return query select movement_id_value, checkout.item_id, p_amount, returned_on, new_quantity_value, left_out - p_amount;
end;
$$;


--
-- Name: reverse_payment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_payment(p_payment_id uuid, p_reason text) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.payments;
begin
  perform public.assert_billing_office();
  if public.current_account_role() <> 'ADMIN' then raise exception 'Only an admin can reverse a payment.'; end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then raise exception 'Write why the payment is being reversed.'; end if;
  select * into target from public.payments p where p.id = p_payment_id for update;
  if target.id is null then raise exception 'That payment was not found.'; end if;
  if target.reversed_at is not null then raise exception 'That payment was already reversed.'; end if;
  update public.payments p set reversed_at = now(), reversed_by = public.current_account_id(), reversal_reason = trim(p_reason)
  where p.id = p_payment_id returning * into target;
  return target;
end;
$$;


--
-- Name: revise_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revise_quote(p_quote_id uuid) RETURNS public.quotes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  source public.quotes;
  created public.quotes;
  today date := (now() at time zone 'Asia/Manila')::date;
begin
  perform public.assert_billing_office();
  select * into source from public.quotes q where q.id = p_quote_id;
  if source.id is null then raise exception 'That quote was not found.'; end if;

  insert into public.quotes (
    client_id, valid_until, payment_terms, area_sqm, discount_type, discount_value, vat_mode, vat_rate,
    deposit_type, deposit_value, subtotal, discount_amount, vat_amount, total, deposit_amount, notes,
    revision_of, created_by
  )
  values (
    source.client_id, greatest(source.valid_until, today + 30), source.payment_terms, source.area_sqm,
    source.discount_type, source.discount_value, source.vat_mode, source.vat_rate,
    source.deposit_type, source.deposit_value, source.subtotal, source.discount_amount, source.vat_amount,
    source.total, source.deposit_amount, source.notes, source.id, public.current_account_id()
  )
  returning * into created;

  insert into public.quote_lines (quote_id, position, kind, service_id, item_id, description, quantity, unit, unit_price, amount)
  select created.id, l.position, l.kind, l.service_id, l.item_id, l.description, l.quantity, l.unit, l.unit_price, l.amount
  from public.quote_lines l where l.quote_id = source.id;

  return created;
end;
$$;


--
-- Name: role_account_for_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.role_account_for_session(session_token uuid) RETURNS TABLE(id uuid, role_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select a.id, 'ADMIN'::text from sessions s join admins a on a.id = s.user_id
    where s.token = session_token and s.user_role = 'ADMIN' and s.expires_at > now() and a.status = 'ACTIVE'
  union all
  select a.id, 'STAFF'::text from sessions s join staff a on a.id = s.user_id
    where s.token = session_token and s.user_role = 'STAFF' and s.expires_at > now() and a.status = 'ACTIVE'
  union all
  select a.id, 'TECHNICIAN'::text from sessions s join technicians a on a.id = s.user_id
    where s.token = session_token and s.user_role = 'TECHNICIAN' and s.expires_at > now() and a.status = 'ACTIVE';
$$;


--
-- Name: save_contract(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_contract(p_contract_id uuid, p_contract jsonb) RETURNS public.contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.contracts;
  v_client uuid := (p_contract->>'client_id')::uuid;
  v_quote uuid := nullif(p_contract->>'quote_id', '')::uuid;
  v_services uuid[] := coalesce(
    (select array_agg(value::uuid) from jsonb_array_elements_text(coalesce(p_contract->'service_ids', '[]'::jsonb))),
    '{}'::uuid[]
  );
  v_count integer := nullif(p_contract->>'visit_count', '')::integer;
  v_starts date := nullif(p_contract->>'starts_on', '')::date;
  v_ends date := nullif(p_contract->>'ends_on', '')::date;
  v_price numeric := coalesce(nullif(p_contract->>'price_per_visit', '')::numeric, 0);
  v_area numeric := nullif(p_contract->>'area_sqm', '')::numeric;
  v_names text;
begin
  perform public.assert_billing_office();

  if v_client is null or not exists (select 1 from public.clients c where c.id = v_client) then
    raise exception 'Choose the client for this contract.';
  end if;
  if nullif(trim(coalesce(p_contract->>'title', '')), '') is null then raise exception 'Give the contract a title.'; end if;
  if cardinality(v_services) = 0 then raise exception 'Choose the services the contract covers.'; end if;
  if nullif(trim(coalesce(p_contract->>'frequency', '')), '') is null then raise exception 'Choose how often the visits are.'; end if;
  if v_starts is null then raise exception 'Enter the start date.'; end if;
  if v_count is null and v_ends is null then raise exception 'Enter the number of visits or the end date.'; end if;
  if v_ends is not null and v_ends < v_starts then raise exception 'The end date is before the start date.'; end if;
  if v_area is not null and (v_area <= 0 or v_area > 1000000) then raise exception 'Enter an area between 1 and 1,000,000 sqm.'; end if;
  if v_price < 0 or v_price > 999999.99 then raise exception 'Enter a price per visit up to ₱999,999.99.'; end if;
  if v_quote is not null and not exists (select 1 from public.quotes q where q.id = v_quote and q.client_id = v_client) then
    raise exception 'That quote is for a different client.';
  end if;

  select string_agg(s.name, ', ' order by array_position(v_services, s.id)) into v_names
  from public.services s where s.id = any(v_services);

  if p_contract_id is null then
    insert into public.contracts (
      client_id, quote_id, title, service_ids, service_names, frequency, visit_count, starts_on, ends_on,
      area_sqm, price_per_visit, billing_schedule, payment_terms, inclusions, cancellation_terms, notes, created_by
    )
    values (
      v_client, v_quote, trim(p_contract->>'title'), v_services, v_names, trim(p_contract->>'frequency'), v_count, v_starts, v_ends,
      v_area, round(v_price, 2), coalesce(p_contract->>'billing_schedule', 'PER_VISIT'), coalesce(p_contract->>'payment_terms', 'DUE_ON_RECEIPT'),
      nullif(trim(coalesce(p_contract->>'inclusions', '')), ''), nullif(trim(coalesce(p_contract->>'cancellation_terms', '')), ''),
      nullif(trim(coalesce(p_contract->>'notes', '')), ''), public.current_account_id()
    )
    returning * into target;
  else
    select * into target from public.contracts c where c.id = p_contract_id for update;
    if target.id is null then raise exception 'That contract was not found.'; end if;
    if target.status <> 'DRAFT' then
      raise exception 'Contract % is %: its terms are what was signed and can no longer be changed.', target.reference, lower(target.status);
    end if;
    update public.contracts c set
      client_id = v_client, quote_id = v_quote, title = trim(p_contract->>'title'),
      service_ids = v_services, service_names = v_names, frequency = trim(p_contract->>'frequency'),
      visit_count = v_count, starts_on = v_starts, ends_on = v_ends, area_sqm = v_area, price_per_visit = round(v_price, 2),
      billing_schedule = coalesce(p_contract->>'billing_schedule', 'PER_VISIT'),
      payment_terms = coalesce(p_contract->>'payment_terms', 'DUE_ON_RECEIPT'),
      inclusions = nullif(trim(coalesce(p_contract->>'inclusions', '')), ''),
      cancellation_terms = nullif(trim(coalesce(p_contract->>'cancellation_terms', '')), ''),
      notes = nullif(trim(coalesce(p_contract->>'notes', '')), ''),
      -- A draft moved to another client can't keep the first client's file.
      signed_document_id = case when v_client = target.client_id then target.signed_document_id end,
      updated_at = now()
    where c.id = target.id
    returning * into target;
  end if;
  return target;
end;
$$;


--
-- Name: save_quote(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_quote(p_quote_id uuid, p_quote jsonb, p_lines jsonb) RETURNS public.quotes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  today date := (now() at time zone 'Asia/Manila')::date;
  target public.quotes;
  entry_row record;
  lines_total numeric := 0;
  discount numeric;
  net numeric;
  vat numeric;
  grand numeric;
  deposit numeric;
  line_no integer := 0;
  v_client uuid := (p_quote->>'client_id')::uuid;
  v_valid date := (p_quote->>'valid_until')::date;
  v_discount_type text := coalesce(p_quote->>'discount_type', 'AMOUNT');
  v_discount_value numeric := coalesce((p_quote->>'discount_value')::numeric, 0);
  v_vat_mode text := coalesce(p_quote->>'vat_mode', 'ADDED');
  v_vat_rate numeric := coalesce((p_quote->>'vat_rate')::numeric, 12);
  v_deposit_type text := coalesce(p_quote->>'deposit_type', 'NONE');
  v_deposit_value numeric := coalesce((p_quote->>'deposit_value')::numeric, 0);
begin
  perform public.assert_billing_office();

  if v_client is null or not exists (select 1 from public.clients c where c.id = v_client) then
    raise exception 'Choose the client for this quote.';
  end if;
  if v_valid is null then raise exception 'Set how long the quote is valid.'; end if;
  if v_valid < today then raise exception 'A quote cannot be valid only until a past date.'; end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Add at least one service, material or extra to the quote.';
  end if;
  if v_discount_type = 'PERCENT' and v_discount_value > 100 then raise exception 'A discount cannot be more than 100%%.'; end if;
  if v_deposit_type = 'PERCENT' and v_deposit_value > 100 then raise exception 'A down payment cannot be more than 100%%.'; end if;

  if p_quote_id is not null then
    select * into target from public.quotes q where q.id = p_quote_id for update;
    if target.id is null then raise exception 'That quote was not found.'; end if;
    if target.status not in ('DRAFT', 'SENT') then
      raise exception 'Quote % is %: it can no longer be changed. Revise it to make a new version.', target.reference, lower(target.status);
    end if;
  end if;

  for entry_row in
    select entries.kind, entries.quantity, entries.unit_price
    from jsonb_to_recordset(p_lines) as entries(kind text, quantity numeric, unit_price numeric)
  loop
    if entry_row.quantity is null or entry_row.quantity <= 0 then raise exception 'Every line needs a quantity above zero.'; end if;
    if entry_row.unit_price is null or entry_row.unit_price < 0 then raise exception 'Every line needs a price.'; end if;
    lines_total := lines_total + round(entry_row.quantity * entry_row.unit_price, 2);
  end loop;

  discount := round(case when v_discount_type = 'PERCENT' then lines_total * v_discount_value / 100 else least(v_discount_value, lines_total) end, 2);
  net := lines_total - discount;
  vat := round(case v_vat_mode
    when 'ADDED' then net * v_vat_rate / 100
    when 'INCLUSIVE' then net - net / (1 + v_vat_rate / 100)
    else 0 end, 2);
  grand := case when v_vat_mode = 'ADDED' then net + vat else net end;
  deposit := round(case v_deposit_type
    when 'PERCENT' then grand * v_deposit_value / 100
    when 'AMOUNT' then least(v_deposit_value, grand)
    else 0 end, 2);

  if p_quote_id is null then
    insert into public.quotes (
      client_id, valid_until, payment_terms, area_sqm, discount_type, discount_value, vat_mode, vat_rate,
      deposit_type, deposit_value, subtotal, discount_amount, vat_amount, total, deposit_amount, notes,
      revision_of, created_by
    )
    values (
      v_client, v_valid, coalesce(p_quote->>'payment_terms', 'DUE_ON_RECEIPT'), nullif(p_quote->>'area_sqm', '')::numeric,
      v_discount_type, v_discount_value, v_vat_mode, v_vat_rate, v_deposit_type, v_deposit_value,
      lines_total, discount, vat, grand, deposit, nullif(trim(coalesce(p_quote->>'notes', '')), ''),
      nullif(p_quote->>'revision_of', '')::uuid, public.current_account_id()
    )
    returning * into target;
  else
    update public.quotes q set
      client_id = v_client, valid_until = v_valid,
      payment_terms = coalesce(p_quote->>'payment_terms', 'DUE_ON_RECEIPT'),
      area_sqm = nullif(p_quote->>'area_sqm', '')::numeric,
      discount_type = v_discount_type, discount_value = v_discount_value,
      vat_mode = v_vat_mode, vat_rate = v_vat_rate,
      deposit_type = v_deposit_type, deposit_value = v_deposit_value,
      subtotal = lines_total, discount_amount = discount, vat_amount = vat, total = grand, deposit_amount = deposit,
      notes = nullif(trim(coalesce(p_quote->>'notes', '')), ''),
      -- Changed after it was sent: it has to go out again.
      status = 'DRAFT', sent_at = null,
      updated_at = now()
    where q.id = p_quote_id
    returning * into target;
    delete from public.quote_lines l where l.quote_id = target.id;
  end if;

  for entry_row in
    select entries.kind, entries.service_id, entries.item_id, entries.description, entries.quantity, entries.unit, entries.unit_price
    from jsonb_to_recordset(p_lines) as entries(kind text, service_id uuid, item_id uuid, description text, quantity numeric, unit text, unit_price numeric)
  loop
    insert into public.quote_lines (quote_id, position, kind, service_id, item_id, description, quantity, unit, unit_price, amount)
    values (
      target.id, line_no, upper(entry_row.kind), entry_row.service_id, entry_row.item_id,
      trim(entry_row.description), entry_row.quantity, nullif(trim(coalesce(entry_row.unit, '')), ''),
      entry_row.unit_price, round(entry_row.quantity * entry_row.unit_price, 2)
    );
    line_no := line_no + 1;
  end loop;

  return target;
end;
$$;


--
-- Name: send_quote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_quote(p_quote_id uuid) RETURNS public.quotes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.quotes;
begin
  perform public.assert_billing_office();
  select * into target from public.quotes q where q.id = p_quote_id for update;
  if target.id is null then raise exception 'That quote was not found.'; end if;
  if target.status <> 'DRAFT' then raise exception 'Only a draft can be marked as sent.'; end if;
  if target.valid_until < (now() at time zone 'Asia/Manila')::date then
    raise exception 'This quote''s validity date has passed. Change it before sending.';
  end if;
  update public.quotes q set status = 'SENT', sent_at = now(), updated_at = now()
  where q.id = p_quote_id returning * into target;
  return target;
end;
$$;


--
-- Name: service_in_use(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.service_in_use(p_service_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from public.appointments a where a.service_id = p_service_id)
      or exists (select 1 from public.appointment_services s where s.service_id = p_service_id)
      or exists (select 1 from public.quote_lines l where l.service_id = p_service_id)
      or exists (select 1 from public.invoice_lines l where l.service_id = p_service_id)
      or exists (select 1 from public.contracts c where p_service_id = any(c.service_ids));
$$;


--
-- Name: services_no_chemicals_when_non_chemical(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.services_no_chemicals_when_non_chemical() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.category = 'NON_CHEMICAL' and exists (
    select 1 from public.service_materials sm join public.inventory i on i.id = sm.item_id
    where sm.service_id = new.id and i.type = 'CHEMICAL'
  ) then
    raise exception 'Remove the chemicals from % first. A non-chemical service can''t use chemicals.', new.name;
  end if;
  return new;
end;
$$;


--
-- Name: set_appointment_services(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_appointment_services(p_appointment_id uuid, p_service_ids uuid[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare joined text;
begin
  if p_service_ids is null or cardinality(p_service_ids) = 0 then
    select service_type into joined from public.appointments where id = p_appointment_id;
    return joined;
  end if;

  if exists (
    select 1 from unnest(p_service_ids) as ids(id)
    where ids.id is null or not exists (select 1 from public.services s where s.id = ids.id)
  ) then
    raise exception 'One of those services no longer exists. Choose again.';
  end if;

  delete from public.appointment_services where appointment_id = p_appointment_id;

  insert into public.appointment_services (appointment_id, position, service_id, service_name)
  select p_appointment_id, (row_number() over (order by chosen.first_position))::integer - 1, chosen.id, chosen.name
  from (
    select s.id, s.name, min(ids.ord) as first_position
    from unnest(p_service_ids) with ordinality as ids(id, ord)
    join public.services s on s.id = ids.id
    group by s.id, s.name
  ) chosen;

  update public.appointments a
    set service_id = (select x.service_id from public.appointment_services x
                      where x.appointment_id = p_appointment_id order by x.position limit 1),
        service_type = (select string_agg(x.service_name, ', ' order by x.position)
                        from public.appointment_services x where x.appointment_id = p_appointment_id)
    where a.id = p_appointment_id
    returning a.service_type into joined;
  return joined;
end;
$$;


--
-- Name: set_appointment_technicians(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_appointment_technicians(p_appointment_id uuid, p_technician_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.appointment_technicians at
  where at.appointment_id = p_appointment_id
    and (p_technician_ids is null or not (at.technician_id = any (p_technician_ids)));

  if p_technician_ids is null then
    update public.appointments set technician_id = null where id = p_appointment_id;
    return;
  end if;

  -- Clear the old lead before writing the new one: appointment_technicians_one_lead_idx
  -- allows a single is_lead row per appointment, and swapping the lead between two
  -- people who are both staying on the job would otherwise collide mid-statement.
  update public.appointment_technicians
  set is_lead = false
  where appointment_id = p_appointment_id and is_lead;

  insert into public.appointment_technicians (appointment_id, technician_id, is_lead)
  select p_appointment_id, entry.technician_id, entry.position = 1
  from (
    select distinct on (ids.technician_id) ids.technician_id, ids.position
    from unnest(p_technician_ids) with ordinality as ids(technician_id, position)
    where ids.technician_id is not null
    order by ids.technician_id, ids.position
  ) entry
  on conflict (appointment_id, technician_id)
  do update set is_lead = excluded.is_lead;

  if not exists (select 1 from public.appointment_technicians at where at.appointment_id = p_appointment_id) then
    update public.appointments set technician_id = null where id = p_appointment_id;
  end if;
end;
$$;


--
-- Name: set_check_status(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_check_status(p_payment_id uuid, p_status text, p_on date DEFAULT NULL::date, p_note text DEFAULT NULL::text) RETURNS public.payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.payments;
begin
  perform public.assert_billing_office();
  if upper(coalesce(p_status, '')) not in ('CLEARED', 'BOUNCED') then raise exception 'A check either clears or bounces.'; end if;
  if upper(p_status) = 'BOUNCED' and nullif(trim(coalesce(p_note, '')), '') is null then
    raise exception 'Write why the check bounced.';
  end if;
  select * into target from public.payments p where p.id = p_payment_id for update;
  if target.id is null then raise exception 'That payment was not found.'; end if;
  if target.method <> 'CHECK' then raise exception 'That payment was not made by check.'; end if;
  if target.reversed_at is not null then raise exception 'That payment was reversed.'; end if;
  if target.check_status <> 'PENDING' then raise exception 'That check was already marked %.', lower(target.check_status); end if;
  update public.payments p set
    check_status = upper(p_status),
    check_status_on = coalesce(p_on, (now() at time zone 'Asia/Manila')::date),
    check_status_note = nullif(trim(coalesce(p_note, '')), '')
  where p.id = p_payment_id returning * into target;
  return target;
end;
$$;


--
-- Name: set_client_payment_check(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_client_payment_check(p_client_id uuid, p_skip boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_office_account() then
    raise exception 'Only the office can change a client''s payment check.';
  end if;
  update public.clients set skip_payment_check = coalesce(p_skip, false) where id = p_client_id;
  if not found then raise exception 'Client not found.'; end if;
  return coalesce(p_skip, false);
end;
$$;


--
-- Name: set_contract_deposit(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contract_deposit(p_contract_id uuid, p_type text, p_value numeric) RETURNS public.contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.contracts;
  v_type text := upper(coalesce(p_type, 'NONE'));
  v_value numeric := coalesce(p_value, 0);
  v_total numeric;
  v_amount numeric;
begin
  perform public.assert_billing_office();
  select * into target from public.contracts c where c.id = p_contract_id for update;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  if target.status in ('ENDED', 'CANCELLED') then raise exception 'Contract % is %.', target.reference, lower(target.status); end if;
  if exists (select 1 from public.payments p where p.contract_id = target.id and p.reversed_at is null) then
    raise exception 'A down payment was already received on %; it cannot be changed.', target.reference;
  end if;
  if v_type not in ('NONE', 'AMOUNT', 'PERCENT') then raise exception 'Choose none, an amount or a percentage.'; end if;
  if v_value < 0 then raise exception 'The down payment cannot be negative.'; end if;

  v_total := case when target.visit_count is not null then target.price_per_visit * target.visit_count end;
  if v_type = 'PERCENT' then
    if v_value > 100 then raise exception 'A down payment cannot be more than 100%%.'; end if;
    if v_total is null then raise exception 'A contract with an end date takes the down payment as an amount.'; end if;
    v_amount := round(v_total * v_value / 100, 2);
  elsif v_type = 'AMOUNT' then
    if v_total is not null and v_value > v_total then raise exception 'The down payment is more than the contract total (₱%).', v_total; end if;
    v_amount := round(v_value, 2);
  else
    v_amount := 0;
    v_value := 0;
  end if;

  update public.contracts c set deposit_type = v_type, deposit_value = v_value, deposit_amount = v_amount, updated_at = now()
  where c.id = target.id returning * into target;
  return target;
end;
$$;


--
-- Name: set_contract_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contract_status(p_contract_id uuid, p_status text) RETURNS public.contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.contracts;
  v_status text := upper(coalesce(p_status, ''));
begin
  perform public.assert_billing_office();
  select * into target from public.contracts c where c.id = p_contract_id for update;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  if v_status = 'ACTIVE' then
    if target.status <> 'DRAFT' then raise exception 'Only a draft contract can be made active.'; end if;
    if target.signed_document_id is null then raise exception 'Attach the signed contract first.'; end if;
    update public.contracts c set status = 'ACTIVE', activated_at = now(), updated_at = now() where c.id = target.id returning * into target;
  elsif v_status = 'ENDED' then
    if target.status <> 'ACTIVE' then raise exception 'Only an active contract can end.'; end if;
    update public.contracts c set status = 'ENDED', ended_at = now(), updated_at = now() where c.id = target.id returning * into target;
  else
    raise exception 'A contract is made active or ended here; cancel it with a reason instead.';
  end if;
  return target;
end;
$$;


--
-- Name: set_contract_warranty(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_contract_warranty(p_contract_id uuid, p_months integer, p_checkups text) RETURNS public.contracts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.contracts;
begin
  perform public.assert_billing_office();
  if p_months is not null and (p_months < 1 or p_months > 120) then raise exception 'A warranty is between 1 and 120 months.'; end if;
  if p_checkups is not null and p_checkups not in ('MONTHLY', 'QUARTERLY') then raise exception 'Checkups are monthly or quarterly.'; end if;
  update public.contracts c set warranty_months = p_months, checkup_frequency = case when p_months is null then null else p_checkups end, updated_at = now()
  where c.id = p_contract_id returning * into target;
  if target.id is null then raise exception 'That contract was not found.'; end if;
  return target;
end;
$$;


