    created_at timestamp with time zone DEFAULT now() NOT NULL,
    renewal_declined_at timestamp with time zone,
    renewal_declined_by uuid,
    CONSTRAINT appointment_plans_kind_check CHECK ((kind = ANY (ARRAY['RECURRING'::text, 'MULTI_DAY'::text])))
);


--
-- Name: TABLE appointment_plans; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.appointment_plans IS 'A recurring series or a multi-day job. Its visits point here through appointments.plan_id.';


--
-- Name: COLUMN appointment_plans.renewal_declined_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointment_plans.renewal_declined_at IS 'Set when the office decided not to renew this recurring plan; it no longer shows a renewal reminder. Null = remind as usual.';


--
-- Name: set_plan_renewal(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_plan_renewal(p_plan_id uuid, p_renew boolean) RETURNS public.appointment_plans
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare plan_row public.appointment_plans;
begin
  perform public.assert_office();

  select * into plan_row from public.appointment_plans where id = p_plan_id;
  if plan_row.id is null then raise exception 'Plan not found.'; end if;
  if plan_row.kind <> 'RECURRING' then
    raise exception 'Only a recurring plan can be renewed.';
  end if;

  update public.appointment_plans
    set renewal_declined_at = case when p_renew then null else now() end,
        renewal_declined_by = case when p_renew then null else public.current_account_id() end
    where id = p_plan_id
    returning * into plan_row;

  return plan_row;
end;
$$;


--
-- Name: set_quote_inspection(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_quote_inspection(p_quote_id uuid, p_appointment_id uuid) RETURNS public.quotes
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.quotes;
begin
  perform public.assert_billing_office();
  select * into target from public.quotes q where q.id = p_quote_id for update;
  if target.id is null then raise exception 'That quote was not found.'; end if;
  if p_appointment_id is not null and not exists (
    select 1 from public.appointments a where a.id = p_appointment_id and a.client_id = target.client_id
  ) then
    raise exception 'That inspection is for a different client.';
  end if;
  update public.quotes q set inspection_id = p_appointment_id where q.id = target.id returning * into target;
  return target;
end;
$$;


