--
-- Name: set_role_account_status(uuid, uuid, public.account_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_role_account_status(session_token uuid, target_id uuid, new_status public.account_status) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare caller_id uuid; caller_role text; target_role text; updated jsonb; active_admins integer;
begin
  select id, role_name into caller_id, caller_role from role_account_for_session(session_token) limit 1;
  if caller_id is null or caller_role <> 'ADMIN' then raise exception 'You do not have permission to change account status.'; end if;
  select role_name into target_role from (
    select id, 'ADMIN'::text role_name from admins union all select id, 'STAFF'::text from staff union all select id, 'TECHNICIAN'::text from technicians
  ) accounts where id=target_id;
  if target_role is null then raise exception 'Account not found.'; end if;
  if target_role = 'ADMIN' then
    select count(*) into active_admins from admins where status='ACTIVE';
    if new_status <> 'ACTIVE' and active_admins <= 1 then raise exception 'At least one active admin account is required.'; end if;
    if caller_id <> target_id then raise exception 'Admins cannot change the status of other Admins.'; end if;
    update admins set status=new_status where id=target_id returning to_jsonb(admins.*) into updated;
  elsif target_role = 'STAFF' then update staff set status=new_status where id=target_id returning to_jsonb(staff.*) into updated;
  else update technicians set status=new_status where id=target_id returning to_jsonb(technicians.*) into updated;
  end if;
  if new_status <> 'ACTIVE' then delete from sessions where user_id=target_id; end if;
  return updated || jsonb_build_object('role', target_role);
end;
$$;


--
-- Name: service_materials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.service_materials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    service_id uuid NOT NULL,
    item_id uuid NOT NULL,
    default_amount numeric NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    billing_mode text DEFAULT 'INCLUDED'::text NOT NULL,
    CONSTRAINT service_materials_billing_mode_check CHECK ((billing_mode = ANY (ARRAY['INCLUDED'::text, 'EXTRA_CHARGED'::text, 'CHARGE_ALL'::text]))),
    CONSTRAINT service_materials_default_amount_check CHECK (((default_amount > (0)::numeric) AND (default_amount <= (100000)::numeric)))
);


--
-- Name: TABLE service_materials; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.service_materials IS 'Default materials for a service, in each item''s own unit. Prefills the appointment Stock-Out tab; never deducted without the technician submitting it.';


--
-- Name: COLUMN service_materials.billing_mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.service_materials.billing_mode IS 'INCLUDED: covered by the service price. EXTRA_CHARGED: use beyond default_amount (the included quantity) is billed at the item''s customer price.';


--
-- Name: set_service_materials(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_service_materials(p_service_id uuid, p_materials jsonb) RETURNS SETOF public.service_materials
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.is_office_account() then
    raise exception 'Only the office can change service materials.';
  end if;
  if not exists (select 1 from public.services where id = p_service_id) then
    raise exception 'Service not found.';
  end if;
  if p_materials is null or jsonb_typeof(p_materials) <> 'array' then
    raise exception 'Materials must be a list.';
  end if;
  -- 080: a non-chemical service uses no chemicals.
  if exists (select 1 from public.services s where s.id = p_service_id and s.category = 'NON_CHEMICAL')
     and exists (
       select 1 from jsonb_to_recordset(p_materials) as entries(item_id uuid)
       join public.inventory i on i.id = entries.item_id where i.type = 'CHEMICAL'
     ) then
    raise exception 'A non-chemical service can''t use chemicals. Remove them, or make the service Chemical.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_materials) as entries(item_id uuid)
    group by entries.item_id having count(*) > 1
  ) then
    raise exception 'Each inventory item can only be listed once per service.';
  end if;

  delete from public.service_materials where service_id = p_service_id;

  insert into public.service_materials (service_id, item_id, default_amount, billing_mode)
  select p_service_id, entries.item_id, entries.default_amount,
         case upper(coalesce(entries.billing_mode, ''))
           when 'EXTRA_CHARGED' then 'EXTRA_CHARGED'
           when 'CHARGE_ALL' then 'CHARGE_ALL'
           else 'INCLUDED'
         end
  from jsonb_to_recordset(p_materials) as entries(item_id uuid, default_amount numeric, billing_mode text);

  return query select * from public.service_materials where service_id = p_service_id;
end;
$$;


