--
-- Name: inventory_batch_reference_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.inventory_batch_reference_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: inventory_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reference text DEFAULT ('TPC-B-'::text || lpad((nextval('public.inventory_batch_reference_seq'::regclass))::text, 5, '0'::text)) NOT NULL,
    item_id uuid NOT NULL,
    lot_number text,
    expiration_date date,
    received_date date DEFAULT CURRENT_DATE NOT NULL,
    quantity_received numeric NOT NULL,
    quantity numeric NOT NULL,
    unit_cost numeric,
    stock_in_movement_id uuid,
    is_opening boolean DEFAULT false NOT NULL,
    split_from uuid,
    written_off_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inventory_batches_quantity_check CHECK ((quantity >= (0)::numeric)),
    CONSTRAINT inventory_batches_quantity_received_check CHECK ((quantity_received >= (0)::numeric))
);


--
-- Name: TABLE inventory_batches; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inventory_batches IS 'One row per chemical delivery line. quantity is what is still on the shelf; the item''s quantity is their sum.';


--
-- Name: COLUMN inventory_batches.lot_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_batches.lot_number IS 'The manufacturer''s lot number printed on the container. Null when none is printed.';


--
-- Name: COLUMN inventory_batches.is_opening; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_batches.is_opening IS 'Stock that existed before migration 055, or stock of unknown lot: no delivery behind it.';


--
-- Name: split_inventory_batch(uuid, numeric, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_inventory_batch(p_batch_id uuid, p_amount numeric, p_lot_number text, p_expiration_date date) RETURNS public.inventory_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare source public.inventory_batches; created public.inventory_batches;
begin
  perform public.assert_inventory_admin();
  select * into source from public.inventory_batches b where b.id = p_batch_id for update;
  if source.id is null then raise exception 'That batch was not found.'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Enter a quantity greater than zero.'; end if;
  if p_amount >= source.quantity then
    raise exception 'Split off less than the whole batch (% left). To change the whole batch, edit it instead.', source.quantity;
  end if;
  if p_expiration_date is not null and p_expiration_date < source.received_date then
    raise exception 'The expiry cannot be before the batch was received.';
  end if;

  update public.inventory_batches b set quantity = b.quantity - p_amount where b.id = source.id;
  insert into public.inventory_batches (
    item_id, lot_number, expiration_date, received_date, quantity_received, quantity, unit_cost, is_opening, split_from
  )
  values (
    source.item_id, nullif(trim(coalesce(p_lot_number, '')), ''), p_expiration_date, source.received_date,
    p_amount, p_amount, source.unit_cost, false, source.id
  )
  returning * into created;
  return created;
end;
$$;


--
-- Name: start_visit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_visit(p_appointment_id uuid) RETURNS public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare existing_row public.appointments;
declare started public.appointments;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;

  select * into existing_row from public.appointments where id = p_appointment_id;
  if existing_row.id is null then raise exception 'Appointment not found.'; end if;

  if public.current_account_role() = 'TECHNICIAN' and not public.is_assigned_to_appointment(p_appointment_id) then
    raise exception 'You can only start a visit you are assigned to.';
  end if;

  -- A double tap, or a second crew member arriving: already started.
  if existing_row.status = 'In progress' then
    return existing_row;
  end if;

  if existing_row.status not in ('Pending', 'Scheduled', 'Confirmed', 'Reschedule') then
    raise exception 'A % visit cannot be started.', lower(existing_row.status);
  end if;

  if (existing_row.scheduled_at at time zone 'Asia/Manila')::date <> (now() at time zone 'Asia/Manila')::date then
    raise exception 'A visit can only be started on its scheduled day.';
  end if;

  update public.appointments
  set status = 'In progress',
      started_at = coalesce(started_at, now())
  where id = p_appointment_id
  returning * into started;
  return started;
end;
$$;


--
-- Name: stock_correction(uuid, numeric, text, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_correction(p_item_id uuid, p_delta numeric, p_reason text, p_movement_date date, p_batch_id uuid DEFAULT NULL::uuid) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, reference text, actor text, new_quantity numeric, batch_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  item_status inventory_status;
  item_kind text;
  current_quantity numeric;
  actor_name text;
  actor_account_id uuid;
  movement_id_value uuid;
  new_quantity_value numeric;
  moved_on date;
  target_batch uuid;
  target_label text;
  portion_batches uuid[];
  portion_amounts numeric[];
  portion_labels text[];
  idx integer;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if p_delta is null or p_delta = 0 then raise exception 'Correction amount cannot be zero.'; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'A correction reason is required.'; end if;

  select i.status, i.type::text, i.quantity into item_status, item_kind, current_quantity
  from public.inventory i where i.id = p_item_id for update;
  if item_status is null then raise exception 'Inventory item not found.'; end if;
  if item_status = 'DISABLED' then raise exception 'Cannot correct a disabled item.'; end if;
  if current_quantity + p_delta < 0 then raise exception 'Correction cannot make stock negative.'; end if;

  select r.id, coalesce(a.name, s.name, t.name) into actor_account_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id left join public.staff s on s.id = r.id left join public.technicians t on t.id = r.id limit 1;

  moved_on := coalesce(p_movement_date, current_date);

  if item_kind = 'CHEMICAL' and p_delta > 0 then
    if p_batch_id is not null
       and not exists (select 1 from public.inventory_batches b where b.id = p_batch_id and b.item_id = p_item_id) then
      raise exception 'That batch is not one of this item''s batches.';
    end if;
    target_batch := coalesce(p_batch_id, public.fallback_batch(p_item_id, moved_on));
    update public.inventory_batches b set quantity = b.quantity + p_delta, written_off_at = null
      where b.id = target_batch
      returning coalesce(b.lot_number, b.reference) into target_label;
  end if;

  -- A chemical counted down leaves by batch; anything else is one row.
  if item_kind = 'CHEMICAL' and p_delta < 0 then
    select array_agg(taken.batch_id order by taken.ordinality),
           array_agg(taken.taken order by taken.ordinality),
           array_agg(taken.lot_label order by taken.ordinality)
      into portion_batches, portion_amounts, portion_labels
    from public.take_from_batches(p_item_id, -p_delta, moved_on, p_batch_id, true, false) with ordinality as taken(batch_id, taken, lot_label, ordinality);
  else
    portion_batches := array[target_batch];
    portion_amounts := array[abs(p_delta)];
    portion_labels := array[target_label];
  end if;

  for idx in 1..coalesce(array_length(portion_amounts, 1), 0) loop
    insert into public.inventory_movements (item_id, amount, quantity_delta, movement_date, reference, actor, actor_id, movement_type, batch_id, batch_number)
    values (p_item_id, portion_amounts[idx], sign(p_delta) * portion_amounts[idx], moved_on, trim(p_reason), actor_name, actor_account_id, 'CORRECTION', portion_batches[idx], portion_labels[idx])
    returning id into movement_id_value;

    update public.inventory i set quantity = i.quantity + sign(p_delta) * portion_amounts[idx]
    where i.id = p_item_id
    returning i.quantity into new_quantity_value;

    return query select movement_id_value, p_item_id, portion_amounts[idx], moved_on, trim(p_reason), actor_name, new_quantity_value, portion_batches[idx];
  end loop;
end;
$$;


--
-- Name: stock_in(uuid, numeric, date, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_in(p_item_id uuid, p_amount numeric, p_movement_date date, p_reference text, p_actor text, p_idempotency_key uuid, p_actor_id uuid, p_intake_branch_or_station text) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, reference text, actor text, created_at timestamp with time zone, new_quantity numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare existing inventory_movements; item_status inventory_status; movement_id_value uuid; created_at_value timestamptz; new_quantity_value numeric;
begin
  if p_amount is null or p_amount <= 0 then raise exception 'Stock In amount must be greater than 0'; end if;
  if nullif(trim(p_reference), '') is null then raise exception 'A purchase order or supplier invoice reference is required'; end if;
  if p_idempotency_key is not null then
    select * into existing from public.inventory_movements where idempotency_key = p_idempotency_key;
    if existing.id is not null then select quantity into new_quantity_value from public.inventory where id = existing.item_id; return query select existing.id, existing.item_id, existing.amount, existing.movement_date, existing.reference, existing.actor, existing.created_at, new_quantity_value; return; end if;
  end if;
  select status into item_status from public.inventory where id = p_item_id for update;
  if item_status is null then raise exception 'Inventory item not found'; end if;
  if item_status = 'DISABLED' then raise exception 'Cannot Stock In on a disabled item'; end if;
  insert into public.inventory_movements (item_id, amount, quantity_delta, movement_date, reference, actor, actor_id, intake_branch_or_station, purchase_reference, idempotency_key, movement_type)
  values (p_item_id, p_amount, p_amount, p_movement_date, nullif(trim(p_reference), ''), p_actor, p_actor_id, nullif(trim(p_intake_branch_or_station), ''), nullif(trim(p_reference), ''), p_idempotency_key, 'IN')
  returning id, inventory_movements.created_at into movement_id_value, created_at_value;
  update public.inventory set quantity = quantity + p_amount where id = p_item_id returning quantity into new_quantity_value;
  return query select movement_id_value, p_item_id, p_amount, p_movement_date, nullif(trim(p_reference), ''), p_actor, created_at_value, new_quantity_value;
end;
$$;


--
-- Name: stock_in_batch(jsonb, date, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_in_batch(p_items jsonb, p_movement_date date, p_reference text, p_intake_branch_or_station text, p_idempotency_key uuid) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, reference text, actor text, unit_cost numeric, total_cost numeric, created_at timestamp with time zone, new_quantity numeric, expiration_date date, batch_id uuid, batch_reference text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  entry record;
  item_status inventory_status;
  item_kind text;
  item_label text;
  actor_name text;
  actor_account_id uuid;
  movement_id_value uuid;
  created_at_value timestamptz;
  new_quantity_value numeric;
  new_expiry_value date;
  resolved_cost numeric;
  resolved_amount numeric;
  resolved_lot text;
  received_on date;
  batch_id_value uuid;
  batch_reference_value text;
  entry_key uuid;
  row_index integer := 0;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'At least one item is required.';
  end if;
  if nullif(trim(p_reference), '') is null then
    raise exception 'A purchase order or supplier invoice reference is required.';
  end if;
  if nullif(trim(p_intake_branch_or_station), '') is null then
    raise exception 'An intake branch or station is required.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_items) as entries(item_id uuid, lot_number text)
    group by entries.item_id, lower(trim(coalesce(entries.lot_number, '')))
    having count(*) > 1
  ) then
    raise exception 'The same item and lot appear twice on this Stock In. Combine the duplicate lines.';
  end if;

  if p_idempotency_key is not null
     and exists (select 1 from public.inventory_movements m where m.batch_key = p_idempotency_key) then
    return query
      select m.id, m.item_id, m.amount, m.movement_date, m.reference, m.actor,
             coalesce(m.unit_cost, 0), coalesce(m.total_cost, 0), m.created_at, i.quantity,
             i.expiration_date::date, m.batch_id, b.reference
      from public.inventory_movements m
      join public.inventory i on i.id = m.item_id
      left join public.inventory_batches b on b.id = m.batch_id
      where m.batch_key = p_idempotency_key
      order by m.created_at;
    return;
  end if;

  received_on := coalesce(p_movement_date, current_date);

  select r.id, coalesce(a.name, s.name, t.name) into actor_account_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id
  left join public.staff s on s.id = r.id
  left join public.technicians t on t.id = r.id
  limit 1;

  for entry in
    select entries.item_id, entries.amount, entries.unit_cost,
           entries.entered_amount, entries.entered_unit, entries.conversion_factor,
           entries.expiration_date, entries.lot_number, entries.no_lot
    from jsonb_to_recordset(p_items) as entries(
      item_id uuid, amount numeric, unit_cost numeric,
      entered_amount numeric, entered_unit text, conversion_factor numeric,
      expiration_date date, lot_number text, no_lot boolean
    )
  loop
    resolved_amount := round(entry.amount, 4);
    if resolved_amount is null or resolved_amount <= 0 then
      raise exception 'Stock In amounts must be greater than 0.';
    end if;

    select i.status, i.type::text, i.name into item_status, item_kind, item_label
    from public.inventory i where i.id = entry.item_id for update;
    if item_status is null then raise exception 'Inventory item not found.'; end if;
    if item_status = 'DISABLED' then raise exception 'Cannot Stock In on a disabled item.'; end if;

    resolved_cost := coalesce(entry.unit_cost, 0);
    if resolved_cost < 0 then raise exception 'Purchase cost cannot be negative.'; end if;

    if entry.expiration_date is not null and entry.expiration_date < received_on then
      raise exception 'This delivery is already expired: the expiry date is before the delivery date.';
    end if;

    resolved_lot := nullif(trim(coalesce(entry.lot_number, '')), '');
    if item_kind = 'CHEMICAL' then
      -- Stock already on the shelf with no batch gets its opening batch first,
      -- so this delivery's batch is not mistaken for all of it.
      perform public.ensure_item_batches(entry.item_id);
      if entry.expiration_date is null then
        raise exception 'Enter the expiry date printed on the % delivery.', item_label;
      end if;
      if resolved_lot is null and not coalesce(entry.no_lot, false) then
        raise exception 'Enter the lot number printed on the % container, or tick "No lot number printed".', item_label;
      end if;
    else
      resolved_lot := null;
    end if;

    entry_key := case when row_index = 0 then p_idempotency_key else null end;
    row_index := row_index + 1;

    insert into public.inventory_movements (
      item_id, amount, quantity_delta, movement_date, reference, actor, actor_id,
      intake_branch_or_station, purchase_reference, idempotency_key, batch_key, movement_type,
      unit_cost, total_cost, entered_amount, entered_unit, conversion_factor,
      expiration_date
    )
    values (
      entry.item_id, resolved_amount, resolved_amount, received_on,
      nullif(trim(p_reference), ''), actor_name, actor_account_id,
      nullif(trim(p_intake_branch_or_station), ''), nullif(trim(p_reference), ''),
      entry_key, p_idempotency_key, 'IN',
      resolved_cost, round(resolved_cost * resolved_amount, 2),
      entry.entered_amount, nullif(trim(coalesce(entry.entered_unit, '')), ''),
      coalesce(entry.conversion_factor, 1),
      entry.expiration_date
    )
    returning id, inventory_movements.created_at into movement_id_value, created_at_value;

    batch_id_value := null;
    batch_reference_value := null;
    if item_kind = 'CHEMICAL' then
      insert into public.inventory_batches (
        item_id, lot_number, expiration_date, received_date, quantity_received, quantity, unit_cost, stock_in_movement_id
      )
      values (
        entry.item_id, resolved_lot, entry.expiration_date, received_on, resolved_amount, resolved_amount,
        resolved_cost, movement_id_value
      )
      returning id, inventory_batches.reference into batch_id_value, batch_reference_value;

      update public.inventory_movements m
        set batch_id = batch_id_value, batch_number = coalesce(resolved_lot, batch_reference_value)
        where m.id = movement_id_value;
    end if;

    -- The expiry is no longer written here: the batch trigger keeps the item
    -- at its soonest live expiry.
    update public.inventory i
    set quantity = i.quantity + resolved_amount,
        cost = case when entry.unit_cost is null then i.cost else resolved_cost end
    where i.id = entry.item_id
    returning i.quantity, i.expiration_date::date into new_quantity_value, new_expiry_value;

    return query select
      movement_id_value, entry.item_id, resolved_amount, received_on, nullif(trim(p_reference), ''), actor_name,
      resolved_cost, round(resolved_cost * resolved_amount, 2),
      created_at_value, new_quantity_value, new_expiry_value, batch_id_value, batch_reference_value;
  end loop;
end;
$$;


--
-- Name: stock_out(uuid, uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_out(p_item_id uuid, p_appointment_id uuid, p_amount numeric, p_movement_date date) RETURNS TABLE(movement_id uuid, item_id uuid, appointment_id uuid, amount numeric, movement_date date, actor text, new_quantity numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare item_status inventory_status; current_quantity numeric; actor_name text; actor_id uuid; movement_id_value uuid; new_quantity_value numeric;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Stock Out amount must be greater than 0.'; end if;
  if not exists (select 1 from public.appointments where id = p_appointment_id and status <> 'Cancelled') then raise exception 'Active appointment not found.'; end if;
  select status, quantity into item_status, current_quantity from public.inventory where id = p_item_id for update;
  if item_status is null then raise exception 'Inventory item not found.'; end if;
  if item_status = 'DISABLED' then raise exception 'Cannot Stock Out a disabled item.'; end if;
  if p_amount > current_quantity then raise exception 'Requested quantity exceeds available stock.'; end if;
  select r.id, coalesce(a.name, s.name, t.name) into actor_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id
  left join public.staff s on s.id = r.id
  left join public.technicians t on t.id = r.id limit 1;

  insert into public.inventory_movements (item_id, amount, quantity_delta, movement_date, reference, actor, actor_id, movement_type, appointment_id)
  values (p_item_id, p_amount, -p_amount, coalesce(p_movement_date, current_date), 'Appointment ' || p_appointment_id::text, actor_name, actor_id, 'OUT', p_appointment_id)
  returning id into movement_id_value;
  update public.inventory set quantity = quantity - p_amount where id = p_item_id returning quantity into new_quantity_value;
  return query select movement_id_value, p_item_id, p_appointment_id, p_amount, coalesce(p_movement_date, current_date), actor_name, new_quantity_value;
end;
$$;


--
-- Name: stock_out_batch(uuid, jsonb, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_out_batch(p_appointment_id uuid, p_items jsonb, p_movement_date date) RETURNS TABLE(movement_id uuid, item_id uuid, appointment_id uuid, amount numeric, movement_date date, actor text, new_quantity numeric, batch_number text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  item_row record;
  held record;
  portion record;
  logged record;
  chosen public.inventory_batches;
  item_status inventory_status;
  item_kind text;
  current_quantity numeric;
  actor_name text;
  actor_account_id uuid;
  still_needed numeric;
  drawn numeric;
  crew uuid[];
  visit_reference text;
  used_on date;
  pass integer;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if not exists (select 1 from public.appointments a where a.id = p_appointment_id and a.status <> 'Cancelled') then raise exception 'Active appointment not found.'; end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then raise exception 'At least one stock-out item is required.'; end if;
  if exists (select entries.item_id from jsonb_to_recordset(p_items) as entries(item_id uuid, amount numeric) group by entries.item_id having count(*) > 1) then raise exception 'Each inventory item can only be added once per stock-out.'; end if;

  used_on := coalesce(p_movement_date, current_date);

  select r.id, coalesce(a.name, s.name, t.name) into actor_account_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id
  left join public.staff s on s.id = r.id
  left join public.technicians t on t.id = r.id
  limit 1;

  select coalesce(array_agg(at.technician_id), '{}') into crew
  from public.appointment_technicians at where at.appointment_id = p_appointment_id;
  select crew || coalesce(array_agg(a.technician_id) filter (where a.technician_id is not null), '{}') into crew
  from public.appointments a where a.id = p_appointment_id;

  select coalesce(a.reference, 'Appointment ' || a.id::text) into visit_reference
  from public.appointments a where a.id = p_appointment_id;

  for item_row in
    select entries.item_id, entries.amount, entries.batch_id
    from jsonb_to_recordset(p_items) as entries(item_id uuid, amount numeric, batch_id uuid)
    order by entries.item_id
  loop
    if item_row.amount is null or item_row.amount <= 0 then raise exception 'Stock-Out quantities must be greater than zero.'; end if;

    select i.status, i.type::text, i.quantity into item_status, item_kind, current_quantity
    from public.inventory i where i.id = item_row.item_id for update;
    if item_status is null then raise exception 'Inventory item not found.'; end if;
    if item_status = 'DISABLED' then raise exception 'Cannot Stock Out a disabled item.'; end if;

    chosen := null;
    if item_row.batch_id is not null and item_kind = 'CHEMICAL' then
      select * into chosen from public.inventory_batches b where b.id = item_row.batch_id and b.item_id = item_row.item_id;
      if chosen.id is null then raise exception 'That batch is not one of this item''s batches.'; end if;
      if chosen.expiration_date is not null and chosen.expiration_date < used_on then
        raise exception 'Batch % expired on %. Choose another batch.',
          coalesce(chosen.lot_number, chosen.reference), to_char(chosen.expiration_date, 'Mon DD, YYYY');
      end if;
    end if;

    still_needed := item_row.amount;

    for pass in 1..2 loop
      continue when pass = 1 and chosen.id is null;

      -- What the crew checked out: pass 1 the chosen batch only, pass 2 the rest.
      for held in
        select c.id, c.batch_id as held_batch, public.checkout_remaining(c.id) as remaining,
               coalesce(b.lot_number, b.reference, c.batch_number) as label
        from public.inventory_movements c
        left join public.inventory_batches b on b.id = c.batch_id
        where c.stock_out_reason = 'TECHNICIAN_CHECKOUT'
          and c.item_id = item_row.item_id
          and c.custody_closed_at is null
          and c.technician_id = any(crew)
          and c.movement_date <= used_on
          and (b.id is null or b.expiration_date is null or b.expiration_date >= used_on)
          and ((pass = 1 and c.batch_id = chosen.id)
               or (pass = 2 and (chosen.id is null or c.batch_id is distinct from chosen.id)))
        order by (c.for_appointment_id is not distinct from p_appointment_id) desc,
                 b.expiration_date asc nulls last, c.movement_date, c.created_at
      loop
        exit when still_needed <= 0;
        continue when held.remaining <= 0;
        drawn := least(held.remaining, still_needed);
        select * into logged from public.log_visit_usage(
          p_appointment_id, item_row.item_id, drawn, used_on, visit_reference, actor_name, actor_account_id,
          held.held_batch, held.label, held.id);
        still_needed := still_needed - drawn;
        return query select logged.movement_id, item_row.item_id, p_appointment_id, drawn, used_on, actor_name, logged.new_quantity, held.label;
      end loop;

      -- Between the passes: the chosen batch on the shelf.
      if pass = 1 and still_needed > 0 then
        for portion in
          select * from public.take_from_batches(item_row.item_id, still_needed, used_on, chosen.id, false, true)
        loop
          select * into logged from public.log_visit_usage(
            p_appointment_id, item_row.item_id, portion.taken, used_on, visit_reference, actor_name, actor_account_id,
            portion.batch_id, portion.lot_label, null);
          still_needed := still_needed - portion.taken;
          return query select logged.movement_id, item_row.item_id, p_appointment_id, portion.taken, used_on, actor_name, logged.new_quantity, portion.lot_label;
        end loop;
      end if;
    end loop;

    -- The shelf, soonest expiry first.
    if still_needed > 0 then
      if item_kind = 'CHEMICAL' then
        for portion in
          select * from public.take_from_batches(item_row.item_id, still_needed, used_on, null, false, false)
        loop
          select * into logged from public.log_visit_usage(
            p_appointment_id, item_row.item_id, portion.taken, used_on, visit_reference, actor_name, actor_account_id,
            portion.batch_id, portion.lot_label, null);
          return query select logged.movement_id, item_row.item_id, p_appointment_id, portion.taken, used_on, actor_name, logged.new_quantity, portion.lot_label;
        end loop;
      else
        if still_needed > current_quantity then
          raise exception 'Requested quantity exceeds available stock.';
        end if;
        select * into logged from public.log_visit_usage(
          p_appointment_id, item_row.item_id, still_needed, used_on, visit_reference, actor_name, actor_account_id,
          null, null, null);
        return query select logged.movement_id, item_row.item_id, p_appointment_id, still_needed, used_on, actor_name, logged.new_quantity, null::text;
      end if;
    end if;
  end loop;
end;
$$;


--
-- Name: stock_out_lines(jsonb, date, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_out_lines(p_lines jsonb, p_movement_date date, p_reason text, p_technician_id uuid, p_note text, p_for_appointment_id uuid DEFAULT NULL::uuid) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, reason text, technician_id uuid, actor text, note text, new_quantity numeric, for_appointment_id uuid, batch_id uuid, batch_number text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  line jsonb;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Add at least one item to stock out.';
  end if;
  if jsonb_array_length(p_lines) > 50 then
    raise exception 'Stock out at most 50 lines at a time.';
  end if;

  for line in select value from jsonb_array_elements(p_lines) loop
    return query
      select * from public.stock_out_manual(
        (line->>'item_id')::uuid,
        (line->>'amount')::numeric,
        p_movement_date,
        p_reason,
        p_technician_id,
        p_note,
        case when p_reason = 'TECHNICIAN_CHECKOUT' then p_for_appointment_id else null end,
        nullif(line->>'batch_id', '')::uuid
      );
  end loop;
end;
$$;


--
-- Name: stock_out_lines_signed(jsonb, date, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_out_lines_signed(p_lines jsonb, p_movement_date date, p_technician_id uuid, p_note text, p_for_appointment_id uuid, p_handover_path text, p_receiver_path text) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, reason text, technician_id uuid, actor text, note text, new_quantity numeric, for_appointment_id uuid, batch_id uuid, batch_number text, handover_group uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_group uuid := gen_random_uuid();
  v_actor text;
  v_row record;
  v_ids uuid[] := '{}';
begin
  if not public.is_office_account() then raise exception 'Only the office checks stock out to a technician.'; end if;
  if p_technician_id is null then raise exception 'Select the technician the stock is going to.'; end if;
  if nullif(trim(coalesce(p_handover_path, '')), '') is null then raise exception 'The person handing the stock over must sign.'; end if;
  if nullif(trim(coalesce(p_receiver_path, '')), '') is null then raise exception 'The technician taking the stock must sign.'; end if;

  select coalesce(a.name, s.name) into v_actor
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id
  left join public.staff s on s.id = r.id
  limit 1;

  for v_row in
    select * from public.stock_out_lines(p_lines, p_movement_date, 'TECHNICIAN_CHECKOUT', p_technician_id, p_note, p_for_appointment_id)
  loop
    v_ids := v_ids || v_row.movement_id;
    movement_id := v_row.movement_id;
    item_id := v_row.item_id;
    amount := v_row.amount;
    movement_date := v_row.movement_date;
    reason := v_row.reason;
    technician_id := v_row.technician_id;
    actor := v_row.actor;
    note := v_row.note;
    new_quantity := v_row.new_quantity;
    for_appointment_id := v_row.for_appointment_id;
    batch_id := v_row.batch_id;
    batch_number := v_row.batch_number;
    handover_group := v_group;
    return next;
  end loop;

  -- A statement of its own, so it sees the movements just booked.
  update public.inventory_movements m
    set handover_signature_path = trim(p_handover_path),
        receiver_signature_path = trim(p_receiver_path),
        handover_group = v_group,
        handed_over_by_name = v_actor
    where m.id = any(v_ids);
end;
$$;


--
-- Name: stock_out_manual(uuid, numeric, date, text, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stock_out_manual(p_item_id uuid, p_amount numeric, p_movement_date date, p_reason text, p_technician_id uuid, p_note text, p_for_appointment_id uuid DEFAULT NULL::uuid, p_batch_id uuid DEFAULT NULL::uuid) RETURNS TABLE(movement_id uuid, item_id uuid, amount numeric, movement_date date, reason text, technician_id uuid, actor text, note text, new_quantity numeric, for_appointment_id uuid, batch_id uuid, batch_number text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  item_status inventory_status;
  item_kind text;
  current_quantity numeric;
  actor_name text;
  actor_account_id uuid;
  movement_id_value uuid;
  new_quantity_value numeric;
  reason_label text;
  resolved_technician uuid;
  resolved_visit uuid;
  visit_status text;
  moved_on date;
  resolved_note text;
  portion_batches uuid[];
  portion_amounts numeric[];
  portion_labels text[];
  idx integer;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if p_reason not in ('TECHNICIAN_CHECKOUT', 'MISSING', 'DAMAGED') then
    raise exception 'Choose a stock-out reason.';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'Stock-Out quantities must be greater than zero.';
  end if;

  resolved_technician := case when p_reason = 'TECHNICIAN_CHECKOUT' then p_technician_id end;
  resolved_visit := case when p_reason = 'TECHNICIAN_CHECKOUT' then p_for_appointment_id end;
  if p_reason = 'TECHNICIAN_CHECKOUT' then
    if resolved_technician is null then
      raise exception 'Select the technician the stock was checked out to.';
    end if;
    if not exists (select 1 from public.technicians t where t.id = resolved_technician) then
      raise exception 'That technician was not found.';
    end if;
    if not public.account_is_active(resolved_technician) then
      raise exception 'That technician account is not active.';
    end if;
    if resolved_visit is not null then
      select a.status into visit_status from public.appointments a where a.id = resolved_visit;
      if visit_status is null then raise exception 'That visit was not found.'; end if;
      if visit_status in ('Completed', 'Cancelled') then
        raise exception 'That visit is already %; choose an upcoming one.', lower(visit_status);
      end if;
      if not exists (
        select 1 from public.appointment_technicians at
        where at.appointment_id = resolved_visit and at.technician_id = resolved_technician
      ) and not exists (
        select 1 from public.appointments a where a.id = resolved_visit and a.technician_id = resolved_technician
      ) then
        raise exception 'That technician is not on the visit''s crew.';
      end if;
    end if;
  end if;

  select i.status, i.type::text, i.quantity into item_status, item_kind, current_quantity
  from public.inventory i where i.id = p_item_id for update;
  if item_status is null then raise exception 'Inventory item not found.'; end if;
  if item_status = 'DISABLED' then raise exception 'Cannot Stock Out a disabled item.'; end if;
  if p_amount > current_quantity then raise exception 'Requested quantity exceeds available stock.'; end if;

  select r.id, coalesce(a.name, s.name, t.name) into actor_account_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id
  left join public.staff s on s.id = r.id
  left join public.technicians t on t.id = r.id
  limit 1;

  reason_label := case p_reason
    when 'TECHNICIAN_CHECKOUT' then 'Checked out by ' ||
      coalesce((select t.name from public.technicians t where t.id = resolved_technician), 'a technician')
    when 'MISSING' then 'Missing stock'
    else 'Damaged stock'
  end;
  moved_on := coalesce(p_movement_date, current_date);
  resolved_note := nullif(trim(coalesce(p_note, '')), '');

  -- The portions this stock-out is made of: one per batch for a chemical,
  -- the whole amount for anything else.
  if item_kind = 'CHEMICAL' then
    select array_agg(taken.batch_id order by taken.ordinality),
           array_agg(taken.taken order by taken.ordinality),
           array_agg(taken.lot_label order by taken.ordinality)
      into portion_batches, portion_amounts, portion_labels
    from public.take_from_batches(p_item_id, p_amount, moved_on, p_batch_id, false, false) with ordinality as taken(batch_id, taken, lot_label, ordinality);
  else
    portion_batches := array[null::uuid];
    portion_amounts := array[p_amount];
    portion_labels := array[null::text];
  end if;

  for idx in 1..coalesce(array_length(portion_amounts, 1), 0) loop
    insert into public.inventory_movements (
      item_id, amount, quantity_delta, movement_date, reference, actor, actor_id,
      movement_type, stock_out_reason, technician_id, note, for_appointment_id, batch_id, batch_number
    )
    values (
      p_item_id, portion_amounts[idx], -portion_amounts[idx], moved_on,
      reason_label, actor_name, actor_account_id,
      'OUT', p_reason, resolved_technician, resolved_note, resolved_visit, portion_batches[idx], portion_labels[idx]
    )
    returning id into movement_id_value;

    update public.inventory i set quantity = i.quantity - portion_amounts[idx]
    where i.id = p_item_id
    returning i.quantity into new_quantity_value;

    return query select
      movement_id_value, p_item_id, portion_amounts[idx], moved_on,
      p_reason, resolved_technician, actor_name, resolved_note, new_quantity_value, resolved_visit,
      portion_batches[idx], portion_labels[idx];
  end loop;
end;
$$;


--
-- Name: appointment_reports; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.appointment_reports (
    appointment_id uuid NOT NULL,
    findings text NOT NULL,
    submitted_by uuid,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    treatment_performed text,
    recommendations text,
    follow_up_date date,
    customer_name text,
    signature_path text,
    signed_at timestamp with time zone,
    completion_note text,
    treatment_methods text[] DEFAULT '{}'::text[] NOT NULL,
    technician_signature_path text,
    technician_signed_at timestamp with time zone
);


--
-- Name: COLUMN appointment_reports.customer_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointment_reports.customer_name IS 'Printed name of the person who signed. A signature image alone identifies nobody.';


--
-- Name: COLUMN appointment_reports.completion_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointment_reports.completion_note IS 'Why this service was completed without a customer signature. Office use.';


--
-- Name: COLUMN appointment_reports.treatment_methods; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointment_reports.treatment_methods IS 'Ticked treatment methods. Values mirror TREATMENT_METHODS in src/utils/constants.js.';


--
-- Name: COLUMN appointment_reports.technician_signature_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointment_reports.technician_signature_path IS 'Object key of the technician''s signature in the report-attachments bucket. Attestation of their own report, not a confirmation of the service.';


--
-- Name: COLUMN appointment_reports.technician_signed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.appointment_reports.technician_signed_at IS 'When the technician signed. Set from now() on the submit that carried the signature.';


--
-- Name: submit_appointment_report(uuid, text, text, text, date, text, text, text, text[], text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_appointment_report(p_appointment_id uuid, p_findings text, p_treatment_performed text, p_recommendations text, p_follow_up_date date, p_customer_name text DEFAULT NULL::text, p_signature_path text DEFAULT NULL::text, p_completion_note text DEFAULT NULL::text, p_treatment_methods text[] DEFAULT NULL::text[], p_technician_signature_path text DEFAULT NULL::text, p_service_ids uuid[] DEFAULT NULL::uuid[]) RETURNS public.appointment_reports
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare report_row public.appointment_reports;
declare actor_id uuid;
declare previous_status text;
declare current_service text;
declare job_plan uuid;
declare job_kind text;
declare signed boolean;
declare tech_signed boolean;
declare confirmed boolean;
declare methods text[];
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if nullif(trim(p_findings), '') is null then raise exception 'Inspection findings are required.'; end if;

  methods := coalesce(p_treatment_methods, '{}');

  select a.status, a.service_type, a.plan_id, p.kind
    into previous_status, current_service, job_plan, job_kind
  from public.appointments a
  left join public.appointment_plans p on p.id = a.plan_id
  where a.id = p_appointment_id;
  if previous_status is null then raise exception 'Appointment not found.'; end if;

  -- 052: a multi-day job has one report, on its last day.
  if job_kind = 'MULTI_DAY' and public.plan_last_day(job_plan) is distinct from p_appointment_id then
    raise exception 'This job''s report is filed on its last day.';
  end if;

  -- 051: the services performed, ticked on the report. Replaces the list.
  if p_service_ids is not null and cardinality(p_service_ids) > 0 then
    current_service := public.set_appointment_services(p_appointment_id, p_service_ids);
  end if;

  if nullif(trim(coalesce(current_service, '')), '') is null
     and cardinality(methods) = 0
     and nullif(trim(coalesce(p_treatment_performed, '')), '') is null then
    raise exception 'Record the treatment: tick the services performed.';
  end if;

  signed := nullif(trim(coalesce(p_signature_path, '')), '') is not null;
  tech_signed := nullif(trim(coalesce(p_technician_signature_path, '')), '') is not null;

  if signed and nullif(trim(coalesce(p_customer_name, '')), '') is null then
    raise exception 'A customer name is required alongside the signature.';
  end if;

  -- Unchanged from migration 034: only the customer's signature or an office
  -- note completes a visit. tech_signed is deliberately absent here.
  confirmed := signed or nullif(trim(coalesce(p_completion_note, '')), '') is not null;

  actor_id := public.current_account_id();

  insert into public.appointment_reports (
    appointment_id, findings, treatment_performed, treatment_methods, recommendations,
    follow_up_date, submitted_by, customer_name, signature_path, signed_at, completion_note,
    technician_signature_path, technician_signed_at
  )
  values (
    p_appointment_id, trim(p_findings), nullif(trim(coalesce(p_treatment_performed, '')), ''),
    methods, nullif(trim(p_recommendations), ''), p_follow_up_date,
    actor_id,
    nullif(trim(coalesce(p_customer_name, '')), ''),
    nullif(trim(coalesce(p_signature_path, '')), ''),
    case when signed then now() else null end,
    nullif(trim(coalesce(p_completion_note, '')), ''),
    nullif(trim(coalesce(p_technician_signature_path, '')), ''),
    case when tech_signed then now() else null end
  )
  on conflict (appointment_id) do update set
    findings            = excluded.findings,
    treatment_performed = excluded.treatment_performed,
    treatment_methods   = excluded.treatment_methods,
    recommendations     = excluded.recommendations,
    follow_up_date      = excluded.follow_up_date,
    submitted_by        = excluded.submitted_by,
    submitted_at        = now(),
    customer_name   = coalesce(excluded.customer_name,   appointment_reports.customer_name),
    signature_path  = coalesce(excluded.signature_path,  appointment_reports.signature_path),
    signed_at       = coalesce(excluded.signed_at,       appointment_reports.signed_at),
    completion_note = coalesce(excluded.completion_note, appointment_reports.completion_note),
    technician_signature_path = coalesce(excluded.technician_signature_path, appointment_reports.technician_signature_path),
    technician_signed_at      = coalesce(excluded.technician_signed_at,      appointment_reports.technician_signed_at)
  returning * into report_row;

  if confirmed then
    if job_kind = 'MULTI_DAY' then
      -- 052: the signature completes the whole job, every live day of it.
      update public.appointments
        set status = 'Completed', day_done_at = coalesce(day_done_at, now())
        where plan_id = job_plan and status <> 'Cancelled';
    else
      update public.appointments set status = 'Completed' where id = p_appointment_id;
    end if;
  end if;

  if confirmed and previous_status is distinct from 'Completed' then
    insert into public.notifications (recipient_id, appointment_id, message)
    select recipients.id, p_appointment_id,
           'Service completed for ' || coalesce(c.name, 'a client') || '.'
    from public.appointments appt
    join public.clients c on c.id = appt.client_id
    cross join (
      select id from public.admins where status = 'ACTIVE'
      union all
      select id from public.staff where status = 'ACTIVE'
    ) recipients
    where appt.id = p_appointment_id
      and recipients.id is distinct from actor_id;
  end if;

  return report_row;
end;
$$;


--
-- Name: sync_appointment_lead_technician(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_appointment_lead_technician() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare target_appointment uuid;
begin
  target_appointment := coalesce(new.appointment_id, old.appointment_id);

  update public.appointments a
  set technician_id = (
    select at.technician_id
    from public.appointment_technicians at
    where at.appointment_id = target_appointment
    order by at.is_lead desc, at.assigned_at, at.technician_id
    limit 1
  )
  where a.id = target_appointment
    and a.technician_id is distinct from (
      select at.technician_id
      from public.appointment_technicians at
      where at.appointment_id = target_appointment
      order by at.is_lead desc, at.assigned_at, at.technician_id
      limit 1
    );

  return coalesce(new, old);
end;
$$;


--
-- Name: sync_item_expiry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_item_expiry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.inventory i
    set expiration_date = (
      select min(b.expiration_date) from public.inventory_batches b
      where b.item_id = new.item_id and b.quantity > 0 and b.written_off_at is null
    )
    where i.id = new.item_id;
  return null;
end;
$$;


--
-- Name: sync_multi_day_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_multi_day_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare plan_kind text;
begin
  if pg_trigger_depth() > 1 then return new; end if;
  if new.plan_id is null or new.status is not distinct from old.status then return new; end if;
  if new.status = 'In progress' then return new; end if;

  select p.kind into plan_kind from public.appointment_plans p where p.id = new.plan_id;
  if plan_kind is distinct from 'MULTI_DAY' then return new; end if;

  if new.status = 'Completed' then
    update public.appointments a
      set status = 'Completed', day_done_at = coalesce(a.day_done_at, now())
      where a.plan_id = new.plan_id and a.id <> new.id
        and a.status not in ('Completed', 'Cancelled');
  elsif new.status = 'Cancelled' then
    update public.appointments a
      set status = 'Cancelled', cancellation_reason = coalesce(new.cancellation_reason, a.cancellation_reason)
      where a.plan_id = new.plan_id and a.id <> new.id
        and a.scheduled_at > new.scheduled_at
        and a.status not in ('Completed', 'Cancelled', 'In progress');
  else
    update public.appointments a
      set status = new.status
      where a.plan_id = new.plan_id and a.id <> new.id
        and a.status is distinct from new.status
        and a.status not in ('Completed', 'In progress')
        and (a.status <> 'Cancelled' or old.status = 'Cancelled');
  end if;
  return new;
end;
$$;


--
-- Name: take_from_batches(uuid, numeric, date, uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_from_batches(p_item_id uuid, p_amount numeric, p_on date, p_batch_id uuid DEFAULT NULL::uuid, p_include_expired boolean DEFAULT false, p_only_chosen boolean DEFAULT false) RETURNS TABLE(batch_id uuid, taken numeric, lot_label text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  still numeric := p_amount;
  chosen public.inventory_batches;
  source record;
  drawn numeric;
  expired_quantity numeric;
  item_name text;
  item_unit text;
begin
  perform public.ensure_item_batches(p_item_id);

  if p_batch_id is not null then
    select * into chosen from public.inventory_batches b where b.id = p_batch_id and b.item_id = p_item_id;
    if chosen.id is null then raise exception 'That batch is not one of this item''s batches.'; end if;
    if not p_include_expired and chosen.expiration_date is not null and chosen.expiration_date < p_on then
      raise exception 'Batch % expired on %. Choose another batch.',
        coalesce(chosen.lot_number, chosen.reference), to_char(chosen.expiration_date, 'Mon DD, YYYY');
    end if;
  end if;

  for source in
    select b.id, b.quantity, coalesce(b.lot_number, b.reference) as label
    from public.inventory_batches b
    where b.item_id = p_item_id
      and b.quantity > 0
      and b.received_date <= p_on
      and (p_include_expired or b.expiration_date is null or b.expiration_date >= p_on)
      and (not p_only_chosen or b.id = p_batch_id)
    order by (b.id = p_batch_id) desc nulls last, b.expiration_date asc nulls last, b.received_date, b.created_at
    for update
  loop
    exit when still <= 0;
    drawn := least(source.quantity, still);
    update public.inventory_batches b set quantity = b.quantity - drawn where b.id = source.id;
    still := still - drawn;
    batch_id := source.id;
    taken := drawn;
    lot_label := source.label;
    return next;
  end loop;

  if still > 0 and not p_only_chosen then
    select coalesce(sum(b.quantity), 0) into expired_quantity
    from public.inventory_batches b
    where b.item_id = p_item_id and b.quantity > 0 and b.expiration_date < p_on;
    select i.name, i.unit into item_name, item_unit from public.inventory i where i.id = p_item_id;
    if expired_quantity > 0 and not p_include_expired then
      raise exception 'Not enough usable %: % % of it has expired. Write the expired batch off, or record less.',
        item_name, expired_quantity, item_unit;
    end if;
    raise exception 'Requested quantity exceeds available stock.';
  end if;
end;
$$;


--
-- Name: treatment_method_in_use(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.treatment_method_in_use(p_value text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.appointment_reports
    where p_value = any(coalesce(treatment_methods, '{}'))
  );
$$;


--
-- Name: update_appointment(uuid, timestamp with time zone, integer, text, text, text, uuid[], text, text, text, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_appointment(p_appointment_id uuid, p_scheduled_at timestamp with time zone, p_duration_minutes integer, p_pest_concern text, p_service_type text, p_service_location text, p_technician_ids uuid[], p_status text, p_notes text, p_cancellation_reason text, p_service_frequency text, p_price numeric, p_service_id uuid DEFAULT NULL::uuid) RETURNS public.appointments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare updated public.appointments;
declare existing_row public.appointments;
begin
  if not public.has_role_table_session() then raise exception 'Not signed in.'; end if;
  if p_duration_minutes is null or p_duration_minutes < 1 or p_duration_minutes > 1440 then
    raise exception 'Duration must be between 1 minute and 24 hours.';
  end if;
  -- 048: 'In progress' added.
  if p_status not in ('Pending', 'Scheduled', 'Confirmed', 'Reschedule', 'In progress', 'Completed', 'Cancelled') then
    raise exception 'Invalid appointment status.';
  end if;
  if p_price is not null and p_price < 0 then raise exception 'Price cannot be negative.'; end if;
  if p_price is not null and p_price > 999999.99 then
    raise exception 'Price cannot be more than 999,999.99.';
  end if;

  select * into existing_row from public.appointments where id = p_appointment_id;
  if existing_row.id is null then raise exception 'Appointment not found.'; end if;

  if (existing_row.scheduled_at is distinct from p_scheduled_at
      or existing_row.duration_minutes is distinct from p_duration_minutes)
     and existing_row.status <> 'Reschedule' then
    raise exception 'Change the status to Reschedule before moving or resizing the appointment.';
  end if;

  if existing_row.scheduled_at is distinct from p_scheduled_at
     and p_scheduled_at < now() - interval '5 minutes' then
    raise exception 'Appointments cannot be moved into the past.';
  end if;
  if p_service_id is not null and not exists (select 1 from public.services where id = p_service_id) then
    p_service_id := null;
  end if;

  perform public.assert_technicians_available(p_appointment_id, p_technician_ids, p_scheduled_at, p_duration_minutes);

  perform public.set_appointment_technicians(p_appointment_id, p_technician_ids);

  update public.appointments
  set scheduled_at = p_scheduled_at,
      duration_minutes = p_duration_minutes,
      pest_concern = nullif(trim(p_pest_concern), ''),
      service_type = nullif(trim(p_service_type), ''),
      service_location = nullif(trim(p_service_location), ''),
      technician_id = (select ids.technician_id
                       from unnest(coalesce(p_technician_ids, array[]::uuid[])) with ordinality as ids(technician_id, position)
                       where ids.technician_id is not null
                       order by ids.position limit 1),
      status = p_status,
      notes = nullif(trim(p_notes), ''),
      cancellation_reason = case when p_status = 'Cancelled' then nullif(trim(p_cancellation_reason), '') end,
      service_frequency = nullif(trim(p_service_frequency), ''),
      price = p_price,
      service_id = p_service_id
  where id = p_appointment_id
  returning * into updated;
  return updated;
end;
$$;


--
-- Name: update_inventory_batch(uuid, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_inventory_batch(p_batch_id uuid, p_lot_number text, p_expiration_date date) RETURNS public.inventory_batches
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.inventory_batches;
begin
  perform public.assert_inventory_admin();
  select * into target from public.inventory_batches b where b.id = p_batch_id for update;
  if target.id is null then raise exception 'That batch was not found.'; end if;
  if p_expiration_date is not null and p_expiration_date < target.received_date then
    raise exception 'The expiry cannot be before the batch was received.';
  end if;

  update public.inventory_batches b
    set lot_number = nullif(trim(coalesce(p_lot_number, '')), ''),
        expiration_date = p_expiration_date
    where b.id = p_batch_id
    returning * into target;
  return target;
end;
$$;


--
-- Name: update_plan_future(uuid, uuid, text, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_plan_future(p_plan_id uuid, p_from_appointment_id uuid, p_start_time text DEFAULT NULL::text, p_technician_ids uuid[] DEFAULT NULL::uuid[], p_service_ids uuid[] DEFAULT NULL::uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare plan_kind text;
declare from_start timestamptz;
declare visit public.appointments;
declare new_start timestamptz;
declare crew uuid[];
declare changed integer := 0;
begin
  perform public.assert_office();

  select kind into plan_kind from public.appointment_plans where id = p_plan_id;
  if plan_kind is null then raise exception 'Plan not found.'; end if;
  if plan_kind = 'MULTI_DAY' and p_start_time is not null then
    raise exception 'A multi-day job''s hours come from how it was split; move a single day instead.';
  end if;
  select scheduled_at into from_start from public.appointments where id = p_from_appointment_id and plan_id = p_plan_id;
  if from_start is null then raise exception 'That visit is not part of this plan.'; end if;

  for visit in
    select * from public.appointments
    where plan_id = p_plan_id and scheduled_at >= from_start
      and status not in ('Completed', 'Cancelled', 'In progress')
    order by scheduled_at
  loop
    new_start := case
      when p_start_time is null then visit.scheduled_at
      else ((visit.scheduled_at at time zone 'Asia/Manila')::date + p_start_time::time) at time zone 'Asia/Manila'
    end;
    if new_start <> visit.scheduled_at and new_start < now() - interval '5 minutes' then
      raise exception 'Visits cannot be moved into the past.';
    end if;

    select coalesce(p_technician_ids, array_agg(technician_id order by is_lead desc, assigned_at)) into crew
    from public.appointment_technicians where appointment_id = visit.id;

    perform public.assert_technicians_available(visit.id, crew, new_start, visit.duration_minutes);

    if new_start <> visit.scheduled_at then
      update public.appointments set scheduled_at = new_start where id = visit.id;
    end if;
    if p_technician_ids is not null then
      perform public.set_appointment_technicians(visit.id, p_technician_ids);
    end if;
    if p_service_ids is not null and cardinality(p_service_ids) > 0 then
      perform public.set_appointment_services(visit.id, p_service_ids);
    end if;
    changed := changed + 1;
  end loop;

  return changed;
end;
$$;


--
-- Name: update_role_account(uuid, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_role_account(session_token uuid, target_id uuid, new_name text, new_email text, new_phone text, new_role text, current_password text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  caller_id uuid;
  caller_role text;
  caller_password text;
  caller_password_hash text;
  target_role text;
  updated jsonb;
  move_result jsonb;
begin
  select id, role_name into caller_id, caller_role
    from role_account_for_session(session_token) limit 1;
  if caller_id is null then raise exception 'Not signed in.'; end if;

  select role_name into target_role from (
    select id, 'ADMIN'::text role_name from admins
    union all select id, 'STAFF'::text from staff
    union all select id, 'TECHNICIAN'::text from technicians
  ) accounts where id = target_id;
  if target_role is null then raise exception 'Account not found.'; end if;
  if caller_id <> target_id and caller_role <> 'ADMIN' then
    raise exception 'You do not have permission to edit accounts.';
  end if;
  if target_role = 'ADMIN' and caller_id <> target_id then
    raise exception 'Admins cannot modify other Admins.';
  end if;

  if caller_id = target_id then
    if new_email is distinct from (
      select email from admins where id = target_id
      union all select email from staff where id = target_id
      union all select email from technicians where id = target_id
    ) and nullif(current_password, '') is null then
      raise exception 'Enter your current password to change your email.';
    end if;

    if new_email is distinct from (
      select email from admins where id = target_id
      union all select email from staff where id = target_id
      union all select email from technicians where id = target_id
    ) then
      select password, password_hash into caller_password, caller_password_hash
        from (
          select password, password_hash from admins where id = target_id
          union all select password, password_hash from staff where id = target_id
          union all select password, password_hash from technicians where id = target_id
        ) credentials limit 1;
      -- Matches migration 044's rule: an empty stored credential never
      -- satisfies a check.
      if not (
        (nullif(caller_password, '') is not null and caller_password = current_password)
        or (nullif(caller_password_hash, '') is not null
            and caller_password_hash = crypt(current_password, caller_password_hash))
      ) then
        raise exception 'Current password is incorrect.';
      end if;
    end if;
  end if;

  if exists (select 1 from admins where id <> target_id and lower(email)=lower(new_email))
     or exists (select 1 from staff where id <> target_id and lower(email)=lower(new_email))
     or exists (select 1 from technicians where id <> target_id and lower(email)=lower(new_email)) then
    raise exception 'That email is already used by another account.';
  end if;

  if target_role = 'ADMIN' then
    update admins set name=new_name, email=new_email, phone=new_phone
      where id=target_id returning to_jsonb(admins.*) into updated;
  elsif target_role = 'STAFF' then
    update staff set name=new_name, email=new_email, phone=new_phone
      where id=target_id returning to_jsonb(staff.*) into updated;
  else
    update technicians set name=new_name, email=new_email, phone=new_phone
      where id=target_id returning to_jsonb(technicians.*) into updated;
  end if;

  if new_role is not null and upper(new_role) <> target_role then
    move_result := public.move_account_role(session_token, target_id, new_role);
    return move_result;
  end if;

  return updated || jsonb_build_object('role', target_role);
end;
$$;


--
-- Name: update_role_account_avatar(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_role_account_avatar(session_token uuid, target_id uuid, new_avatar_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  caller_id uuid;
  caller_role text;
  target_role text;
  updated jsonb;
begin
  select id, role_name
    into caller_id, caller_role
    from role_account_for_session(session_token)
   limit 1;

  if caller_id is null then
    raise exception 'Not signed in.';
  end if;

  if caller_id <> target_id and caller_role <> 'ADMIN' then
    raise exception 'Only administrators can update another user''s profile picture.';
  end if;

  select role_name
    into target_role
    from (
      select id, 'ADMIN'::text as role_name from admins
      union all
      select id, 'STAFF'::text from staff
      union all
      select id, 'TECHNICIAN'::text from technicians
    ) accounts
   where id = target_id;

  if target_role is null then
    raise exception 'Account not found.';
  end if;

  if target_role = 'ADMIN' then
    update admins
       set avatar_url = nullif(new_avatar_url, '')
     where id = target_id
     returning to_jsonb(admins.*) into updated;
  elsif target_role = 'STAFF' then
    update staff
       set avatar_url = nullif(new_avatar_url, '')
     where id = target_id
     returning to_jsonb(staff.*) into updated;
  else
    update technicians
       set avatar_url = nullif(new_avatar_url, '')
     where id = target_id
     returning to_jsonb(technicians.*) into updated;
  end if;

  return updated || jsonb_build_object('role', target_role);
end;
$$;


--
-- Name: validate_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_session(session_token uuid) RETURNS TABLE(id uuid, name text, username text, email text, phone text, role text, status public.account_status, is_primary boolean, last_login_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select a.id, a.name, coalesce(a.username, a.email), a.email, a.phone,
         'ADMIN'::text, a.status, a.is_primary, a.last_login_at, a.created_at, a.updated_at
    from sessions s join admins a on a.id = s.user_id
   where s.token = session_token and s.user_role = 'ADMIN' and s.expires_at > now() and a.status = 'ACTIVE'
  union all
  select a.id, a.name, coalesce(a.username, a.email), a.email, a.phone,
         'STAFF'::text, a.status, false, a.last_login_at, a.created_at, a.updated_at
    from sessions s join staff a on a.id = s.user_id
   where s.token = session_token and s.user_role = 'STAFF' and s.expires_at > now() and a.status = 'ACTIVE'
  union all
  select a.id, a.name, coalesce(a.username, a.email), a.email, a.phone,
         'TECHNICIAN'::text, a.status, false, a.last_login_at, a.created_at, a.updated_at
    from sessions s join technicians a on a.id = s.user_id
   where s.token = session_token and s.user_role = 'TECHNICIAN' and s.expires_at > now() and a.status = 'ACTIVE';
$$;


--
-- Name: void_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_invoice(p_invoice_id uuid, p_reason text) RETURNS public.invoices
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare target public.invoices;
begin
  perform public.assert_billing_office();
  if public.current_account_role() <> 'ADMIN' then raise exception 'Only an admin can void an invoice.'; end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then raise exception 'Write why the invoice is being voided.'; end if;
  select * into target from public.invoices i where i.id = p_invoice_id for update;
  if target.id is null then raise exception 'That invoice was not found.'; end if;
  if target.status = 'VOID' then raise exception 'That invoice was already voided.'; end if;
  if exists (
    select 1 from public.payments p
    where p.invoice_id = target.id and p.reversed_at is null
      and not (p.method = 'CHECK' and p.check_status = 'BOUNCED')
  ) then
    raise exception 'Invoice % has payments on it. Reverse them first.', target.reference;
  end if;

  update public.invoices i set status = 'VOID', voided_at = now(), voided_by = public.current_account_id(), void_reason = trim(p_reason)
  where i.id = target.id returning * into target;
  -- Free the visits and extras for a corrected invoice. The void keeps its
  -- lines, which still name them, as the record of what it billed.
  update public.appointments a set invoice_id = null where a.invoice_id = target.id;
  update public.appointment_extras e set invoice_id = null where e.invoice_id = target.id;
  return target;
end;
$$;


--
-- Name: warranty_checkup_period(text, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warranty_checkup_period(p_source_type text, p_source_id uuid, p_day date) RETURNS TABLE(period_index integer, starts_on date, ends_on date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_months integer;
  v_frequency text;
  v_step integer;
  v_start date;
  i integer;
  v_open date;
  v_close date;
begin
  if upper(p_source_type) = 'CONTRACT' then
    select c.warranty_months, c.checkup_frequency into v_months, v_frequency from public.contracts c where c.id = p_source_id;
  else
    select q.warranty_months, q.checkup_frequency into v_months, v_frequency from public.quotes q where q.id = p_source_id;
  end if;
  v_step := case upper(coalesce(v_frequency, '')) when 'MONTHLY' then 1 when 'QUARTERLY' then 3 end;
  if v_step is null or v_months is null or p_day is null then return; end if;
  select w.starts_on into v_start from public.warranty_window(p_source_type, p_source_id) w;
  if v_start is null then return; end if;
  for i in 0 .. (v_months / v_step) - 1 loop
    v_open := (v_start + make_interval(months => i * v_step))::date;
    v_close := (v_start + make_interval(months => (i + 1) * v_step))::date;
    if p_day > v_open and p_day <= v_close then
      return query select i, v_open + 1, v_close;
      return;
    end if;
  end loop;
end;
$$;


--
-- Name: warranty_start(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warranty_start(p_source_type text, p_source_id uuid) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_start date;
begin
  if upper(p_source_type) = 'CONTRACT' then
    select (c.activated_at at time zone 'Asia/Manila')::date into v_start
    from public.contracts c where c.id = p_source_id and c.status in ('ACTIVE', 'ENDED');
  else
    if not exists (select 1 from public.quotes q where q.id = p_source_id and q.status = 'APPROVED') then return null; end if;
    select min((coalesce(r.signed_at, r.submitted_at, a.scheduled_at) at time zone 'Asia/Manila')::date) into v_start
    from public.appointments a
    left join public.appointment_reports r on r.appointment_id = a.id
    where a.quote_id = p_source_id and a.status = 'Completed' and a.warranty_kind is null;
  end if;
  return v_start;
end;
$$;


--
-- Name: warranty_window(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.warranty_window(p_source_type text, p_source_id uuid) RETURNS TABLE(starts_on date, ends_on date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_months integer;
  v_start date;
begin
  if upper(p_source_type) = 'CONTRACT' then
    select c.warranty_months, (c.activated_at at time zone 'Asia/Manila')::date into v_months, v_start
    from public.contracts c where c.id = p_source_id and c.status in ('ACTIVE', 'ENDED');
  else
    select q.warranty_months into v_months from public.quotes q where q.id = p_source_id and q.status = 'APPROVED';
    select min((coalesce(r.signed_at, r.submitted_at, a.scheduled_at) at time zone 'Asia/Manila')::date) into v_start
    from public.appointments a
    left join public.appointment_reports r on r.appointment_id = a.id
    where a.quote_id = p_source_id and a.status = 'Completed' and a.warranty_kind is null;
  end if;
  if v_months is null or v_start is null then return; end if;
  return query select v_start, (v_start + make_interval(months => v_months))::date;
end;
$$;


--
-- Name: write_off_expired_batch(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_off_expired_batch(p_batch_id uuid, p_note text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  target public.inventory_batches;
  actor_name text;
  actor_account_id uuid;
  today date := (now() at time zone 'Asia/Manila')::date;
begin
  perform public.assert_inventory_admin();

  select * into target from public.inventory_batches b where b.id = p_batch_id for update;
  if target.id is null then raise exception 'That batch was not found.'; end if;
  perform 1 from public.inventory i where i.id = target.item_id for update;
  if target.expiration_date is null or target.expiration_date >= today then
    raise exception 'Only an expired batch can be written off. Use Stock Out for missing or damaged stock.';
  end if;
  if target.quantity <= 0 then raise exception 'That batch has nothing left on the shelf.'; end if;

  select r.id, coalesce(a.name, s.name, t.name) into actor_account_id, actor_name
  from public.role_account_for_session(nullif(current_setting('request.headers', true)::json->>'x-session-token', '')::uuid) r
  left join public.admins a on a.id = r.id left join public.staff s on s.id = r.id left join public.technicians t on t.id = r.id limit 1;

  insert into public.inventory_movements (
    item_id, amount, quantity_delta, movement_date, reference, actor, actor_id,
    movement_type, stock_out_reason, note, batch_id, batch_number
  )
  values (
    target.item_id, target.quantity, -target.quantity, today,
    'Expired ' || to_char(target.expiration_date, 'Mon DD, YYYY') || ' — written off', actor_name, actor_account_id,
    'OUT', 'EXPIRED', nullif(trim(coalesce(p_note, '')), ''), target.id, coalesce(target.lot_number, target.reference)
  );

  update public.inventory i set quantity = i.quantity - target.quantity where i.id = target.item_id;
  update public.inventory_batches b set quantity = 0, written_off_at = now() where b.id = target.id;
  return target.quantity;
end;
$$;


