--
-- Name: client_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    name text NOT NULL,
    mime_type text,
    size_bytes bigint,
    storage_path text NOT NULL,
    uploaded_by uuid,
    uploaded_at timestamp with time zone DEFAULT now() NOT NULL,
    category text DEFAULT 'OTHER'::text NOT NULL,
    CONSTRAINT client_documents_category_check CHECK ((category = ANY (ARRAY['CLIENT_ID'::text, 'CONTRACT'::text, 'PROPERTY'::text, 'PERMIT'::text, 'OTHER'::text])))
);


--
-- Name: client_reference_seq; Type: SEQUENCE; Schema: public; Owner: -
--

CREATE SEQUENCE public.client_reference_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: clients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clients (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    email text,
    phone text,
    address text,
    classification public.client_classification DEFAULT 'RESIDENTIAL'::public.client_classification NOT NULL,
    classification_other text,
    pest_concern text,
    source text,
    status public.client_status DEFAULT 'ACTIVE'::public.client_status NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    archived_at timestamp with time zone,
    archived_by uuid,
    reference text DEFAULT ('TPC-C-'::text || lpad((nextval('public.client_reference_seq'::regclass))::text, 4, '0'::text)),
    service_notes text,
    skip_payment_check boolean DEFAULT false NOT NULL,
    category text,
    checkup_frequency text,
    CONSTRAINT clients_category_check CHECK (((category IS NULL) OR (category = ANY (ARRAY['CHEMICAL'::text, 'NON_CHEMICAL'::text])))),
    CONSTRAINT clients_checkup_frequency_check CHECK (((checkup_frequency IS NULL) OR (checkup_frequency = ANY (ARRAY['MONTHLY'::text, 'QUARTERLY'::text])))),
    CONSTRAINT clients_email_check CHECK (((email IS NULL) OR (email = ''::text) OR (email ~* '^[A-Za-z0-9._+%-]+@[A-Za-z0-9.-]+[.][A-Za-z]+$'::text))),
    CONSTRAINT clients_phone_check CHECK (((phone IS NULL) OR (phone = ''::text) OR (phone ~ '^09[0-9]{9}$'::text)))
);


--
-- Name: COLUMN clients.service_notes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.service_notes IS 'Standing service instructions for this client: access, contacts, restrictions. Shown on every booking.';


--
-- Name: COLUMN clients.category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.category IS 'CHEMICAL or NON_CHEMICAL (075); null until set.';


--
-- Name: COLUMN clients.checkup_frequency; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.checkup_frequency IS 'MONTHLY or QUARTERLY (075): how often the client''s checkups are booked.';


--
-- Name: inventory_movements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inventory_movements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    item_id uuid NOT NULL,
    amount numeric NOT NULL,
    movement_date date NOT NULL,
    reference text,
    actor text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id uuid,
    intake_branch_or_station text,
    purchase_reference text,
    idempotency_key uuid,
    unit_cost numeric DEFAULT 0,
    total_cost numeric DEFAULT 0,
    movement_type text DEFAULT 'IN'::text NOT NULL,
    quantity_delta numeric,
    appointment_id uuid,
    batch_number text,
    entered_amount numeric,
    entered_unit text,
    conversion_factor numeric,
    stock_out_reason text,
    technician_id uuid,
    note text,
    batch_key uuid,
    expiration_date date,
    checkout_id uuid,
    for_appointment_id uuid,
    return_reason text,
    custody_closed_at timestamp with time zone,
    batch_id uuid,
    handover_signature_path text,
    receiver_signature_path text,
    handover_group uuid,
    handed_over_by_name text,
    CONSTRAINT inventory_movements_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT inventory_movements_checkout_link_check CHECK (((checkout_id IS NULL) OR (stock_out_reason = ANY (ARRAY['APPOINTMENT'::text, 'MISSING'::text, 'DAMAGED'::text])) OR (movement_type = 'RETURN'::text))),
    CONSTRAINT inventory_movements_checkout_technician_check CHECK (((technician_id IS NULL) OR (stock_out_reason = 'TECHNICIAN_CHECKOUT'::text) OR (movement_type = 'RETURN'::text) OR ((checkout_id IS NOT NULL) AND (stock_out_reason = ANY (ARRAY['MISSING'::text, 'DAMAGED'::text]))))),
    CONSTRAINT inventory_movements_for_appointment_check CHECK (((for_appointment_id IS NULL) OR (stock_out_reason = 'TECHNICIAN_CHECKOUT'::text) OR (movement_type = 'RETURN'::text))),
    CONSTRAINT inventory_movements_movement_type_check CHECK ((movement_type = ANY (ARRAY['IN'::text, 'OUT'::text, 'CORRECTION'::text, 'RETURN'::text]))),
    CONSTRAINT inventory_movements_return_reason_check CHECK ((((movement_type = 'RETURN'::text) AND (return_reason = ANY (ARRAY['VISIT_CANCELLED'::text, 'LEFTOVER'::text, 'NOT_NEEDED'::text, 'OTHER'::text])) AND (checkout_id IS NOT NULL)) OR ((movement_type <> 'RETURN'::text) AND (return_reason IS NULL)))),
    CONSTRAINT inventory_movements_stock_out_reason_check CHECK (((stock_out_reason IS NULL) OR ((movement_type = 'OUT'::text) AND (stock_out_reason = ANY (ARRAY['APPOINTMENT'::text, 'TECHNICIAN_CHECKOUT'::text, 'MISSING'::text, 'DAMAGED'::text, 'EXPIRED'::text])))))
);


--
-- Name: COLUMN inventory_movements.batch_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.batch_number IS 'Manufacturer lot/batch code read off the container at the time of use. Recall traceability.';


--
-- Name: COLUMN inventory_movements.entered_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.entered_amount IS 'Quantity as the user typed it, in entered_unit. Null when they typed the base unit.';


--
-- Name: COLUMN inventory_movements.entered_unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.entered_unit IS 'Unit the quantity was entered in, e.g. "gal" for an item tracked in "L".';


--
-- Name: COLUMN inventory_movements.conversion_factor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.conversion_factor IS 'Multiplier applied to entered_amount to reach amount. 1 when no conversion took place.';


--
-- Name: COLUMN inventory_movements.stock_out_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.stock_out_reason IS 'Why stock left: APPOINTMENT, TECHNICIAN_CHECKOUT, MISSING or DAMAGED. Null on IN and CORRECTION.';


--
-- Name: COLUMN inventory_movements.technician_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.technician_id IS 'Who the stock was checked out to. Only set for TECHNICIAN_CHECKOUT.';


--
-- Name: COLUMN inventory_movements.batch_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.batch_key IS 'Groups the rows written by one stock_in_batch() call. Shared by every row of the batch.';


--
-- Name: COLUMN inventory_movements.expiration_date; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.expiration_date IS 'Stock In only: the expiry printed on this delivery. Copied onto inventory.expiration_date by stock_in_batch().';


--
-- Name: COLUMN inventory_movements.checkout_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.checkout_id IS 'The technician checkout this row settles: visit materials drawn from it, or stock returned from it.';


--
-- Name: COLUMN inventory_movements.for_appointment_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.for_appointment_id IS 'On a checkout, the visit it was taken for; on a return, the visit it was taken for or the one that was cancelled.';


--
-- Name: COLUMN inventory_movements.return_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.return_reason IS 'Why stock came back: VISIT_CANCELLED, LEFTOVER, NOT_NEEDED or OTHER. Only on RETURN rows.';


--
-- Name: COLUMN inventory_movements.custody_closed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.custody_closed_at IS 'Set on checkouts from before migration 054: settled as they were, not drawn on by later visits.';


--
-- Name: COLUMN inventory_movements.batch_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inventory_movements.batch_id IS 'The chemical batch this movement took from or put into (migration 055).';


--
-- Name: invoice_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoice_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    invoice_id uuid NOT NULL,
    "position" integer NOT NULL,
    kind text NOT NULL,
    service_id uuid,
    item_id uuid,
    appointment_id uuid,
    extra_id uuid,
    description text NOT NULL,
    quantity numeric NOT NULL,
    unit text,
    unit_price numeric NOT NULL,
    amount numeric NOT NULL,
    CONSTRAINT invoice_lines_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT invoice_lines_description_check CHECK (((char_length(description) >= 1) AND (char_length(description) <= 300))),
    CONSTRAINT invoice_lines_kind_check CHECK ((kind = ANY (ARRAY['SERVICE'::text, 'MATERIAL'::text, 'EXTRA'::text]))),
    CONSTRAINT invoice_lines_quantity_check CHECK (((quantity > (0)::numeric) AND (quantity <= (1000000)::numeric))),
    CONSTRAINT invoice_lines_unit_price_check CHECK (((unit_price >= (0)::numeric) AND (unit_price <= 999999.99)))
);


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    recipient_id uuid NOT NULL,
    appointment_id uuid,
    message text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    read_at timestamp with time zone
);


--
-- Name: quote_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.quote_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    quote_id uuid NOT NULL,
    "position" integer NOT NULL,
    kind text NOT NULL,
    service_id uuid,
    item_id uuid,
    description text NOT NULL,
    quantity numeric NOT NULL,
    unit text,
    unit_price numeric NOT NULL,
    amount numeric NOT NULL,
    CONSTRAINT quote_lines_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT quote_lines_description_check CHECK (((char_length(description) >= 1) AND (char_length(description) <= 300))),
    CONSTRAINT quote_lines_kind_check CHECK ((kind = ANY (ARRAY['SERVICE'::text, 'MATERIAL'::text, 'EXTRA'::text]))),
    CONSTRAINT quote_lines_quantity_check CHECK (((quantity > (0)::numeric) AND (quantity <= (1000000)::numeric))),
    CONSTRAINT quote_lines_unit_price_check CHECK (((unit_price >= (0)::numeric) AND (unit_price <= 999999.99)))
);


--
-- Name: services; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.services (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    description text,
    default_price numeric,
    default_duration_minutes integer,
    sort_order integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pricing_mode text DEFAULT 'FLAT'::text NOT NULL,
    area_rate numeric,
    minimum_charge numeric,
    deposit_percent numeric DEFAULT 0 NOT NULL,
    skip_payment_check boolean DEFAULT false NOT NULL,
    follow_up_price numeric(12,2),
    category text DEFAULT 'CHEMICAL'::text NOT NULL,
    system_key text,
    CONSTRAINT services_area_pricing_check CHECK ((((area_rate IS NULL) OR ((area_rate >= (0)::numeric) AND (area_rate <= 999999.99))) AND ((minimum_charge IS NULL) OR ((minimum_charge >= (0)::numeric) AND (minimum_charge <= 999999.99))) AND ((pricing_mode <> 'AREA'::text) OR (area_rate IS NOT NULL)))),
    CONSTRAINT services_category_check CHECK ((category = ANY (ARRAY['CHEMICAL'::text, 'NON_CHEMICAL'::text]))),
    CONSTRAINT services_default_duration_check CHECK (((default_duration_minutes IS NULL) OR ((default_duration_minutes >= 15) AND (default_duration_minutes <= 1440)))),
    CONSTRAINT services_default_price_check CHECK (((default_price IS NULL) OR ((default_price >= (0)::numeric) AND (default_price <= 999999.99)))),
    CONSTRAINT services_deposit_percent_check CHECK (((deposit_percent >= (0)::numeric) AND (deposit_percent <= (100)::numeric))),
    CONSTRAINT services_follow_up_price_check CHECK (((follow_up_price IS NULL) OR ((follow_up_price >= (0)::numeric) AND (follow_up_price <= 999999.99)))),
    CONSTRAINT services_name_check CHECK (((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 120))),
    CONSTRAINT services_pricing_mode_check CHECK ((pricing_mode = ANY (ARRAY['FLAT'::text, 'AREA'::text]))),
    CONSTRAINT services_system_key_check CHECK (((system_key IS NULL) OR (system_key = ANY (ARRAY['CHECKUP'::text, 'FOLLOW_UP'::text, 'INSPECTION'::text]))))
);


--
-- Name: TABLE services; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.services IS 'Admin-managed service catalog. appointments.service_type keeps the name as booked; service_id only links for prefill.';


--
-- Name: COLUMN services.is_active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.services.is_active IS 'False retires a service: it leaves the booking form but appointments already booked under it are untouched.';


--
-- Name: COLUMN services.area_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.services.area_rate IS 'Pesos per square metre, for pricing_mode AREA.';


--
-- Name: COLUMN services.minimum_charge; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.services.minimum_charge IS 'The least an AREA-priced service charges, however small the area.';


--
-- Name: COLUMN services.deposit_percent; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.services.deposit_percent IS 'The down payment a quote for this service asks for by default, as a % of its total.';


--
-- Name: COLUMN services.follow_up_price; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.services.follow_up_price IS 'Price of a follow-up visit after this service (migration 068). Null: the Follow-up Visit service''s own price.';


--
-- Name: COLUMN services.category; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.services.category IS 'CHEMICAL or NON_CHEMICAL (075). A visit is Chemical if any of its services is.';


--
-- Name: sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sessions (
    token uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '12:00:00'::interval) NOT NULL,
    user_role text
);


--
-- Name: shared_login_accounts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.shared_login_accounts (
    id uuid NOT NULL,
    note text,
    added_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE shared_login_accounts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.shared_login_accounts IS 'Accounts that may be signed in on several devices at once (check_login leaves their other sessions alone). Empty = one device per account for everyone.';


--
-- Name: staff; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.staff (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    phone text,
    email text NOT NULL,
    password text DEFAULT ''::text NOT NULL,
    status public.account_status DEFAULT 'ACTIVE'::public.account_status NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    username text,
    password_hash text,
    last_login_at timestamp with time zone,
    avatar_url text,
    reference text DEFAULT ('TPC-S-'::text || lpad((nextval('public.account_reference_seq'::regclass))::text, 3, '0'::text))
);


--
-- Name: system_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    actor_id uuid,
    actor_name text NOT NULL,
    message text NOT NULL,
    type text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_role text NOT NULL,
    CONSTRAINT system_logs_type_check CHECK ((type = ANY (ARRAY['auth'::text, 'admin'::text, 'client'::text, 'document'::text, 'inventory'::text])))
);


--
-- Name: TABLE system_logs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.system_logs IS 'The system activity log. Written only by add_system_log(); never updated or deleted.';


--
-- Name: technician_absences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.technician_absences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    technician_id uuid NOT NULL,
    starts_on date NOT NULL,
    ends_on date NOT NULL,
    reason text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT technician_absences_dates_check CHECK ((ends_on >= starts_on))
);


--
-- Name: TABLE technician_absences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.technician_absences IS 'A technician out of work from starts_on to ends_on (Asia/Manila dates, both included). Nobody can book them in that time.';


