--
-- Name: COLUMN treatment_methods.is_active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.treatment_methods.is_active IS 'False retires a method: it disappears from the report form but still resolves to a label on reports that already reference it.';


--
-- Name: treatment_methods_id_seq; Type: SEQUENCE; Schema: public; Owner: -
